const MONEY_PAGES = {"ai-agency-uk":{"spec":{"status":"approved","kind":"money","meta":{"slug":"ai-agency-uk","title":"AI Agency UK | AI Software Engineering Partner | 7code","metaDescription":"AI agency for UK companies that need software built, not marketing campaigns. We map the process, build the AI, and ship it with evals and guardrails.","canonical":"https://www.7code.tech/ai-agency-uk/","ogImage":"/og/ai-agency-uk.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"ai agency uk","secondaryKeywords":["ai company uk","ai agency london","artificial intelligence agency uk","ai solutions company uk","best ai agency uk"],"icpSegment":"smb-automation","searchIntent":"commercial-investigation","flywheelStage":"find","difficultyNote":"Intent on this term is genuinely mixed. In the UK market \"AI agency\" is used by marketing automation shops, chatbot resellers, generalist consultancies and engineering firms, and the SERP reflects all four. That makes it a parity term rather than a conversion term: worth holding for visibility, but the page's real job is to disambiguate fast and route the visitor to the deeper page that matches what they came for. Written deliberately as a router. Qualitative assessment from manual SERP inspection. No verified volume data available.\n"},"cta":{"label":"Book an Operational Quick Scan","action":"booking","href":"/book/quick-scan","reassurance":"45 minutes. No prep needed. You'll leave knowing whether your problem is an AI problem, and what it would take to fix it."},"blocks":["hero","trustStrip","diagnosis","successHorizon","proof","cta","whatWeBuild","howWeDeliver","package","cta","pointOfView","faq","close"],"proof":[{"caseStudySlug":"hera","metric":"Clinical intake from days to minutes — RAG-verified, MVP in 3 months","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"LLM & agent development","href":"/service/llm-agent-development"}]},{"caseStudySlug":"lidl-road-safety","metric":"Road-safety programme platform delivered for Lidl Romania","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI automation","href":"/service/ai-automation"}]}],"internalLinks":[{"anchor":"AI automation agency","href":"/ai-automation-agency-uk","placement":"whatWeBuild"},{"anchor":"AI development company","href":"/ai-development-company-uk","placement":"whatWeBuild"},{"anchor":"AI agent development","href":"/ai-agent-development-company","placement":"whatWeBuild"},{"anchor":"AI consultancy","href":"/ai-consultancy-uk","placement":"whatWeBuild"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatWeBuild"},{"anchor":"Operational Quick Scan","href":"/packages/operational-quick-scan","placement":"package"},{"anchor":"Automation Pilot","href":"/packages/automation-pilot","placement":"package"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"faq"},{"anchor":"Production MVP","href":"/mvp-development-agency-uk","placement":"faq"},{"anchor":"staff augmentation","href":"/staff-augmentation-company-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"The AI agency UK teams hire when they need software built","sub":"We are engineers, not a marketing shop with an AI page. If you need a model in production, an agent doing real work, or an honest answer on whether AI helps at all, start here."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"diagnosis":{"rich":[{"type":"h2","text":"You searched \"AI agency\" and got four different businesses"},{"type":"p","inline":[{"type":"text","value":"The first result runs paid social and has added an AI page. The second resells a chatbot on someone else's platform. The third is a consultancy that will produce a strategy deck and then introduce you to an implementation partner. The fourth might actually write code, but the site does not say so clearly enough for you to be sure."}]},{"type":"p","inline":[{"type":"text","value":"All four call themselves an AI agency. None of the sites make it easy to work out which one builds software, which one advises, and which one is a reseller with a good landing page."}]},{"type":"p","inline":[{"type":"text","value":"That is not your failure to research. It is a category that has not settled, and it costs UK buyers weeks of calls that end in \"so, to be clear, do you build this yourselves?\""}]},{"type":"p","inline":[{"type":"text","value":"Here is our answer up front. We are an AI-native product engineering partner. We design, build and operate AI software: LLM features, agent workflows and the infrastructure underneath them. We do not run marketing campaigns. This page exists to say that clearly, then point you at the right part of what we do."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"successHorizon":{"heading":"What this looks like from where you're sitting","horizons":[{"type":"horizon","label":"In 3 weeks","inline":[{"type":"text","value":"you have a written map of where AI would actually pay in your business, ranked by value and effort, with an honest estimate against each. If nothing on the list is worth building yet, that is what the document says."}]},{"type":"horizon","label":"In 3 months","inline":[{"type":"text","value":"one thing is live and running on your real data. Your team can see what it did, why it decided that, and what it cost to run. Edge cases route to a person rather than disappearing."}]},{"type":"horizon","label":"In 12 months","inline":[{"type":"text","value":"AI is part of how a department operates rather than a project with a name. It is documented, owned by your team, running on infrastructure you control, and monitored well enough that you find out about drift before your customers do."}]}]},"proof":{"rich":[{"type":"h2","text":"Two we can talk about"},{"type":"p","inline":[{"type":"bold","value":"Hera Health Tech"},{"type":"text","value":" — clinical onboarding that used to take days now takes minutes. Built as a RAG-verified AI intake flow with a human review step, MVP shipped in three months. Tags: "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"LLM & agent development","href":"/service/llm-agent-development"},{"type":"text","value":" → "},{"type":"link","label":"Read the Hera case study","href":"/case-study/hera"}]},{"type":"p","inline":[{"type":"bold","value":"Lidl Romania"},{"type":"text","value":" — a road-safety programme platform delivered for a client with enterprise procurement and enterprise security review. Evidence that the engineering survives contact with a large buyer. Tags: "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" · "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" → "},{"type":"link","label":"Read the Lidl case study","href":"/case-study/lidl-road-safety"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book an Operational Quick Scan"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatWeBuild":{"rich":[{"type":"h2","text":"Four things people mean by \"AI agency\" — and where to go for each"},{"type":"p","inline":[{"type":"text","value":"Most visitors to this page want one of four things. Each has its own page with the detail, the process and the pricing for that specific work."}]},{"type":"ul","items":[[{"type":"bold","value":"You want manual work to stop being manual."},{"type":"text","value":" Intake, triage, routing, approvals, reporting, document handling. That is process automation with AI inside it, and it is our biggest practice. → "},{"type":"link","label":"AI automation agency","href":"/ai-automation-agency-uk"}],[{"type":"bold","value":"You want AI features inside a product you are building or already run."},{"type":"text","value":" Retrieval over your own content, generation with guardrails, classification, search that understands intent, evals to keep it honest. → "},{"type":"link","label":"AI development company","href":"/ai-development-company-uk"}],[{"type":"bold","value":"You want agents that take actions, not chat windows."},{"type":"text","value":" Systems that read a document, decide something, act in a real system and escalate what they should not decide alone. → "},{"type":"link","label":"AI agent development","href":"/ai-agent-development-company"}],[{"type":"bold","value":"You want to know whether any of this is worth doing."},{"type":"text","value":" A senior engineering read on feasibility, cost, data readiness and sequencing, delivered as a document you own rather than a slide deck. → "},{"type":"link","label":"AI consultancy","href":"/ai-consultancy-uk"}]]},{"type":"p","inline":[{"type":"text","value":"And the two things underneath all four, which nobody searches for and everybody needs:"}]},{"type":"ul","items":[[{"type":"bold","value":"[System integrations](/service/system-integrations)"},{"type":"text","value":" — the connective work that makes any of the above possible. APIs, middleware, data sync between tools built in different decades."}],[{"type":"bold","value":"Production hardening"},{"type":"text","value":" — evals, guardrails, traces, cost dashboards and rollback. This is the difference between a demo that impressed a board and something a business runs on."}]]},{"type":"p","inline":[{"type":"text","value":"If you are not sure which of the four you need, book the call and we will tell you. That conversation takes twenty minutes and it is free."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howWeDeliver":{"rich":[{"type":"h2","text":"How we work, and what that protects you from"},{"type":"ul","items":[[{"type":"bold","value":"We map before we build."},{"type":"text","value":" Most failed AI projects skipped this step. A use case that demos well is not the same as a process that is understood, and automating a broken process makes it broken faster."}],[{"type":"bold","value":"Senior engineers only, and the same ones throughout."},{"type":"text","value":" The person on your first call is the person building it. No account manager layer, no handover to juniors once the contract is signed."}],[{"type":"bold","value":"Model agnostic."},{"type":"text","value":" GPT, Claude, Gemini or an open-weight model inside your own environment. We choose per use case and per data-sensitivity requirement, not per vendor relationship. That also means we are not defending a partner tier when a cheaper model would do."}],[{"type":"bold","value":"Evals and observability by default."},{"type":"text","value":" Every AI step ships with a test set, a guardrail, a trace and a cost dashboard. Non-deterministic software without measurement is not production software."}],[{"type":"bold","value":"You own everything."},{"type":"text","value":" Code, prompts, eval suites, infrastructure config and documentation, running in your cloud account. Nothing here requires us to keep existing."}],[{"type":"bold","value":"Your data stays in the EU."},{"type":"text","value":" We are an EU company delivering from Romania. Data residency, GDPR posture and a DPA are settled before the first line of code, not after a security questionnaire arrives."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"Start with the scan, not the build"},{"type":"p","inline":[{"type":"bold","value":"Operational Quick Scan — 2 to 3 weeks"}]},{"type":"p","inline":[{"type":"text","value":"We sit with the people who do the work, map what actually happens, and come back with an opportunity map: where AI would pay, what each option would cost, what each would return, and in what order to do them."}]},{"type":"p","inline":[{"type":"text","value":"You get a written deliverable you own, whether or not you build anything with us. If the answer is that nothing here is worth automating yet, that is what it will say, and you will have spent a few thousand euros rather than six figures finding out."}]},{"type":"p","inline":[{"type":"bold","value":"Typically €4,500–€6,000."},{"type":"text","value":" What moves the number is how many processes are in scope and how many systems each one touches."}]},{"type":"p","inline":[{"type":"text","value":"→ "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":" · most clients who proceed then run an "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":" on the highest-value item from the map."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"pointOfView":{"rich":[{"type":"h2","text":"Our point of view"},{"type":"p","inline":[{"type":"text","value":"\"AI agency\" is a label the market has not agreed on, and the ambiguity is doing real damage to buyers. A firm that runs your paid social and a firm that ships a retrieval pipeline into production are not the same kind of business. They need different skills, different contracts and different people in the room."}]},{"type":"p","inline":[{"type":"text","value":"Our view is that AI work is software engineering. The model is one component in a system that also needs data plumbing, error handling, permissions, monitoring, rollback and a cost ceiling. Teams that treat the model as the whole product ship impressive demos and then spend a year discovering the other eighty percent."}]},{"type":"p","inline":[{"type":"text","value":"We would rather be described narrowly and accurately than broadly and vaguely. So: we build AI software. We advise on it when advice is what is needed, and we say no when the honest answer is that a spreadsheet and one fixed integration would solve the problem for a tenth of the cost."}]},{"type":"p","inline":[{"type":"bold","value":"Who we are not for:"},{"type":"text","value":" if you are looking for AI-assisted marketing, content generation at volume, or campaign automation, we are the wrong firm and we will say so on the first call rather than stretching to fit. We build software. Good marketing agencies exist and we are not one."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does working with an AI agency actually cost?","objection":"price","answerInline":[{"type":"text","value":"It depends on scope, but these are the bands we work in. A process audit and opportunity map, the "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":", is typically "},{"type":"bold","value":"€4,500–€6,000"},{"type":"text","value":" over two to three weeks. A deeper readiness and sequencing piece, the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":", usually sits between "},{"type":"bold","value":"€9,000 and €14,000"},{"type":"text","value":" over four to six weeks. Building one workflow end to end, an "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":", typically runs "},{"type":"bold","value":"€15,000–€25,000"},{"type":"text","value":" over six to ten weeks. A full AI product build, the "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":", is usually "},{"type":"bold","value":"€40,000–€90,000"},{"type":"text","value":" over three to five months. What moves the number is the number of systems involved and how clean your data is. We break it down per workflow during the scan so you can drop anything that does not pay for itself. More detail in "},{"type":"link","label":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"Are you a marketing agency that does AI?","objection":"other","answerInline":[{"type":"text","value":"No. We are a software engineering firm. We do not run campaigns, buy media, write ad copy or manage your content calendar. What we build is software with AI inside it: automated workflows, agents, retrieval systems, AI features inside products. If your need is marketing-side, we will tell you on the first call instead of taking the project."}]},{"question":"Do you build it yourselves, or subcontract?","objection":"seniority","answerInline":[{"type":"text","value":"We build it. The engineers are employed by us, in Cluj-Napoca, and the person you meet on the first call is on the build. There is no delivery partner behind the curtain and no account manager layer between you and the people writing the code. You can meet the engineer before you commit, and we would rather you did."}]},{"question":"Which of your pages should I actually be on?","objection":"other","answerInline":[{"type":"text","value":"If the problem is manual operational work, go to the "},{"type":"link","label":"AI automation agency","href":"/ai-automation-agency-uk"},{"type":"text","value":" page. If you are adding AI to a product, "},{"type":"link","label":"AI development company","href":"/ai-development-company-uk"},{"type":"text","value":". If you want systems that take actions rather than answer questions, "},{"type":"link","label":"AI agent development","href":"/ai-agent-development-company"},{"type":"text","value":". If you need a decision before a build, "},{"type":"link","label":"AI consultancy","href":"/ai-consultancy-uk"},{"type":"text","value":". If none of those quite fit, book the call and describe the problem in plain terms; routing you correctly takes about twenty minutes."}]},{"question":"How long until we see something working?","objection":"timeline","answerInline":[{"type":"text","value":"The scan produces a written deliverable in two to three weeks. A first automated workflow is usually live six to ten weeks from kickoff. A full product build runs three to five months. We deliberately pick an early win your team can watch working, rather than disappearing for two quarters and returning with a platform. See "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" for the sequence."}]},{"question":"We tried an AI tool last year and it did not work. Why would this be different?","objection":"failed-before","answerInline":[{"type":"text","value":"You are not unusual, and the cause is usually the same. Someone picked a use case because it demoed well, not because the process behind it was understood. It worked on clean sample data and fell over on the real thing. We map the process first and test against your actual data before you commit to a build. If it will not work, you find that out in week two for the price of a scan."}]},{"question":"Will we be locked into you, or into one AI vendor?","objection":"lock-in","answerInline":[{"type":"text","value":"Neither. You own the code, the prompts, the eval suites and the infrastructure configuration, and it runs in your cloud account. Everything is documented so another team can pick it up. We are model agnostic, so swapping providers is a configuration change rather than a rebuild. Some clients keep us on for the next workflow; plenty take it in house after the first project, which is a perfectly good outcome."}]},{"question":"Who owns the IP?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You do, transferring on full payment. That includes anything we build on top of our own internal tooling, and it covers code, prompts, evals and documentation. It is in our standard contract, not a paid upgrade, and we will sign your NDA and MSA if you have your own."}]},{"question":"Our data is sensitive. Where does it go?","objection":"data-residency","answerInline":[{"type":"text","value":"We are an EU company delivering from Romania, so data stays inside the EEA by default and a DPA is part of standard paperwork. Where data cannot leave your environment at all, we run open-weight models inside your own infrastructure rather than calling a hosted API. Engineers normally work in your cloud accounts under your access controls. We settle all of this during the scan, before any build starts."}]},{"question":"What happens after launch?","objection":"after-launch","answerInline":[{"type":"text","value":"Everything ships with a test set, guardrails, traces and a cost dashboard, so your team can see it working and see it drift. We offer a support retainer, but it is optional and it is not how we make a project viable. If you want to run it yourself from day one, the handover documentation is written on that assumption."}]},{"question":"What if we need engineers rather than a project?","objection":"sideline-our-team","answerInline":[{"type":"text","value":"Then we do that too. Where a team already has direction and is simply short of senior capacity, our "},{"type":"link","label":"staff augmentation","href":"/staff-augmentation-company-uk"},{"type":"text","value":" model puts engineers into your repo and your standups on a monthly rolling basis. It is a different commercial shape from a fixed-scope build, and sometimes it is the honest answer. We will tell you which one fits on the first call."}]},{"question":"Do you work with UK companies, and where are you based?","objection":"other","answerInline":[{"type":"text","value":"Yes. We work with companies across the UK, Ireland, the Nordics, Benelux and DACH, and we deliver from Cluj-Napoca in Romania. That is two hours ahead of London, so the working day overlaps almost entirely and projects run in English. Most engagements start and continue over video, and we travel to the UK for kickoffs and planning where it helps."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Start with the scan","sub":"Two or three weeks, a written opportunity map you own, and a clear answer about whether AI is the right tool for the problem you have."}},"sourceFile":"7code-build/content/pages/ai-agency-uk.mdx"},"ai-agent-development-company":{"spec":{"status":"approved","kind":"money","meta":{"slug":"ai-agent-development-company","title":"AI Agent Development Company | Production Agents | 7code","metaDescription":"AI agent development company building tool-calling and multi-agent systems that survive production: eval harnesses, tracing, cost attribution and guardrails.","canonical":"https://www.7code.tech/ai-agent-development-company/","ogImage":"/og/ai-agent-development-company.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"ai agent development company","secondaryKeywords":["ai agent development services","build ai agents for business","multi-agent system development","llm agent development company","autonomous agent development"],"icpSegment":"outstaffing","searchIntent":"commercial","flywheelStage":"find","difficultyNote":"A directory listing holds the top organic position for this term, which caps the realistic ceiling at a top-ten slot below it. That is acceptable: the traffic is mid-funnel, budget-bearing and technical. Most competing pages spend half their length explaining what an agent is, which loses the reader we want. The winning angle is depth on operations — evals, tracing, cost attribution, prompt-injection defence — written for someone who already knows what a tool-calling loop is. Qualitative only — no verified volume data available.\n"},"cta":{"label":"Book a technical call","action":"booking","href":"/book/technical-call","reassurance":"45 minutes with a senior engineer, not a salesperson. Bring a trace or a failing run and we'll work through it."},"blocks":["hero","trustStrip","diagnosis","successHorizon","proof","cta","whatWeBuild","howWeDeliver","package","cta","pointOfView","faq","close"],"proof":[{"caseStudySlug":"hera","metric":"RAG-verified clinical AI intake with human approval — MVP in 3 months","tags":[{"label":"LLM & agent development","href":"/service/llm-agent-development"},{"label":"AI product engineering","href":"/service/ai-product-engineering"}]},{"caseStudySlug":"numerize","metric":"Platform running 6,000+ customer accounts","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI automation","href":"/service/ai-automation"}]}],"internalLinks":[{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatWeBuild"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatWeBuild"},{"anchor":"AI product engineering","href":"/service/ai-product-engineering","placement":"whatWeBuild"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"package"},{"anchor":"Production MVP","href":"/mvp-development-agency-uk","placement":"package"},{"anchor":"RAG development","href":"/rag-development-company","placement":"faq"},{"anchor":"AI development company UK","href":"/ai-development-company-uk","placement":"faq"},{"anchor":"AI automation","href":"/ai-automation-agency-uk","placement":"faq"},{"anchor":"staff augmentation","href":"/staff-augmentation-company-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"what AI work costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"AI agent development company for agents that reach production","sub":"You know what a tool-calling loop is. What you need is the layer around it — evals, tracing, cost attribution, approval steps and guardrails — built by senior engineers who have shipped it before."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"diagnosis":{"rich":[{"type":"h2","text":"The agent works until someone else uses it"},{"type":"p","inline":[{"type":"text","value":"In the demo it planned three steps, called two tools and produced the right answer. In production it calls the same tool eleven times in a row. It invents a parameter your API has never accepted. One support ticket ran for forty minutes and burned four hundred dollars of tokens before anyone noticed, and the only reason anyone noticed was the invoice."}]},{"type":"p","inline":[{"type":"text","value":"Underneath that, the real gap: nobody owns the eval suite. There is no graded set of runs, so every prompt change is a guess and every model upgrade is a leap. When quality drops, the team argues from anecdotes because there is no measurement to argue from."}]},{"type":"p","inline":[{"type":"text","value":"Agents are not hard to build. They are hard to operate. The engineering that matters sits in the scaffolding — step budgets, idempotent tools, typed outputs, approval gates, per-run cost attribution, and a test harness that fails loudly in CI."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"successHorizon":{"heading":"What this looks like from where you're sitting","horizons":[{"type":"horizon","label":"In 3 weeks","inline":[{"type":"text","value":"the agent's behaviour is measurable. There is a graded set of real runs, a scoring rubric your team agreed, and a baseline. Every trace is searchable, and you can see which tool call in which step caused a failure rather than reading the final answer and guessing."}]},{"type":"horizon","label":"In 3 months","inline":[{"type":"text","value":"the agent is live under real traffic with step and spend budgets enforced in code. Irreversible actions pass through an approval step. Cost per run is on a dashboard, broken down by tool and by customer, and a regression in the eval suite blocks the deploy."}]},{"type":"horizon","label":"In 12 months","inline":[{"type":"text","value":"your engineers extend the agent without us. New tools arrive with their own tests. Model upgrades are evaluated in an afternoon rather than debated for a month, because the harness answers the question."}]}]},"proof":{"rich":[{"type":"h2","text":"Two we can talk about"},{"type":"p","inline":[{"type":"bold","value":"Hera Health Tech"},{"type":"text","value":" — a clinical intake flow with retrieval-verified answers and a human approval step before anything reaches a clinician. Days of manual review became minutes, MVP shipped in three months. Tags: "},{"type":"link","label":"LLM & agent development","href":"/service/llm-agent-development"},{"type":"text","value":" · "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" → "},{"type":"link","label":"Read the Hera case study","href":"/case-study/hera"}]},{"type":"p","inline":[{"type":"bold","value":"Numerize"},{"type":"text","value":" — an operational platform now running 6,000+ customer accounts, with automated flows reaching into systems that previously required manual reconciliation. Tags: "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" · "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" → "},{"type":"link","label":"Read the Numerize case study","href":"/case-study/numerize"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book a technical call"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatWeBuild":{"rich":[{"type":"h2","text":"What we actually build"},{"type":"ul","items":[[{"type":"bold","value":"Tool-calling agents"},{"type":"text","value":" — typed tool schemas, strict output validation, idempotent side effects, retries with backoff, and a step budget that ends a loop instead of letting it run."}],[{"type":"bold","value":"Multi-agent orchestration"},{"type":"text","value":" — planner and worker separation, explicit handoff contracts, shared state that is written once, and a supervisor that can cancel a branch. We use it where it earns its complexity, and we will tell you when one agent would do."}],[{"type":"bold","value":"Human-in-the-loop approval steps"},{"type":"text","value":" — a review queue for anything irreversible: payments, external messages, record deletion, production writes. With the diff the reviewer needs, not a raw payload."}],[{"type":"bold","value":"Agent memory and state"},{"type":"text","value":" — short-term context management, durable run state so a crash resumes rather than restarts, and long-term memory with an expiry policy you control."}],[{"type":"bold","value":"Eval harnesses"},{"type":"text","value":" — graded run sets built from your own traffic, rubric scoring, regression gates in CI, and separate suites for tool-selection accuracy and end-to-end task success."}],[{"type":"bold","value":"Tracing and cost attribution per run"},{"type":"text","value":" — every step, prompt, tool call, token count and latency recorded, with spend rolled up by feature, by customer and by tool."}],[{"type":"bold","value":"Guardrails against prompt injection"},{"type":"text","value":" — untrusted content isolated from instructions, allow-lists on tool arguments, output filtering, and least-privilege credentials per tool rather than one shared key."}],[{"type":"bold","value":"[System integrations](/service/system-integrations) the agent acts through"},{"type":"text","value":" — the CRM, ERP, ticketing and internal APIs, wrapped as tools with sane errors. This is the unglamorous majority of the work."}],[{"type":"bold","value":"[LLM and agent development](/service/llm-agent-development) and [AI product engineering](/service/ai-product-engineering)"},{"type":"text","value":" as one team, where the agent is part of a product rather than a standalone script."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howWeDeliver":{"rich":[{"type":"h2","text":"How we work, and what that protects you from"},{"type":"ul","items":[[{"type":"bold","value":"The eval suite is the first deliverable, not the last."},{"type":"text","value":" Without a graded set you cannot tell an improvement from a coincidence. We build it before we tune anything, and we hand it to your team."}],[{"type":"bold","value":"Budgets are enforced in code."},{"type":"text","value":" Steps, tokens, wall-clock time and spend per run, with hard stops. A runaway agent becomes a failed run and an alert, not an invoice."}],[{"type":"bold","value":"You meet the engineers who build it."},{"type":"text","value":" Named senior people from the first call through delivery. No account manager layer, no reassignment after signature."}],[{"type":"bold","value":"Model agnostic by policy."},{"type":"text","value":" Provider calls sit behind an internal interface, so switching model is a config change the eval suite validates. You are not tied to one vendor's roadmap or pricing."}],[{"type":"bold","value":"You own everything."},{"type":"text","value":" Code, prompts, tool definitions, eval sets, traces and infrastructure config, in your cloud account, documented so another team can take it over."}],[{"type":"bold","value":"Your data stays in the EU."},{"type":"text","value":" We are an EU company delivering from Romania, so residency and a DPA are settled before the first tool is written, not after a security review."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"Start with a two-week paid agent architecture review"},{"type":"p","inline":[{"type":"text","value":"Most agent engagements here begin the same way. Two weeks, senior engineers, working on your existing runs and traces rather than a discovery questionnaire."}]},{"type":"p","inline":[{"type":"text","value":"You get a written architecture: which decisions belong to the model and which belong to code, the tool boundary and permission model, the memory and state design, where the human approval step sits, the eval strategy and rubric, the prompt-injection threat model, and a cost model per run. Plus a phased build plan with estimates. It is written for your engineers to argue with, and it is yours either way."}]},{"type":"p","inline":[{"type":"bold","value":"Typically €9,000–€14,000"},{"type":"text","value":", the same band as the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":". What moves it is the number of tools and systems in scope, and whether we can reach your traces on day one."}]},{"type":"p","inline":[{"type":"text","value":"→ Where the review confirms a full build, teams usually continue into a "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":". Where the underlying problem turns out to be operational rather than agentic, the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":" is the better route."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"pointOfView":{"rich":[{"type":"h2","text":"Our point of view"},{"type":"p","inline":[{"type":"text","value":"Most systems sold as agents should not be agents. If the sequence of steps is known in advance, a state machine calling a model at two points is cheaper, faster, testable and far easier to debug. Autonomy is a cost you pay for genuine branching, and a lot of teams pay it for a workflow they could have drawn on a whiteboard."}]},{"type":"p","inline":[{"type":"text","value":"Where autonomy is genuinely warranted, the interesting engineering is not the loop. It is the boundary around it: what the agent is permitted to touch, what it must ask a human about, what happens on the fourth identical tool call, and how you measure any of it. We would rather spend week one deleting autonomy than month six explaining a four-hundred-dollar support ticket."}]},{"type":"p","inline":[{"type":"bold","value":"Who we are not for:"},{"type":"text","value":" if you want an autonomous agent because the board asked for one, and the underlying process is a fixed sequence, we will say so and quote for the smaller thing. Teams looking for a supplier to build the agent as specified without challenging the design should hire someone else."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does agent development cost?","objection":"price","answerInline":[{"type":"text","value":"It depends on tool count, systems touched and how much autonomy the task genuinely needs, but here are the bands. A two-week paid architecture review is typically "},{"type":"bold","value":"€9,000–€14,000"},{"type":"text","value":", the same band as the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":". A production build of a full agent-backed product, a "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":", usually sits between "},{"type":"bold","value":"€40,000–€90,000"},{"type":"text","value":" over three to five months. Ongoing capacity is monthly: a dedicated senior engineer "},{"type":"bold","value":"€6,400–€8,000"},{"type":"text","value":", a dedicated architect "},{"type":"bold","value":"€9,600–€12,800"},{"type":"text","value":", a pod of an architect plus two senior engineers "},{"type":"bold","value":"€22,000–€29,000"},{"type":"text","value":". Integration count and approval-workflow complexity move those numbers most. More detail in "},{"type":"link","label":"what AI work costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"Our agent loops and burns tokens. Where do you start?","objection":"failed-before","answerInline":[{"type":"text","value":"With your traces, not your prompts. The usual causes are a missing step budget, tools that return ambiguous errors so the model retries forever, and no idempotency, so a repeated call looks like progress. We reproduce the failure against a graded run set, then fix the scaffolding before touching prompt wording. Prompt edits without an eval set are how teams spend a quarter going sideways."}]},{"question":"How do you evaluate an agent, specifically?","objection":"other","answerInline":[{"type":"text","value":"On three levels. Task success against a graded set of real runs, scored by a rubric your team signs off. Trajectory quality — whether the right tool was selected with the right arguments at each step. And operational metrics: steps per run, cost per run, latency, and rate of escalation to a human. All three run in CI. A regression on any of them blocks the deploy."}]},{"question":"Which framework do you use?","objection":"other","answerInline":[{"type":"text","value":"We choose per project and we are not attached to any of them. Plenty of production agents are better served by a plain loop, typed tool definitions and your existing job queue than by a framework that hides control flow. What we insist on is that the orchestration is inspectable, testable and yours. Framework choice is written down with the reasoning during the architecture review."}]},{"question":"How do you stop prompt injection?","objection":"other","answerInline":[{"type":"text","value":"By assuming it will happen. Untrusted content is separated from instructions and never gets to define tool behaviour. Tool arguments are validated against allow-lists rather than free text. Each tool has its own least-privilege credential, so a compromised step cannot reach the whole system. Anything irreversible goes through human approval. We also add injection cases to the eval suite so defences are tested on every change, not once at launch."}]},{"question":"Can the agent act in our production systems?","objection":"other","answerInline":[{"type":"text","value":"Yes, and carefully. Writes go through wrapped tools with typed inputs, idempotency keys and audit logging, so a repeated call cannot double-charge or duplicate a record. Destructive and external-facing actions sit behind an approval step by default. We usually start read-only in production, prove the trajectory quality on real traffic, then enable writes one tool at a time."}]},{"question":"Who actually builds it?","objection":"seniority","answerInline":[{"type":"text","value":"Senior engineers, named before you sign, and the same ones through delivery. The person on your technical call is the person writing the tool layer. If you want a working session with the engineer before there is a contract, ask — we prefer it, and it is a faster way to judge us than a deck."}]},{"question":"How fast can you start, and when is something live?","objection":"timeline","answerInline":[{"type":"text","value":"Two to four weeks from signed contract to a working team. The architecture review can usually start sooner. A first agent running against real traffic, read-only, is typically four to six weeks after that, with writes enabled once the eval numbers justify it."}]},{"question":"Who owns the IP?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You do, transferring on full payment. Code, prompts, tool definitions, eval sets and infrastructure configuration, including anything built on top of our own internal tooling. It is in the standard contract rather than a premium option."}]},{"question":"Will we be locked into you or into one model provider?","objection":"lock-in","answerInline":[{"type":"text","value":"Neither. Everything runs in your cloud account and is documented for handover. Provider calls sit behind an interface, so switching is a config change the eval suite validates in an afternoon. Some clients keep us for the next agent; others take it in house after the first release, which we plan for from the start."}]},{"question":"What does support look like after launch?","objection":"after-launch","answerInline":[{"type":"text","value":"Traces, eval runs, cost dashboards and alerts on failure rate, escalation rate and spend per run all ship with the build. Your team can operate it without us. A support retainer is available and optional, and the handover documentation is written on the assumption you may not take it."}]},{"question":"Is an agent even the right answer for us?","objection":"other","answerInline":[{"type":"text","value":"Often not, and we will say so in the first call. Fixed sequences belong in a workflow with a model at two steps, which is "},{"type":"link","label":"AI automation","href":"/ai-automation-agency-uk"},{"type":"text","value":" work. Question-answering over your documents is "},{"type":"link","label":"RAG development","href":"/rag-development-company"},{"type":"text","value":". A broader AI build is "},{"type":"link","label":"AI development company UK","href":"/ai-development-company-uk"},{"type":"text","value":", and if you would rather add senior capacity to your own team than outsource, that is "},{"type":"link","label":"staff augmentation","href":"/staff-augmentation-company-uk"},{"type":"text","value":". You can see "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" before you talk to us."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Start with a technical call","sub":"Bring a failing run, a trace, or an agent design you are unsure about. You will get a senior engineer's read on what will break under real traffic and what it will cost to run."}},"sourceFile":"7code-build/content/pages/ai-agent-development-company.mdx"},"ai-automation-agency-uk":{"spec":{"status":"approved","kind":"money","meta":{"slug":"ai-automation-agency-uk","title":"AI Automation Agency UK | Process Automation | 7code","metaDescription":"AI automation agency working with UK companies that run on manual work. We map the process first, automate one workflow end-to-end, and ship it production-ready.","canonical":"https://www.7code.tech/ai-automation-agency-uk/","ogImage":"/og/ai-automation-agency-uk.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"ai automation agency uk","secondaryKeywords":["ai process automation uk","business process automation ai","ai workflow automation company","automate manual processes ai"],"icpSegment":"smb-automation","searchIntent":"commercial","flywheelStage":"find","difficultyNote":"Softest competitive field in the target set. Incumbents observed are small, often solo-operator n8n/Make shops on exact-match domains (automationaiagency.co.uk, theaiautomationagency.ai, flowio.co.uk, mrkhan.digital). Zero directory presence, zero enterprise presence. A real engineering firm with named engineers and delivered case studies materially outclasses this field on E-E-A-T. Qualitative only — no verified volume data available (Ahrefs plan blocked).\n"},"cta":{"label":"Book an Operational Quick Scan","action":"booking","href":"/book/quick-scan","reassurance":"45 minutes. No prep needed. You'll leave with two or three processes worth automating, whether or not you work with us."},"blocks":["hero","trustStrip","diagnosis","successHorizon","proof","cta","whatWeBuild","howWeDeliver","package","cta","pointOfView","faq","close"],"proof":[{"caseStudySlug":"hera","metric":"Clinical intake from days to minutes — RAG-verified, MVP in 3 months","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"LLM & agent development","href":"/service/llm-agent-development"}]},{"caseStudySlug":"numerize","metric":"6,000+ customer accounts running on the platform","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI automation","href":"/service/ai-automation"}]}],"internalLinks":[{"anchor":"AI automation","href":"/service/ai-automation","placement":"whatWeBuild"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatWeBuild"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatWeBuild"},{"anchor":"Operational Quick Scan","href":"/packages/operational-quick-scan","placement":"package"},{"anchor":"Automation Pilot","href":"/packages/automation-pilot","placement":"package"},{"anchor":"Department Automation Sprint","href":"/packages/department-automation-sprint","placement":"faq"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"faq"},{"anchor":"staff augmentation","href":"/staff-augmentation-company-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"operations","href":"/expertise/operations","placement":"faq"},{"anchor":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"AI automation agency for UK businesses running on manual work","sub":"We automate the workflows your team rebuilds by hand every week — and we ship them with the evals, guardrails and cost controls that keep them working after we leave."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"diagnosis":{"rich":[{"type":"h2","text":"You already know which processes are broken"},{"type":"p","inline":[{"type":"text","value":"Someone on your team rebuilds the same report every Monday morning. A headcount was signed off last year because a process could not scale, not because the work needed a person. A tool was bought, rolled out, and half the team still works around it in a spreadsheet."}]},{"type":"p","inline":[{"type":"text","value":"None of that is a technology problem. It is a process nobody has mapped end to end. And that is why most automation projects fail — they move the mess somewhere more expensive, then break the first time real data arrives."}]},{"type":"p","inline":[{"type":"text","value":"We start by mapping. Then we automate one thing properly, prove it works on your real data, and only then scale it."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"successHorizon":{"heading":"What this looks like from where you're sitting","horizons":[{"type":"horizon","label":"In 3 weeks","inline":[{"type":"text","value":"you have a written map of your operational processes, ranked by how much time and money each one costs you, with an honest estimate of what automating it would cost and what it would return. If nothing on that list is worth doing, we tell you."}]},{"type":"horizon","label":"In 3 months","inline":[{"type":"text","value":"one workflow runs without a person in the middle. Your team can see what it did, why it did it, and what it cost to run. Errors go to a human, not into a void."}]},{"type":"horizon","label":"In 12 months","inline":[{"type":"text","value":"a department operates at a volume that would previously have required hiring. The automations are documented, owned by your team, and running on infrastructure you control."}]}]},"proof":{"rich":[{"type":"h2","text":"Two we can talk about"},{"type":"p","inline":[{"type":"bold","value":"Hera Health Tech"},{"type":"text","value":" — clinical onboarding that took days now takes minutes. Built as a RAG-verified AI intake flow with a human review step, MVP shipped in three months. Tags: "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"LLM & agent development","href":"/service/llm-agent-development"},{"type":"text","value":" → "},{"type":"link","label":"Read the Hera case study","href":"/case-study/hera"}]},{"type":"p","inline":[{"type":"bold","value":"Numerize"},{"type":"text","value":" — an operational platform now running 6,000+ customer accounts, integrating systems that previously required manual reconciliation. Tags: "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" · "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" → "},{"type":"link","label":"Read the Numerize case study","href":"/case-study/numerize"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book an Operational Quick Scan"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatWeBuild":{"rich":[{"type":"h2","text":"What we actually build"},{"type":"ul","items":[[{"type":"bold","value":"Workflow automation"},{"type":"text","value":" — the multi-step processes that currently live in someone's head and three browser tabs. Intake, triage, routing, approval, reporting."}],[{"type":"bold","value":"AI agents that do real work"},{"type":"text","value":" — not a chatbot on your website. Agents that read a document, decide something, act in a system, and hand the edge cases to a person."}],[{"type":"bold","value":"Document and data extraction"},{"type":"text","value":" — invoices, contracts, forms, emails. Structured output your existing systems can consume, with a confidence score attached."}],[{"type":"bold","value":"[System integrations](/service/system-integrations)"},{"type":"text","value":" — the connective work that makes any of the above possible. APIs, middleware, data sync between tools that were never designed to talk."}],[{"type":"bold","value":"Internal tools and dashboards"},{"type":"text","value":" — so the people who own the process can see what the automation is doing without asking engineering."}],[{"type":"bold","value":"Evals, guardrails and cost controls"},{"type":"text","value":" — shipped with the automation, not added later. This is the difference between a demo and something you can run a business on."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howWeDeliver":{"rich":[{"type":"h2","text":"How we work, and what that protects you from"},{"type":"ul","items":[[{"type":"bold","value":"We map before we build."},{"type":"text","value":" Most failed automation projects skipped this. If the process is broken, automating it makes it broken faster."}],[{"type":"bold","value":"You own everything."},{"type":"text","value":" The code, the prompts, the infrastructure, the documentation. No black boxes and nothing you need us to keep running."}],[{"type":"bold","value":"Model agnostic."},{"type":"text","value":" GPT, Claude, Gemini, or an open-weight model running in your own environment. We pick per use case and per data-sensitivity requirement, not per vendor relationship."}],[{"type":"bold","value":"Senior engineers only."},{"type":"text","value":" The person in your first call is the person building it. No account manager layer, no handover to juniors after the contract signs."}],[{"type":"bold","value":"Evals and observability by default."},{"type":"text","value":" Every AI step ships with a test set, a guardrail, a trace and a cost dashboard. You will know when it degrades before your customers do."}],[{"type":"bold","value":"Your data stays in the EU."},{"type":"text","value":" We are an EU company delivering from Romania. Data residency, GDPR posture and a DPA are settled before the first line of code."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"Start with the scan, not the build"},{"type":"p","inline":[{"type":"bold","value":"Operational Quick Scan — 2 to 3 weeks"}]},{"type":"p","inline":[{"type":"text","value":"We sit with the people who run the process, map what actually happens, and come back with an automation opportunity map: which workflows are worth automating, what each would cost, what each would return, and in what order."}]},{"type":"p","inline":[{"type":"text","value":"You get a written deliverable you own. If the answer is \"none of this is worth automating yet\", that is what we will tell you — and you will have spent a few thousand euros instead of six figures finding out."}]},{"type":"p","inline":[{"type":"bold","value":"Typically €4,500–€6,000."}]},{"type":"p","inline":[{"type":"text","value":"→ "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":" · most clients who proceed then run an "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":" on the highest-value workflow from the map."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"pointOfView":{"rich":[{"type":"h2","text":"Our point of view"},{"type":"p","inline":[{"type":"text","value":"The interesting question is almost never \"can this be automated\". Nearly everything can. The question is whether the process is worth keeping in the first place."}]},{"type":"p","inline":[{"type":"text","value":"A lot of manual work exists because of a decision somebody made five years ago under constraints that no longer apply. Automating that work preserves the decision and makes it permanent. Sometimes the right answer is to delete the process, not automate it — and an agency paid to build things is structurally unlikely to tell you that."}]},{"type":"p","inline":[{"type":"text","value":"We would rather run a three-week scan that ends in \"don't build this\" than a six-month project that ends in something nobody uses."}]},{"type":"p","inline":[{"type":"bold","value":"Who we are not for:"},{"type":"text","value":" if you want a team that ships exactly what it is told without asking whether the thing should exist, we are the wrong partner. We will push back, in the first meeting, before there is a contract to protect."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"How much does AI automation actually cost?","objection":"price","answerInline":[{"type":"text","value":"It depends on the number of systems involved and how clean your data is, but here are the bands we work in. A process audit and opportunity map — the "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":" — is typically "},{"type":"bold","value":"€4,500–€6,000"},{"type":"text","value":" over two to three weeks. Automating a single workflow end to end, an "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":", typically runs "},{"type":"bold","value":"€15,000–€25,000"},{"type":"text","value":" over six to ten weeks. Digitising a whole department, the "},{"type":"link","label":"Department Automation Sprint","href":"/packages/department-automation-sprint"},{"type":"text","value":", is usually "},{"type":"bold","value":"€40,000–€65,000"},{"type":"text","value":" over ten to sixteen weeks. We break the cost down by workflow during the scan, so you can drop anything that does not pay for itself. More detail in "},{"type":"link","label":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"We tried an AI tool last year and it did not work. Why would this be different?","objection":"failed-before","answerInline":[{"type":"text","value":"You are not unusual. Most of the failures we are called in to fix have the same cause: someone picked a use case because it demoed well, not because the process behind it was understood. The pilot worked on clean sample data and fell over on the real thing. We map the process first and test on your actual data before you commit to a build. If it will not work, you find out in week two."}]},{"question":"How long before we see anything?","objection":"timeline","answerInline":[{"type":"text","value":"The scan produces a deliverable in two to three weeks. A first automated workflow is usually live in six to ten weeks from kickoff. We deliberately pick an early win your team can see working, rather than disappearing for six months and returning with a platform."}]},{"question":"Who will actually be doing the work?","objection":"seniority","answerInline":[{"type":"text","value":"Senior engineers, and the same ones throughout. The person who runs your scan is the person who builds the automation. We do not have an account manager layer and we do not hand the build down to juniors once the contract is signed. If you want to meet the engineer before you commit, ask — we would rather you did."}]},{"question":"Will we be locked into you?","objection":"lock-in","answerInline":[{"type":"text","value":"No. You own the code, the prompts, the eval suites and the infrastructure config, and it runs in your cloud account. Everything is documented so another team can pick it up. We are model agnostic, so you are not tied to one AI vendor either. Some clients keep us on for new workflows; plenty take it in house after the first pilot, which is a fine outcome."}]},{"question":"Will you replace our operations team?","objection":"sideline-our-team","answerInline":[{"type":"text","value":"That is not what this is. The pattern we see is a team spending most of its week on work that does not need judgement, and the rest on work that does. Automation takes the first part. In practice the people who run the process become the people who own the automation — they are the only ones who know what a wrong output looks like."}]},{"question":"Who owns the IP?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You do, transferring on full payment. That includes anything we build on top of our own internal tooling. It is in our standard contract, not an upgrade."}]},{"question":"Our data is sensitive. Where does it go?","objection":"data-residency","answerInline":[{"type":"text","value":"We are an EU company delivering from Romania, so your data stays inside the EEA by default and a DPA is part of the standard paperwork. Where the data cannot leave your environment at all, we run open-weight models inside your own infrastructure instead of calling a hosted API. We settle this in the scan, not after the build."}]},{"question":"What happens after it goes live?","objection":"after-launch","answerInline":[{"type":"text","value":"Every automation ships with a test set, guardrails, traces and a cost dashboard, so your team can see it working and see it drift. We offer a support retainer, but it is optional and it is not how we make the project viable. If you want to run it yourself from day one, the handover documentation assumes exactly that."}]},{"question":"We do not have clean data. Is this premature?","objection":"other","answerInline":[{"type":"text","value":"Sometimes, and we will say so. Poor data quality is the most common reason to slow down, and the scan is where it surfaces. Often the honest answer is a smaller first step — fixing one integration so two systems finally agree — before any AI is involved. That work is less exciting and it is frequently where the return is."}]},{"question":"Do you work with companies outside the UK?","objection":"other","answerInline":[{"type":"text","value":"Yes. We work with companies across the UK, Ireland, the Nordics, Benelux and DACH. Delivery is from Cluj-Napoca, which overlaps the UK working day almost entirely, and we run projects in English. Most engagements start with a video call, so location has not been a practical issue for years."}]},{"question":"What if we need more than automation?","objection":"other","answerInline":[{"type":"text","value":"Then we say so. We also do product engineering and "},{"type":"link","label":"staff augmentation","href":"/staff-augmentation-company-uk"},{"type":"text","value":", and quite often what starts as an automation conversation turns out to be a product problem or a capacity problem. We would rather tell you that than sell you the thing we were asked about. You can see "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" and the "},{"type":"link","label":"operations work","href":"/expertise/operations"},{"type":"text","value":" we have done."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Start with the scan","sub":"Two or three weeks, a written opportunity map you own, and an honest answer about whether anything here is worth building."}},"sourceFile":"7code-build/content/pages/ai-automation-agency-uk.mdx"},"ai-consultancy-uk":{"spec":{"status":"approved","kind":"money","meta":{"slug":"ai-consultancy-uk","title":"AI Consultancy UK | Costed AI Strategy, Then Built | 7code","metaDescription":"AI consultancy for UK leadership teams. We cost every AI opportunity, tell you which ones are worth doing, and build the ones that are. Price bands below.","canonical":"https://www.7code.tech/ai-consultancy-uk/","ogImage":"/og/ai-consultancy-uk.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"ai consultancy uk","secondaryKeywords":["ai consulting services uk","ai strategy consultant uk","ai consultancy pricing","enterprise ai advisory uk","ai readiness assessment uk"],"icpSegment":"smb-automation","searchIntent":"commercial-investigation","flywheelStage":"find","difficultyNote":"The observed SERP is dominated by listicles, directory rankings and \"best AI consultancies\" round-ups rather than by firms selling their own work. The strongest ranking page in the field is a pricing-and-providers guide, which tells you what the query rewards: explicit cost content and buyer criteria. A delivery firm that publishes real bands and arms the buyer with selection questions outranks a round-up on usefulness. Qualitative only — no verified volume data available (Ahrefs plan blocked).\n"},"cta":{"label":"Book an Operational Quick Scan","action":"booking","href":"/book/quick-scan","reassurance":"45 minutes with an engineer, not a salesperson. You'll leave with a costed view of two or three AI opportunities, whether or not you work with us."},"blocks":["hero","trustStrip","diagnosis","successHorizon","proof","cta","whatWeBuild","howWeDeliver","package","cta","pointOfView","faq","close"],"proof":[{"caseStudySlug":"g42-fleet","metric":"Fleet platform deployed at EXPO 2020 scale, across a two-year engagement","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"Cloud infrastructure","href":"/service/cloud-agentic-infra"}]},{"caseStudySlug":"lidl-road-safety","metric":"National road-safety programme platform delivered for Lidl Romania","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"AI automation","href":"/service/ai-automation"}]}],"internalLinks":[{"anchor":"AI automation","href":"/service/ai-automation","placement":"whatWeBuild"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatWeBuild"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatWeBuild"},{"anchor":"cloud infrastructure","href":"/service/cloud-agentic-infra","placement":"whatWeBuild"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"package"},{"anchor":"Operational Quick Scan","href":"/packages/operational-quick-scan","placement":"package"},{"anchor":"Automation Pilot","href":"/packages/automation-pilot","placement":"faq"},{"anchor":"Department Automation Sprint","href":"/packages/department-automation-sprint","placement":"faq"},{"anchor":"AI automation agency","href":"/ai-automation-agency-uk","placement":"faq"},{"anchor":"staff augmentation","href":"/staff-augmentation-company-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"operations","href":"/expertise/operations","placement":"faq"},{"anchor":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"AI consultancy UK leadership teams use to get a straight answer","sub":"For the CEO, COO or board that has heard enough about what AI could do. We cost the options, name the two worth doing, and then build them."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"diagnosis":{"rich":[{"type":"h2","text":"You are not short of AI ambition. You are short of a costed answer"},{"type":"p","inline":[{"type":"text","value":"Three departments are each running their own pilot. Operations has a tool on a corporate card, finance is trialling something a vendor demoed well, and someone in marketing has been quietly productive with a chatbot for months. Nobody has costed any of it, nobody owns it, and none of it is on a risk register."}]},{"type":"p","inline":[{"type":"text","value":"Meanwhile the board has asked for an AI strategy by the next meeting. Or worse, money has already gone out — a pilot, a platform licence, a consultant's deck — and there is nothing to put in front of them that shows a return."}]},{"type":"p","inline":[{"type":"text","value":"The problem is not that your team lacks ideas. It is that no one has priced them. AI opportunities all look equally attractive until someone works out what each costs to build, what it costs to run per month, what it saves, and what happens when it gets an answer wrong in front of a customer."}]},{"type":"p","inline":[{"type":"text","value":"That is the work. It takes weeks, not quarters, and it ends in a ranked list with numbers next to it — including the items we recommend you do not fund."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"successHorizon":{"heading":"What this looks like from where you're sitting","horizons":[{"type":"horizon","label":"In 3 weeks","inline":[{"type":"text","value":"you know what the pilots already running in your business are costing, what they are returning, and which ones should be stopped. You have a shortlist of opportunities with an estimated build cost, a monthly running cost and a payback period against each one."}]},{"type":"horizon","label":"In 3 months","inline":[{"type":"text","value":"one of them is live and being measured. There is a named owner inside your business, a defined escalation path when the model is wrong, and a cost dashboard the finance team can read without an interpreter. The board question moves from \"what is our AI strategy\" to \"what do we fund next\"."}]},{"type":"horizon","label":"In 12 months","inline":[{"type":"text","value":"AI is part of how a department operates rather than a project. Governance is written down, data handling has survived a review, and you can explain each decision to an auditor, an insurer or an acquirer using documents that already exist."}]}]},"proof":{"rich":[{"type":"h2","text":"Two we can talk about"},{"type":"p","inline":[{"type":"bold","value":"G42"},{"type":"text","value":" — a fleet platform deployed at EXPO 2020 scale, over a two-year engagement. The kind of work where uptime, integration depth and operating under scrutiny matter more than the demo. Tags: "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" · "},{"type":"link","label":"Cloud infrastructure","href":"/service/cloud-agentic-infra"},{"type":"text","value":" → "},{"type":"link","label":"Read the G42 case study","href":"/case-study/g42-fleet"}]},{"type":"p","inline":[{"type":"bold","value":"Lidl Romania"},{"type":"text","value":" — the platform behind a national road-safety programme, delivered for one of the largest retailers in the market and run in front of a public audience. Tags: "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" → "},{"type":"link","label":"Read the Lidl Romania case study","href":"/case-study/lidl-road-safety"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book an Operational Quick Scan"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatWeBuild":{"rich":[{"type":"h2","text":"What you get, and what we build after it"},{"type":"ul","items":[[{"type":"bold","value":"A costed opportunity map"},{"type":"text","value":" — every AI and automation candidate in your business, with a build cost, a monthly running cost, an estimated return and a recommendation. Including the ones to stop."}],[{"type":"bold","value":"A pilot audit"},{"type":"text","value":" — what the three departments are already running, what it costs, what data it touches, and which of it belongs on a risk register today rather than after an incident."}],[{"type":"bold","value":"An AI governance and policy pack"},{"type":"text","value":" — acceptable use, model selection criteria, human-review thresholds, escalation paths, and a record of decisions you can hand to an auditor."}],[{"type":"bold","value":"A data-readiness assessment"},{"type":"text","value":" — where your data actually lives, what state it is in, and what has to be true before any of this works. Usually the least exciting document and the most useful."}],[{"type":"bold","value":"[AI automation](/service/ai-automation) built and shipped"},{"type":"text","value":" — the workflows the map says are worth doing, delivered end to end rather than recommended and left."}],[{"type":"bold","value":"[LLM and agent development](/service/llm-agent-development)"},{"type":"text","value":" — assistants and agents that read, decide and act inside your systems, with evals, guardrails, traces and cost controls from day one."}],[{"type":"bold","value":"[System integrations](/service/system-integrations)"},{"type":"text","value":" — the connective work that makes any of it possible, and the part most strategy decks skip because it is not interesting to write about."}],[{"type":"bold","value":"[Cloud infrastructure](/service/cloud-agentic-infra)"},{"type":"text","value":" — deployed into your own environment, with the monitoring and access controls your security team will ask about."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howWeDeliver":{"rich":[{"type":"h2","text":"How we work, and what that protects you from"},{"type":"ul","items":[[{"type":"bold","value":"Every recommendation carries a number."},{"type":"text","value":" Build cost, monthly run cost, expected return, payback period. A strategy without those is an opinion, and a board cannot fund an opinion."}],[{"type":"bold","value":"Your data stays in the EU, and we can prove where."},{"type":"text","value":" We are an EU company delivering from Romania. Data residency, GDPR posture and a DPA are settled before the work starts, not during your next security review."}],[{"type":"bold","value":"Model agnostic, by policy."},{"type":"text","value":" GPT, Claude, Gemini or an open-weight model running inside your own environment. We choose per use case and per data-sensitivity requirement, and we write down why. No vendor relationship decides your architecture."}],[{"type":"bold","value":"Governance is a deliverable, not a slide."},{"type":"text","value":" Human-review thresholds, escalation paths, an audit trail, and a written record of why each model was chosen. Enough that you can answer an auditor, an insurer or a customer's procurement team."}],[{"type":"bold","value":"Nothing we recommend locks you in."},{"type":"text","value":" You own the code, the prompts, the eval suites and the infrastructure config, it runs in your cloud account, and it is documented for a team that has never met us. Including if that team replaces us."}],[{"type":"bold","value":"Senior engineers, not a research team."},{"type":"text","value":" The people advising you build production systems for a living. That is why the estimates hold up, and why we will tell you when something demos far better than it runs."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"The engagement that produces the board paper"},{"type":"p","inline":[{"type":"bold","value":"AI-Ready Ops Blueprint — 4 to 6 weeks"}]},{"type":"p","inline":[{"type":"text","value":"We work through your operations with the people who run them, audit what is already running, assess the state of your data, and cost every opportunity we find. You get a ranked plan: what to build, in what order, what each costs to build and to run, what each returns, and what to stop doing now."}]},{"type":"p","inline":[{"type":"text","value":"It comes with the governance pack — model selection criteria, human-review thresholds, escalation paths, data handling — so the strategy arrives with its risk answers attached. The output is written to be read by a board, and it is yours whether or not we build anything afterwards."}]},{"type":"p","inline":[{"type":"bold","value":"Typically €9,000–€14,000."},{"type":"text","value":" What moves it: the number of departments in scope, how many pilots are already live, and whether data governance has to be built from nothing or extended."}]},{"type":"p","inline":[{"type":"text","value":"→ "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":". If you want something smaller first, the "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":" covers one function in two to three weeks."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"pointOfView":{"rich":[{"type":"h2","text":"Our point of view"},{"type":"p","inline":[{"type":"text","value":"Most AI strategy work fails at the same point. Not at the analysis — the analysis is usually fine — but at the handover. A document arrives, everyone agrees it is thorough, and nobody has the capacity or the mandate to build any of it. Twelve months later the same board asks the same question."}]},{"type":"p","inline":[{"type":"text","value":"We think advice you cannot execute is close to worthless, and that a firm which only advises has no incentive to be right. If your estimate is never tested against a real build, being wrong costs you nothing. We publish a cost estimate in week five and then have to live with it in month three, which is a considerably more disciplined way to produce a number."}]},{"type":"p","inline":[{"type":"text","value":"So we do both, deliberately. The blueprint is a real deliverable you can take elsewhere. But it is written by the people who would build it, which is why it contains integration effort, running costs and failure modes that a pure advisory deck tends to leave out."}]},{"type":"p","inline":[{"type":"bold","value":"Who we are not for:"},{"type":"text","value":" if what you need is a document to satisfy a board — a strategy nobody intends to fund — we are the wrong firm, and a large consultancy will do it better and with a more impressive cover. We are also wrong for you if the AI decision has already been made and you want it validated. We will tell you when a favoured initiative does not pay back, and that is an awkward meeting we are willing to have."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does AI consultancy actually cost?","objection":"price","answerInline":[{"type":"text","value":"We publish bands, because the alternative wastes everyone's time. A single-function review, the "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":", is typically "},{"type":"bold","value":"€4,500–€6,000"},{"type":"text","value":" over two to three weeks. The full costed strategy, the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":", is typically "},{"type":"bold","value":"€9,000–€14,000"},{"type":"text","value":" over four to six weeks. If you then build, a single workflow taken live as an "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":" typically runs "},{"type":"bold","value":"€15,000–€25,000"},{"type":"text","value":" over six to ten weeks, and a whole department, the "},{"type":"link","label":"Department Automation Sprint","href":"/packages/department-automation-sprint"},{"type":"text","value":", usually sits between "},{"type":"bold","value":"€40,000–€65,000"},{"type":"text","value":" over ten to sixteen weeks. What moves those numbers: how many departments are in scope, how many systems have to be integrated, and the state of your data. More detail in "},{"type":"link","label":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"How do we choose between AI consultants?","objection":"other","answerInline":[{"type":"text","value":"Three questions separate the field quickly. Ask what they have shipped — not advised on, shipped, with a named client and a system still running. Ask to speak to a client directly, not read a quote in a deck. And ask what went wrong on a recent project and what it cost to fix. A firm that answers the third one specifically has been in production. A firm that gets cagey is telling you something, and it is usually that the delivery happens somewhere they cannot show you. Two more that are worth asking: who exactly will be in the room after the sales call, and will the output include costs or only recommendations."}]},{"question":"Are we too small for this?","objection":"other","answerInline":[{"type":"text","value":"Probably not. The pattern that makes this work is manual operational load, not headcount — we typically work with companies from around fifty staff upwards, though the real test is whether there is a process consuming meaningful salaried time every week. If you are smaller than that, say so on the call. Sometimes the honest answer is that one integration or an off-the-shelf tool solves it, and we will tell you that instead of scoping an engagement around it."}]},{"question":"Our data is a mess. Should we fix that first?","objection":"other","answerInline":[{"type":"text","value":"Not before the assessment — the assessment is how you find out how much of it actually matters. In practice you rarely need clean data everywhere. You need it in the two or three places the first initiatives touch, and the blueprint tells you which those are and what fixing them costs. What we will not do is start a build on data we know is unreliable. That is how a pilot demos well and then produces confident nonsense in front of a customer."}]},{"question":"Will you build it too, or just advise?","objection":"other","answerInline":[{"type":"text","value":"Both, and that is the whole point. A strategy delivered as a PDF and never opened again is worth nothing, and it is the most common outcome in this market. We advise as engineers who will be held to the estimate, then build through "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" and "},{"type":"link","label":"LLM and agent development","href":"/service/llm-agent-development"},{"type":"text","value":" if you want us to. There is no obligation. You can take the blueprint to another firm or to your own team, and it is written so that they can price from it."}]},{"question":"The board meets in six weeks. Is that realistic?","objection":"timeline","answerInline":[{"type":"text","value":"Yes, that is the window the blueprint is built for. Four to six weeks from kickoff to a costed, ranked plan written to be read by a board rather than by an engineering team. If the meeting is sooner than that, tell us and we will scope a single function instead — two to three weeks, narrower, but a real answer with numbers rather than a holding slide."}]},{"question":"Who will we actually be dealing with?","objection":"seniority","answerInline":[{"type":"text","value":"Senior engineers, and the same people throughout. The person who runs your assessment is the person who would build the work afterwards. We have no account manager layer and nothing is handed to a junior team once a contract is signed. If you want to meet them before you commit, ask — we would rather you did. You can also see "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" in full."}]},{"question":"What about security, governance and where our data sits?","objection":"data-residency","answerInline":[{"type":"text","value":"Your data stays inside the EEA by default. We are an EU company delivering from Romania, a DPA is part of the standard paperwork, and we deploy into your own cloud account rather than ours. Where data cannot leave your environment at all, we run open-weight models inside your own infrastructure instead of calling a hosted API. Governance is a deliverable in its own right: human-review thresholds, escalation paths, model selection criteria and an audit trail, so you can explain any decision to a regulator or an insurer using documents that already exist."}]},{"question":"How do we avoid being locked into one AI vendor?","objection":"lock-in","answerInline":[{"type":"text","value":"By choosing per use case and writing down why, which is what we do. We are model agnostic and we build so the model behind a workflow can be swapped without rewriting the workflow. You own the code, the prompts, the eval suites and the infrastructure config, and it runs in your account. If a cheaper or better model appears in eighteen months, changing to it should be a configuration decision and a re-run of the eval suite, not a project."}]},{"question":"We have already spent money on AI and have nothing to show the board.","objection":"failed-before","answerInline":[{"type":"text","value":"This is the most common reason we get called, and the cause is almost always the same. The pilot was picked because it demoed well, not because anyone understood the process behind it, so it worked on clean sample data and fell over on the real thing. Part of the blueprint is auditing what you already have. Occasionally something is worth rescuing and we will say so. More often the honest recommendation is to stop two of the three pilots and fund one properly, which is a defensible thing to take to a board."}]},{"question":"Will this be used to cut our team?","objection":"sideline-our-team","answerInline":[{"type":"text","value":"That is not what we are engaged to do, and the leadership teams who frame it that way get worse results anyway. The consistent pattern is that the people who run a process become the people who own the automation — they are the only ones who can recognise a wrong output. We involve them from the first week, because a plan built without them is a plan that quietly does not get used. You can see the "},{"type":"link","label":"operations","href":"/expertise/operations"},{"type":"text","value":" work behind that."}]},{"question":"What happens after the blueprint?","objection":"after-launch","answerInline":[{"type":"text","value":"Whatever you decide. Some clients build with us, some take it to their own team, and some do nothing for six months and come back. Where we do build, everything ships with evals, guardrails, traces and a cost dashboard, so your team can see it working and see it drift. If what you actually need is senior capacity rather than advice, that is "},{"type":"link","label":"staff augmentation","href":"/staff-augmentation-company-uk"},{"type":"text","value":", and if it is purely workflow automation you may want our "},{"type":"link","label":"AI automation agency","href":"/ai-automation-agency-uk"},{"type":"text","value":" page instead."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Start with a costed answer","sub":"Four to six weeks, a ranked and costed plan your board can read, and a governance pack that arrives with it. Yours whether or not we build anything afterwards."}},"sourceFile":"7code-build/content/pages/ai-consultancy-uk.mdx"},"ai-development-company-uk":{"spec":{"status":"approved","kind":"money","meta":{"slug":"ai-development-company-uk","title":"AI Development Company UK | Production AI Systems | 7code","metaDescription":"AI development company for UK teams past the prototype stage. Named senior engineers, EU delivery, and AI shipped with evals, guardrails and cost controls.","canonical":"https://www.7code.tech/ai-development-company-uk/","ogImage":"/og/ai-development-company-uk.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"ai development company uk","secondaryKeywords":["ai software development company uk","ai development services uk","llm development company uk","ai engineering partner uk","custom ai development uk"],"icpSegment":"outstaffing","searchIntent":"commercial","flywheelStage":"find","difficultyNote":"The hardest field in the target set and the most valuable. The first page of results is dominated by large offshore agencies running thin .co.uk landing pages built from a shared template — heavy on stock claims, light on named engineers, delivered products or any UK-specific substance. Topical trust is weak across the board and almost nobody publishes a real engineering point of view. An EU company with named senior engineers, published case studies and production discipline outclasses that field on E-E-A-T. Qualitative only — no verified volume data available.\n"},"cta":{"label":"Book a technical call","action":"booking","href":"/book/technical-call","reassurance":"45 minutes with a senior engineer, not a salesperson. You'll get a straight read on your architecture whether or not you work with us."},"blocks":["hero","trustStrip","diagnosis","successHorizon","proof","cta","whatWeBuild","howWeDeliver","package","cta","pointOfView","faq","close"],"proof":[{"caseStudySlug":"hera","metric":"RAG-verified clinical AI intake — MVP shipped in 3 months","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"LLM & agent development","href":"/service/llm-agent-development"}]},{"caseStudySlug":"g42-fleet","metric":"Fleet platform deployed at EXPO 2020 scale — 2-year engagement","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"System integrations","href":"/service/system-integrations"}]}],"internalLinks":[{"anchor":"AI product engineering","href":"/service/ai-product-engineering","placement":"whatWeBuild"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatWeBuild"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatWeBuild"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"package"},{"anchor":"Production MVP","href":"/mvp-development-agency-uk","placement":"package"},{"anchor":"AI agent development","href":"/ai-agent-development-company","placement":"faq"},{"anchor":"RAG development","href":"/rag-development-company","placement":"faq"},{"anchor":"AI automation","href":"/ai-automation-agency-uk","placement":"faq"},{"anchor":"staff augmentation","href":"/staff-augmentation-company-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"what AI work costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"AI development company for UK teams building past the prototype","sub":"You have decided to build. We are the senior engineers who take an AI feature from a promising notebook to something that survives real users, real data and a real bill at the end of the month."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"diagnosis":{"rich":[{"type":"h2","text":"The demo worked. Production is a different question."},{"type":"p","inline":[{"type":"text","value":"You have a prototype that impressed the board. On your own test set it answers well and the latency is fine. Then it meets real documents, real edge cases and real concurrency, and the accuracy you quoted in that meeting stops being true. Nobody on the team can tell you why it regressed last Tuesday."}]},{"type":"p","inline":[{"type":"text","value":"Or you are one step earlier. Three suppliers have quoted the same build, the proposals are almost interchangeable, and none of them will tell you who writes the code. The prices differ by a factor of four and you cannot see what the difference buys."}]},{"type":"p","inline":[{"type":"text","value":"Both problems have the same root. AI work is easy to start and expensive to operate. What separates a demo from a system is unglamorous: an eval suite, guardrails, traces, a cost model, and someone senior who owns the numbers. That is the part almost nobody quotes for, and it is the part we lead with."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"successHorizon":{"heading":"What this looks like from where you're sitting","horizons":[{"type":"horizon","label":"In 3 weeks","inline":[{"type":"text","value":"you have an architecture you can defend. The model choices are written down with the reasoning, the failure modes are named, the data flow is mapped, and the running cost is estimated per thousand requests. You also have a build plan your own engineers have reviewed and argued with."}]},{"type":"horizon","label":"In 3 months","inline":[{"type":"text","value":"the first AI feature is live for real users. It ships with an eval set that runs in CI, guardrails on the inputs and outputs, traces you can search, and a dashboard showing spend per feature. When quality moves, you see it before a customer emails about it."}]},{"type":"horizon","label":"In 12 months","inline":[{"type":"text","value":"AI is part of your product rather than a project beside it. Your engineers own the eval suite and extend it without us. Model versions change without drama because switching is a config decision that the tests either pass or fail."}]}]},"proof":{"rich":[{"type":"h2","text":"Two we can talk about"},{"type":"p","inline":[{"type":"bold","value":"Hera Health Tech"},{"type":"text","value":" — a clinical intake flow that ran on days of manual review now completes in minutes. Built as a RAG-verified pipeline with citation checks and a human approval step, MVP shipped in three months. Tags: "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"LLM & agent development","href":"/service/llm-agent-development"},{"type":"text","value":" → "},{"type":"link","label":"Read the Hera case study","href":"/case-study/hera"}]},{"type":"p","inline":[{"type":"bold","value":"G42"},{"type":"text","value":" — a fleet platform delivered and operated at EXPO 2020 scale, across a two-year engagement with the same senior team from first architecture session to production. Tags: "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" → "},{"type":"link","label":"Read the G42 case study","href":"/case-study/g42-fleet"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book a technical call"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatWeBuild":{"rich":[{"type":"h2","text":"What we actually build"},{"type":"ul","items":[[{"type":"bold","value":"LLM features inside an existing product"},{"type":"text","value":" — the work of putting a model behind a real screen, with auth, rate limits, retries, streaming, and a fallback path when the provider has a bad hour."}],[{"type":"bold","value":"Retrieval systems that stay grounded"},{"type":"text","value":" — chunking, hybrid retrieval, reranking and citation enforcement, so an answer can be traced back to the document it came from."}],[{"type":"bold","value":"[LLM and agent development](/service/llm-agent-development)"},{"type":"text","value":" — tool-calling agents, approval steps for anything irreversible, memory and state, and a supervisor that stops a loop before it costs money."}],[{"type":"bold","value":"Eval harnesses"},{"type":"text","value":" — a graded test set built from your own data, wired into CI, so a prompt change or a model upgrade is a pull request with a pass or fail rather than a hunch."}],[{"type":"bold","value":"Observability and cost attribution"},{"type":"text","value":" — traces per request, spend broken down by feature and by customer, and alerts on latency, refusal rate and quality drift."}],[{"type":"bold","value":"Guardrails"},{"type":"text","value":" — input validation, output schema enforcement, prompt-injection defences, and PII handling decided before launch instead of after an incident."}],[{"type":"bold","value":"The infrastructure underneath"},{"type":"text","value":" — vector storage, queues, caching, deployment pipelines and "},{"type":"link","label":"system integrations","href":"/service/system-integrations"},{"type":"text","value":" with the systems you already run."}],[{"type":"bold","value":"[AI product engineering](/service/ai-product-engineering) end to end"},{"type":"text","value":" — where there is no product yet, we do the design, the build and the operations as one team."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howWeDeliver":{"rich":[{"type":"h2","text":"How we work, and what that protects you from"},{"type":"ul","items":[[{"type":"bold","value":"You meet the engineers who build it."},{"type":"text","value":" Named senior people, in the first call, on the contract. No account manager layer and no substitution after signature."}],[{"type":"bold","value":"We are an EU company, not a reseller of one."},{"type":"text","value":" SEVEN CODE DEVELOPMENT SRL, Cluj-Napoca, founded 2017. Your contract, your data and your engineers sit in the same jurisdiction."}],[{"type":"bold","value":"Evals before features."},{"type":"text","value":" We build the graded test set early, because without it nobody can prove a change made things better. This is the single biggest difference between our estimates and cheaper ones."}],[{"type":"bold","value":"Model agnostic by policy."},{"type":"text","value":" GPT, Claude, Gemini or an open-weight model in your own environment. We choose per use case and per data-sensitivity rule, never per vendor relationship."}],[{"type":"bold","value":"You own everything."},{"type":"text","value":" Code, prompts, eval sets, infrastructure config and documentation, running in your cloud account. Another team can pick it up without calling us."}],[{"type":"bold","value":"Costs are engineered, not discovered."},{"type":"text","value":" Token spend, caching strategy and model tiering are design decisions we make with you upfront, then show you on a dashboard."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"Most engagements here start with a two-week paid architecture review"},{"type":"p","inline":[{"type":"text","value":"Before anyone commits to a build, we run a fixed-scope technical discovery. Two weeks, senior engineers only, working on your actual code, data and constraints rather than a questionnaire."}]},{"type":"p","inline":[{"type":"text","value":"You get an architecture document: model and retrieval choices with the reasoning, the failure modes we expect, the eval strategy, a data-residency position, a cost model per thousand requests, and a phased build plan with estimates. It is written for your engineers to challenge, and it is yours whether or not we build the thing."}]},{"type":"p","inline":[{"type":"bold","value":"Typically €9,000–€14,000."},{"type":"text","value":" What moves it is the number of systems in scope and whether the data is already accessible to us. Regulated data and legacy integrations push it up."}]},{"type":"p","inline":[{"type":"text","value":"→ Where the problem is operational rather than product — many manual workflows, unclear where AI even belongs — the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":" is the better starting point. Where the review confirms a full build, most teams continue into a "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":"."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"pointOfView":{"rich":[{"type":"h2","text":"Our point of view"},{"type":"p","inline":[{"type":"text","value":"Model choice is the least interesting decision in an AI project. It changes every few months, and if your system is built properly, changing it is a config edit and a test run. The decisions that actually determine whether the thing works are boring: what you retrieve, how you evaluate, where you put a human, and what happens when the model is confident and wrong."}]},{"type":"p","inline":[{"type":"text","value":"This is why the quotes you are comparing look so different. A price that only covers the happy path will always beat a price that includes evals, guardrails, tracing and a cost model. The difference arrives later, usually as an incident, and it is paid by your team rather than the supplier."}]},{"type":"p","inline":[{"type":"text","value":"We would rather lose a deal on price than win it by quoting for a prototype and calling it a system."}]},{"type":"p","inline":[{"type":"bold","value":"Who we are not for:"},{"type":"text","value":" if you want the cheapest possible build and you already know exactly what to build, we are the wrong partner. We will spend the first two weeks questioning the plan, and we do not staff projects with junior engineers to reach a number."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does AI development actually cost with you?","objection":"price","answerInline":[{"type":"text","value":"It depends on scope, data quality and how much of your stack we have to touch, but here are the bands. A two-week paid architecture review is typically "},{"type":"bold","value":"€9,000–€14,000"},{"type":"text","value":", and it is priced the same as the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":". A full "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":" usually sits between "},{"type":"bold","value":"€40,000–€90,000"},{"type":"text","value":" over three to five months. Ongoing capacity is per month: a dedicated senior engineer is "},{"type":"bold","value":"€6,400–€8,000"},{"type":"text","value":", a dedicated architect "},{"type":"bold","value":"€9,600–€12,800"},{"type":"text","value":", and a pod of an architect plus two senior engineers "},{"type":"bold","value":"€22,000–€29,000"},{"type":"text","value":". What moves those numbers is integration count, regulatory scope and how clean your data is. More detail in "},{"type":"link","label":"what AI work costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"We have three quotes and they look identical. How do we compare them?","objection":"other","answerInline":[{"type":"text","value":"Ask each supplier four questions in writing. Who are the named engineers, and will they still be on the project in month four? What is in scope for evaluation — is there a graded test set, and who builds it? What is the estimated running cost per thousand requests? And what happens to accuracy when the model version changes? The answers separate quotes faster than any price comparison. Most of the gap between a cheap number and ours is those four items."}]},{"question":"Our prototype works in the demo and fails in production. Can you fix it?","objection":"failed-before","answerInline":[{"type":"text","value":"Usually, yes, and the diagnosis is rarely the model. The common causes are retrieval that was never tuned on real documents, no evaluation set so nobody can measure a change, and prompts carrying logic that belongs in code. We start with a two-week review that reproduces the failures on your own data. You get the diagnosis in writing, and it is useful even if your team does the remediation."}]},{"question":"Who actually writes the code?","objection":"seniority","answerInline":[{"type":"text","value":"Senior engineers, named before you sign, and the same ones through delivery. The person in your technical call is the person on the build. We do not run a bench of juniors behind a senior front, and we will put you in a technical session with the engineer before there is a contract if you ask."}]},{"question":"How fast can you start?","objection":"timeline","answerInline":[{"type":"text","value":"Two to four weeks from signed contract to a working team, which is our standard allocation window. The architecture review can usually start sooner because it needs fewer people. First production release depends on scope, but a focused AI feature is typically live for real users within three months."}]},{"question":"You are in Romania. Does that work for a UK company?","objection":"other","answerInline":[{"type":"text","value":"It works well and has done for years. We are an EU company delivering from Cluj-Napoca, on Central European Time, which overlaps the UK working day almost entirely. Projects run in English, contracts are EU law, and GDPR is our home regime rather than an export requirement. Most UK clients meet us on video and never notice the border."}]},{"question":"Where does our data go?","objection":"data-residency","answerInline":[{"type":"text","value":"It stays inside the EEA by default, and a DPA is part of the standard paperwork rather than an add-on. Where data cannot leave your environment at all, we run open-weight models inside your own infrastructure instead of calling a hosted API. We settle residency, retention and the training-opt-out position during the architecture review, before any code is written."}]},{"question":"Who owns the IP?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You do, transferring on full payment. That covers the code, the prompts, the eval sets and the infrastructure configuration, including anything we build on top of our own internal tooling. It is in the standard contract, not a premium tier."}]},{"question":"Will we be locked into you, or into a model vendor?","objection":"lock-in","answerInline":[{"type":"text","value":"Neither, by design. Everything runs in your cloud account and is documented for handover. We keep model calls behind an internal interface so a provider swap is a configuration change validated by the eval suite. Some clients keep us for the next feature; others take it in house after the first release, which is a fine outcome and one we plan for."}]},{"question":"What happens after launch?","objection":"after-launch","answerInline":[{"type":"text","value":"Every AI feature ships with an eval set in CI, guardrails, traces and a cost dashboard, so your team can see quality and spend without asking us. We offer a support retainer, but it is optional and the handover documentation assumes you may not want it. If quality drifts, the alert reaches you first."}]},{"question":"Will this sideline our in-house engineers?","objection":"sideline-our-team","answerInline":[{"type":"text","value":"The opposite is the goal. We work inside your repositories, your review process and your standards, and we pair with your engineers on the parts they will own. If you would rather add senior capacity to your own team than outsource a project, that is "},{"type":"link","label":"staff augmentation","href":"/staff-augmentation-company-uk"},{"type":"text","value":" and we do that too."}]},{"question":"Do you only build AI, or the product around it?","objection":"other","answerInline":[{"type":"text","value":"Both, and the second is usually the larger part. Most of an AI product is ordinary software done well. We also build "},{"type":"link","label":"AI agent development","href":"/ai-agent-development-company"},{"type":"text","value":" and "},{"type":"link","label":"RAG development","href":"/rag-development-company"},{"type":"text","value":" engagements, and "},{"type":"link","label":"AI automation","href":"/ai-automation-agency-uk"},{"type":"text","value":" work where the problem is operational rather than product-shaped. You can see "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" before you talk to us."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Start with a technical call","sub":"Bring your architecture, your prototype or your three quotes. You will get a senior engineer's honest read on what is solid, what will break, and what it should cost."}},"sourceFile":"7code-build/content/pages/ai-development-company-uk.mdx"},"mvp-development-agency-uk":{"spec":{"status":"approved","kind":"money","meta":{"slug":"mvp-development-agency-uk","title":"MVP Development Agency UK | Scope First, Then Build | 7code","metaDescription":"MVP development agency for UK founders. We scope and price the build before you commit, ship with senior engineers only, and you own every line of the code.","canonical":"https://www.7code.tech/mvp-development-agency-uk/","ogImage":"/og/mvp-development-agency-uk.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"mvp development agency uk","secondaryKeywords":["mvp development company uk","build an mvp uk","mvp app development agency","startup mvp developers uk","mvp development cost uk"],"icpSegment":"new-product","searchIntent":"commercial","flywheelStage":"find","difficultyNote":"Small UK agency field with real money pages but low domain authority. Differentiation in the observed set is thin and mostly timeline-based — one incumbent (Magora) anchors on a \"production apps in 6–8 weeks\" promise. No competitor in the field publishes a price or a scoping step, so a costed, phase-gated offer with named senior engineers is a clear opening. Qualitative only — no verified volume data available (Ahrefs plan blocked).\n"},"cta":{"label":"Book an MVP scoping call","action":"booking","href":"/book/mvp-scoping","reassurance":"45 minutes. Bring the idea, not a spec. You'll leave with a realistic scope and a price range, whether or not you work with us."},"blocks":["hero","trustStrip","diagnosis","successHorizon","proof","cta","whatWeBuild","howWeDeliver","package","cta","pointOfView","faq","close"],"proof":[{"caseStudySlug":"wholesum","metric":"Named Clutch testimonial from Emily Kucharski, CEO & Co-founder","tags":[{"label":"Product design","href":"/service/ai-product-engineering"},{"label":"AI product engineering","href":"/service/ai-product-engineering"}]},{"caseStudySlug":"daily8","metric":"Product taken from concept to a shipped build by one senior team","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"Cloud infrastructure","href":"/service/cloud-agentic-infra"}]}],"internalLinks":[{"anchor":"product design","href":"/service/ai-product-engineering","placement":"whatWeBuild"},{"anchor":"AI product engineering","href":"/service/ai-product-engineering","placement":"whatWeBuild"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatWeBuild"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatWeBuild"},{"anchor":"cloud infrastructure","href":"/service/cloud-agentic-infra","placement":"whatWeBuild"},{"anchor":"Clickable prototype + validated scope","href":"/mvp-development-agency-uk","placement":"package"},{"anchor":"Production MVP","href":"/mvp-development-agency-uk","placement":"package"},{"anchor":"staff augmentation","href":"/staff-augmentation-company-uk","placement":"faq"},{"anchor":"AI automation","href":"/ai-automation-agency-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"product work","href":"/case-studies","placement":"faq"},{"anchor":"what an MVP costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"MVP development agency UK founders use to ship a first product","sub":"For the non-technical founder with money on a clock and their name attached to whether this works. We define and price the build before you commit to it."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"diagnosis":{"rich":[{"type":"h2","text":"You have two quotes and no way to tell which one is honest"},{"type":"p","inline":[{"type":"text","value":"One agency came back with £15,000. Another came back with £120,000. You described the same product to both of them, in the same words, on the same call. Nobody has explained the gap, and you cannot tell whether the cheap one is missing something or the expensive one is padding."}]},{"type":"p","inline":[{"type":"text","value":"Or you already picked. You went with the cheap team, four months went past, and what came back was a demo that impressed nobody — not your first users, not the investor you showed it to, not you. The code underneath is not something a second team wants to touch."}]},{"type":"p","inline":[{"type":"text","value":"Here is the thing neither quote told you. That spread is not usually dishonesty. It is that nobody has written down what is actually being built, so both numbers are guesses about different products. A guess with a smaller number attached is still a guess. It just fails later."}]},{"type":"p","inline":[{"type":"text","value":"So we do not quote a build from a conversation. We define it first, as a paid piece of work with its own price and its own deliverable. Then the build number is a number, not a hope."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"successHorizon":{"heading":"What this looks like from where you're sitting","horizons":[{"type":"horizon","label":"In 12 months","inline":[{"type":"text","value":"you have a product with a roadmap, not a prototype that needs a rewrite. The architecture was built to be extended, the code is documented, and whoever comes next — your own hire, another firm, or us — can pick it up without starting again."}]}]},"proof":{"rich":[{"type":"h2","text":"Two we can talk about"},{"type":"p","inline":[{"type":"bold","value":"WholeSum"},{"type":"text","value":" — built with a founding team, design and engineering under one roof. Emily Kucharski, CEO & Co-founder, put her name to a public review of the work on Clutch, which founders tend to weigh more heavily than a logo. Tags: "},{"type":"link","label":"Product design","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" → "},{"type":"link","label":"Read the WholeSum case study","href":"/case-study/wholesum"}]},{"type":"p","inline":[{"type":"bold","value":"Daily8"},{"type":"text","value":" — a product taken from concept to a shipped build by a single senior team, with no handover between a design shop and a development shop in the middle. Tags: "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"Cloud infrastructure","href":"/service/cloud-agentic-infra"},{"type":"text","value":" → "},{"type":"link","label":"Read the Daily8 case study","href":"/case-study/daily8"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book an MVP scoping call"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatWeBuild":{"rich":[{"type":"h2","text":"What we actually build"},{"type":"ul","items":[[{"type":"bold","value":"A clickable prototype"},{"type":"text","value":" — the real screens and the real flow, in your hands in weeks. Something you can test on users and show an investor, before a line of production code exists."}],[{"type":"bold","value":"A validated scope and build plan"},{"type":"text","value":" — every feature in version one written down, sized, and priced, with the things we recommend cutting listed separately and honestly."}],[{"type":"bold","value":"The production MVP"},{"type":"text","value":" — web or mobile, built to carry real users and real money. Accounts, payments, permissions, admin tooling, the unglamorous parts that decide whether it survives contact with people."}],[{"type":"bold","value":"[AI features where they earn their place](/service/llm-agent-development)"},{"type":"text","value":" — an assistant, an extraction step, an agent that removes manual work. Shipped with evals and guardrails, not bolted on because the deck needed the word."}],[{"type":"bold","value":"[System integrations](/service/system-integrations)"},{"type":"text","value":" — the payment provider, the CRM, the data source your product depends on. Usually where an underpriced quote quietly runs aground."}],[{"type":"bold","value":"[Cloud infrastructure](/service/cloud-agentic-infra)"},{"type":"text","value":" — deployed into your own account, with environments, backups and monitoring. Your product does not live on our servers."}],[{"type":"bold","value":"Instrumentation you can raise money on"},{"type":"text","value":" — analytics and event tracking wired in from day one, so your next conversation with an investor uses your usage data rather than your opinion."}],[{"type":"bold","value":"A handover pack"},{"type":"text","value":" — repository, documentation, architecture notes, credentials. Written for a team that has never met us."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howWeDeliver":{"rich":[{"type":"h2","text":"How we work, and what that protects you from"},{"type":"ul","items":[[{"type":"bold","value":"Scope is a separate, paid, three-to-four-week step."},{"type":"text","value":" It ends before you commit to a build. This is what stops the £15,000-versus-£120,000 problem, because by then the thing being priced is defined."}],[{"type":"bold","value":"Senior engineers only, and the same ones throughout."},{"type":"text","value":" The person on your first call is the person who writes the code. Nothing gets handed down to a junior team once the contract is signed."}],[{"type":"bold","value":"You approve each phase before it starts."},{"type":"text","value":" The build is split into phases with their own scope and their own number. You can stop at the end of any of them and keep everything produced so far."}],[{"type":"bold","value":"You own it from the first commit."},{"type":"text","value":" The repository is yours, in your organisation, from day one. Not transferred at the end, not held as commercial protection."}],[{"type":"bold","value":"A working demo every week."},{"type":"text","value":" Not a status deck and not a percentage. Software you can click, on a URL, every week. It is the only honest measure of progress and it makes bad news arrive early."}],[{"type":"bold","value":"Your data stays in the EU."},{"type":"text","value":" We are an EU company delivering from Romania. GDPR posture, a DPA and data residency are settled during scoping, not discovered during diligence."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"Buy the scope before you buy the build"},{"type":"p","inline":[{"type":"bold","value":"Clickable prototype + validated scope — 3 to 4 weeks"}]},{"type":"p","inline":[{"type":"text","value":"We run the product discovery, design the core screens, and build a clickable prototype you can put in front of real people. Alongside it you get a written scope: what version one contains, what it does not, what each part costs, and what we would cut if the budget were smaller than it is."}]},{"type":"p","inline":[{"type":"text","value":"You own the prototype and the document. If you take them to another agency, they can quote from them — and the quotes will finally be comparable, because everyone is pricing the same product."}]},{"type":"p","inline":[{"type":"bold","value":"From €8,000."},{"type":"text","value":" What moves it is the number of user journeys and whether an integration or an AI feature has to be proven before scoping can close."}]},{"type":"p","inline":[{"type":"bold","value":"Production MVP — 3 to 5 months, typically €40,000–€90,000."}]},{"type":"p","inline":[{"type":"text","value":"The build itself, phased and approved as it goes. What moves the number is platform count, the depth of the integrations, and whether the product needs regulated-grade data handling on day one."}]},{"type":"p","inline":[{"type":"text","value":"→ "},{"type":"link","label":"Clickable prototype + validated scope","href":"/mvp-development-agency-uk"},{"type":"text","value":" · then, if the scope holds up, the "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":"."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"pointOfView":{"rich":[{"type":"h2","text":"Our point of view"},{"type":"p","inline":[{"type":"text","value":"An MVP is not a cheap version of your product. It is the smallest thing that produces a real answer from a real user, built well enough that a good answer can be built on rather than thrown away."}]},{"type":"p","inline":[{"type":"text","value":"Most of the founder pain we see comes from getting that backwards. Teams either build the whole roadmap because it was in the deck, and run out of money before anyone uses it, or they buy the cheapest possible demo and learn nothing, because nobody trusts a product that falls over. The first mistake costs your runway. The second costs four months and your credibility with the people you showed it to."}]},{"type":"p","inline":[{"type":"text","value":"We would rather spend three weeks proving the scope is wrong than five months building it. That is also the commercially inconvenient position, which is roughly how you can tell we mean it."}]},{"type":"p","inline":[{"type":"bold","value":"Who we are not for:"},{"type":"text","value":" if the decision comes down to the lowest number on the quote, we will lose and we should. We are not the cheapest team in this field and we will not pretend a fixed £15,000 buys a product with users on it. If you want the full roadmap built before a single user touches anything, we are also the wrong partner — we will argue with you about it in the first meeting."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does an MVP actually cost with you?","objection":"price","answerInline":[{"type":"text","value":"Two numbers, because they are two decisions. The "},{"type":"link","label":"Clickable prototype + validated scope","href":"/mvp-development-agency-uk"},{"type":"text","value":" step is "},{"type":"bold","value":"from €8,000"},{"type":"text","value":" over three to four weeks. The "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":" that follows typically runs "},{"type":"bold","value":"€40,000–€90,000"},{"type":"text","value":" over three to five months. What moves you up that band: more than one platform, payments or regulated data, integrations with systems we cannot test until we have access, and AI features that need evals before they can be trusted. What moves you down: one platform, one core user journey, and a founder willing to cut. We price the build only after scoping, so the number you get is based on a defined product. More detail in "},{"type":"link","label":"what an MVP costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"What happens if we run out of money mid-build?","objection":"price","answerInline":[{"type":"text","value":"You stop, and you keep everything. The build runs in phases with their own scope and their own price, and each one ends in working, deployed software rather than a half-finished branch. If funding does not land, you end the engagement at the last completed phase, you own the code and the infrastructure, and nothing is held back. We would rather have that conversation in month two than discover it in month four, so tell us early — we have re-cut scope down to a smaller version one more than once, and it is a better outcome than everybody pretending. We are also happy to invoice against phase milestones rather than a fixed monthly figure if that matches your cash position better."}]},{"question":"Do we own the code, and could another team pick it up?","objection":"ip-ownership","answerInline":[{"type":"text","value":"Yes to both, and the second one matters more than founders expect. The repository sits in your organisation from the first commit, and IP transfers to you on full payment, including anything built on top of our own internal tooling. It is in the standard contract, not an upsell. On the handover question: we write documentation, architecture notes and a runbook for a team that has never spoken to us, we deploy into your own cloud account, and we use mainstream frameworks rather than something only we can maintain. If you hire an in-house team next year and they want us gone, that should take a week, not a rewrite."}]},{"question":"How fast can you actually ship?","objection":"timeline","answerInline":[{"type":"text","value":"The prototype and scope take three to four weeks. A production MVP is usually three to five months from kickoff, and we have delivered inside that — Hera Health Tech went from start to a shipped MVP in three months. Be careful with anyone promising a production app in six to eight weeks. It is achievable for a genuinely small product, and it is a very effective way to sell a build that later needs rewriting. We will tell you in scoping whether your idea is a six-week product or a five-month one, and it is not always the answer the founder wanted."}]},{"question":"Who is actually writing the code?","objection":"seniority","answerInline":[{"type":"text","value":"Senior engineers, and the same people from the scoping call to launch. We do not run an account manager layer and we do not staff a build with juniors supervised by someone you never meet. Ask to meet the engineer before you sign anything — we would rather you did, and a firm that will not arrange it is telling you something."}]},{"question":"I'm non-technical. How do I know I'm not being sold more than I need?","objection":"other","answerInline":[{"type":"text","value":"This is the right question and most founders are too polite to ask it. Three practical defences. First, the scope document lists what we recommend cutting, in writing, before you spend anything on a build. Second, the phases are separately priced, so you are never approving one large opaque number. Third, ask us to explain any line item in terms of what breaks if we skip it — if the answer is vague, push back. You can also see "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" in detail before any of this."}]},{"question":"We hired a cheap team before and got a demo that went nowhere. Why is this different?","objection":"failed-before","answerInline":[{"type":"text","value":"Because the failure usually happened before any code was written. A cheap build tends to be priced against a conversation rather than a specification, so the team builds the interpretation that fits the budget and the gap surfaces at demo time. We separate defining from building precisely so that gap appears in week two, when it costs a fraction. We can also review what you already have and tell you honestly whether it is salvageable or whether starting again is cheaper. Sometimes it is salvageable."}]},{"question":"Will this be investor-ready?","objection":"other","answerInline":[{"type":"text","value":"It will be a real product with real users, which is the thing investors are actually assessing. We instrument the MVP from day one so you can show usage, retention and funnel data rather than screenshots. What we will not do is build features to make a demo look impressive to a room while the product does nothing for the people using it. That is a trade founders are sometimes tempted by and it does not survive the second meeting."}]},{"question":"What happens after launch?","objection":"after-launch","answerInline":[{"type":"text","value":"The first weeks after real users arrive are when you learn the most, so we usually stay for a short stabilisation period, then move to whatever fits. Some founders keep a "},{"type":"link","label":"dedicated senior engineer","href":"/staff-augmentation-company-uk"},{"type":"text","value":" on a monthly basis, typically "},{"type":"bold","value":"€6,400–€8,000"},{"type":"text","value":", to keep shipping. Others take it fully in house — the handover pack is written on the assumption that they will. Support is a retainer, it is optional, and it is not how we make the project work commercially."}]},{"question":"Where does our data live, and can we get an NDA first?","objection":"data-residency","answerInline":[{"type":"text","value":"Data stays inside the EEA by default. We are an EU company delivering from Romania, a DPA is part of the standard paperwork, and we deploy into your own cloud account rather than ours. We will sign an NDA before the first call if you would prefer, and plenty of founders do."}]},{"question":"Does our MVP need AI in it?","objection":"other","answerInline":[{"type":"text","value":"Often not, and we will say so. AI belongs in a first version when it removes real work or makes something possible that was not — document extraction, an assistant that saves your user twenty minutes, an agent that handles triage. Where it earns its place we build it properly, with evals and guardrails, through "},{"type":"link","label":"LLM and agent development","href":"/service/llm-agent-development"},{"type":"text","value":". Where it is there because the deck mentioned it, it adds cost, latency and a new way to fail in front of your first users."}]},{"question":"What if what we need turns out not to be an MVP?","objection":"other","answerInline":[{"type":"text","value":"Then we say so on the call, before there is anything to protect. Sometimes the real problem is an existing product that needs "},{"type":"link","label":"AI automation","href":"/ai-automation-agency-uk"},{"type":"text","value":" rather than a new build, and sometimes a founder with a technical co-founder just needs senior capacity, which is "},{"type":"link","label":"staff augmentation","href":"/staff-augmentation-company-uk"},{"type":"text","value":" rather than an agency engagement. You can see the "},{"type":"link","label":"product work","href":"/case-studies"},{"type":"text","value":" we have delivered and judge for yourself."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Start with scoping, not a build contract","sub":"Three to four weeks, a clickable prototype and a written scope you own, and a build price based on a defined product rather than a conversation."}},"sourceFile":"7code-build/content/pages/mvp-development-agency-uk.mdx"},"nearshore-software-development-uk":{"spec":{"status":"approved","kind":"money","meta":{"slug":"nearshore-software-development-uk","title":"Nearshore Software Development UK | Romania Teams | 7code","metaDescription":"Nearshore software development for UK companies, delivered from Romania. Full working-day overlap, EU law and GDPR, senior engineers live in 2-4 weeks.","canonical":"https://www.7code.tech/nearshore-software-development-uk/","ogImage":"/og/nearshore-software-development-uk.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"nearshore software development uk","secondaryKeywords":["nearshore development romania","nearshore vs offshore development","nearshore software development company","nearshore development team europe","uk nearshore software outsourcing"],"icpSegment":"outstaffing","searchIntent":"commercial","flywheelStage":"find","difficultyNote":"The unmodified head term is held by Intellias and N-iX at DR 70+ with roughly fifteen years of accumulated link equity, and is not realistically contestable. The UK-qualified variant is a different SERP: fewer entrenched service pages, more listicles, and a buyer whose intent is already narrowed to a UK-to-EEA engagement. It also converts better, because the qualifier means the visitor has already accepted the model and is now choosing a country and a supplier. Qualitative assessment from manual SERP inspection. No verified volume data available.\n"},"cta":{"label":"Book a technical call","action":"booking","href":"/book/technical-call","reassurance":"45 minutes with an engineer, not a salesperson. Bring your stack and your compliance questions. You'll get a straight answer on fit, timeline and rate."},"blocks":["hero","trustStrip","diagnosis","successHorizon","proof","cta","whatWeBuild","howWeDeliver","package","cta","pointOfView","faq","close"],"proof":[{"caseStudySlug":"g42-fleet","metric":"Two-year engagement — fleet platform deployed at EXPO 2020 scale","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI product engineering","href":"/service/ai-product-engineering"}]},{"caseStudySlug":"lidl-road-safety","metric":"Road-safety programme platform delivered for Lidl Romania","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"System integrations","href":"/service/system-integrations"}]}],"internalLinks":[{"anchor":"AI product engineering","href":"/service/ai-product-engineering","placement":"whatWeBuild"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatWeBuild"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatWeBuild"},{"anchor":"dedicated engineer","href":"/staff-augmentation-company-uk","placement":"package"},{"anchor":"dedicated pod","href":"/staff-augmentation-company-uk","placement":"package"},{"anchor":"staff augmentation","href":"/staff-augmentation-company-uk","placement":"faq"},{"anchor":"AI automation","href":"/service/ai-automation","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"nearshore versus offshore","href":"/nearshore-software-development-uk","placement":"faq"},{"anchor":"Production MVP","href":"/mvp-development-agency-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"Nearshore software development UK teams can run like their own","sub":"For engineering leaders who want senior capacity in the same working day, under EU law, with GDPR and IP settled before anyone gets repo access. We deliver from Cluj-Napoca, two hours ahead of London."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"diagnosis":{"rich":[{"type":"h2","text":"The model is not the question any more. The country is."},{"type":"p","inline":[{"type":"text","value":"You have already done the maths on hiring in London. You know what a senior contractor costs per day and how long the last permanent hire took. You are not looking for a case for going nearshore. You made it."}]},{"type":"p","inline":[{"type":"text","value":"What you are actually weighing is narrower and harder. Whether your data can legally sit where the team sits. Whether IP assignment holds in a foreign jurisdiction if a relationship ends badly. Whether the overlap is a real working day or four hours and a lot of goodwill. Whether the engineers are as senior as the profiles say. And whether your board will accept the answer."}]},{"type":"p","inline":[{"type":"text","value":"Most suppliers answer this with a map and a cost-saving percentage. That is not an answer. It is the part of the conversation before the answer."}]},{"type":"p","inline":[{"type":"text","value":"So this page does the objection work instead. Timezone, legal frame, data residency, IP, English, cost, and why Romania rather than somewhere cheaper. If any of it does not hold up, you should not sign."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"successHorizon":{"heading":"What this looks like from where you're sitting","horizons":[{"type":"horizon","label":"In 2 weeks","inline":[{"type":"text","value":"the paperwork is done and the team is in. MSA, DPA and IP assignment signed, access provisioned under your controls, engineers in your Slack and your standup. Your legal and security review happened before start, not in parallel with it."}]},{"type":"horizon","label":"In 3 months","inline":[{"type":"text","value":"the nearshore engineers are indistinguishable from your in-house team in every practical way that matters. Same board, same review process, same on-call expectations. Your product lead has stopped scheduling separate calls for them."}]},{"type":"horizon","label":"In 12 months","inline":[{"type":"text","value":"you have a stable team that knows your domain and your history, at a cost per engineer that let you fund a second workstream. Nothing about the arrangement is a standing item on your risk register."}]}]},"proof":{"rich":[{"type":"h2","text":"Two we can talk about"},{"type":"p","inline":[{"type":"bold","value":"G42"},{"type":"text","value":" — a fleet management platform delivered over a two-year engagement and deployed at EXPO 2020 scale. Long engagements are the honest test of a nearshore team, because the same people have to still be there in year two. Tags: "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" · "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" → "},{"type":"link","label":"Read the G42 case study","href":"/case-study/g42-fleet"}]},{"type":"p","inline":[{"type":"bold","value":"Lidl Romania"},{"type":"text","value":" — a road-safety programme platform built for a client with enterprise procurement, enterprise security review and no appetite for surprises. Tags: "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" → "},{"type":"link","label":"Read the Lidl case study","href":"/case-study/lidl-road-safety"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book a technical call"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatWeBuild":{"rich":[{"type":"h2","text":"What a nearshore team from us actually does"},{"type":"ul","items":[[{"type":"bold","value":"Product engineering teams"},{"type":"text","value":" — a pod that owns an area of your product end to end, from ticket to production. See "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":"."}],[{"type":"bold","value":"Team extension"},{"type":"text","value":" — individual senior engineers embedded in your existing squads, working your process rather than a parallel one."}],[{"type":"bold","value":"AI and LLM engineering"},{"type":"text","value":" — "},{"type":"link","label":"LLM and agent development","href":"/service/llm-agent-development"},{"type":"text","value":", retrieval pipelines, evals, guardrails, traces and cost controls, shipped to production rather than demoed."}],[{"type":"bold","value":"Platform and DevOps"},{"type":"text","value":" — CI/CD, infrastructure as code, cloud cost control, release engineering."}],[{"type":"bold","value":"[System integrations](/service/system-integrations)"},{"type":"text","value":" — the connective work between systems that were never designed to talk, including the migrations nobody wants to own."}],[{"type":"bold","value":"Data engineering"},{"type":"text","value":" — pipelines, warehousing and the reporting layer your operations team keeps rebuilding by hand."}],[{"type":"bold","value":"Legacy modernisation"},{"type":"text","value":" — taking a codebase that has outgrown its original decisions and reshaping it without stopping delivery."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howWeDeliver":{"rich":[{"type":"h2","text":"The objections, answered properly"},{"type":"ul","items":[[{"type":"bold","value":"Timezone: a full working day, not a window."},{"type":"text","value":" Cluj-Napoca is UTC+2 in winter and UTC+3 in summer, two hours ahead of London. Your 9am standup is our 11am and our day runs past yours. There is no overnight handover, no waiting until tomorrow for an answer, and no 6am call to catch anyone."}],[{"type":"bold","value":"Legal frame: one jurisdiction, familiar instruments."},{"type":"text","value":" We are SEVEN CODE DEVELOPMENT SRL, a Romanian company inside the EU single market. Contracts run under EU law with the instruments your counsel already reviews: MSA, DPA, NDA, IP assignment. Post-Brexit this is a supplier relationship, not a legal novelty, and nothing here needs a bespoke enforcement plan."}],[{"type":"bold","value":"Data residency and GDPR: EEA by default."},{"type":"text","value":" Romania is an EU member state, so personal data stays inside the EEA without a transfer mechanism. GDPR applies to us directly as controller or processor. Where data cannot leave your environment at all, engineers work inside your cloud accounts and we run open-weight models in your infrastructure instead of calling a hosted API."}],[{"type":"bold","value":"IP: assigned to you, enforceable where it matters."},{"type":"text","value":" Ownership transfers on full payment under EU law, and every engineer signs a personal IP assignment and confidentiality agreement with us. The chain of title runs unbroken from the individual to you. There is no third-country step in it."}],[{"type":"bold","value":"English: working language, not a second language at work."},{"type":"text","value":" Romania consistently ranks among the strongest English-speaking countries in continental Europe. Every engineer we place interviews with you in English before you commit, so you are not taking our word for it."}],[{"type":"bold","value":"Cost: lower than a UK contractor, and not cheap."},{"type":"text","value":" A dedicated senior engineer is typically €6,400–€8,000 per month, all in. That sits well below the loaded cost of a comparable London contractor and well above the bottom of the global market. We are not competing on price, and a supplier who is will eventually staff your project accordingly."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"Nearshore, offshore or a UK contractor — an honest comparison"},{"type":"p","inline":[{"type":"text","value":"There is no universally right answer here. The three models fail and succeed in different places, and the correct choice depends on how much real-time collaboration your work needs."}]},{"type":"table","rows":[[[],[{"type":"text","value":"Nearshore CEE (us)"}],[{"type":"text","value":"Offshore Asia"}],[{"type":"text","value":"UK contractor"}]],[[{"type":"bold","value":"Timezone overlap with UK"}],[{"type":"text","value":"Effectively the full working day, 1–2 hours ahead"}],[{"type":"text","value":"Typically a few hours at the edges of each day"}],[{"type":"text","value":"Identical"}]],[[{"type":"bold","value":"Rate band"}],[{"type":"text","value":"Mid — materially below UK, above global entry rates"}],[{"type":"text","value":"Lowest of the three"}],[{"type":"text","value":"Highest of the three"}]],[[{"type":"bold","value":"Legal frame"}],[{"type":"text","value":"EU law, GDPR direct, EEA data residency"}],[{"type":"text","value":"Third-country transfer mechanism required"}],[{"type":"text","value":"UK law, simplest of the three"}]],[[{"type":"bold","value":"Communication overhead"}],[{"type":"text","value":"Low — same-day decisions, live pairing possible"}],[{"type":"text","value":"Higher — async by necessity, written specs must carry more"}],[{"type":"text","value":"Lowest"}]],[[{"type":"bold","value":"Best fit"}],[{"type":"text","value":"Long-running product work needing daily collaboration"}],[{"type":"text","value":"Well-specified, self-contained workstreams at volume"}],[{"type":"text","value":"Short, urgent, or highly regulated onsite work"}]]]},{"type":"p","inline":[{"type":"text","value":"Offshore delivery genuinely works when the scope is stable and the interface between teams is a written specification. Plenty of good engineering happens that way. It works badly when the work is discovery-heavy and the answer to a design question needs to arrive the same afternoon."}]},{"type":"p","inline":[{"type":"text","value":"A UK contractor is the right call for short engagements, onsite requirements, or work where an extra legal hop is not worth the saving. They are the wrong call when you need three people for a year."}]},{"type":"p","inline":[{"type":"bold","value":"What we charge."},{"type":"text","value":" A dedicated senior engineer is typically "},{"type":"bold","value":"€6,400–€8,000 per month"},{"type":"text","value":". An architect is typically "},{"type":"bold","value":"€9,600–€12,800 per month"},{"type":"text","value":". A pod of an architect plus two senior engineers typically sits between "},{"type":"bold","value":"€22,000 and €29,000 per month"},{"type":"text","value":". What moves the number inside the band is stack scarcity, seniority and whether the role needs specific domain experience. Rates are all-in and cover employment, equipment and management overhead on our side."}]},{"type":"p","inline":[{"type":"text","value":"→ "},{"type":"link","label":"dedicated engineer","href":"/staff-augmentation-company-uk"},{"type":"text","value":" · "},{"type":"link","label":"dedicated pod","href":"/staff-augmentation-company-uk"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"pointOfView":{"rich":[{"type":"h2","text":"Our point of view"},{"type":"p","inline":[{"type":"text","value":"Romania is not a cost story we are apologising for. It is the reason the engineering is good."}]},{"type":"p","inline":[{"type":"text","value":"The country has a deep technical education pipeline, a two-decade product engineering industry, and enough local and international employers that a weak engineer does not stay senior for long. Cluj in particular is a university city with a real engineering market. We compete for people against the same firms you have heard of, and we pay accordingly. That is why our rates are not the lowest available and why we do not want them to be."}]},{"type":"p","inline":[{"type":"text","value":"The pitch we refuse to make is the one built on a savings percentage. If the only reason to work with a team is that they cost less, the relationship has no floor under it. Someone will always be cheaper next year, and you will spend the saving on rework and management attention."}]},{"type":"p","inline":[{"type":"bold","value":"Who we are not for:"},{"type":"text","value":" if your primary decision criterion is day rate, we are the wrong partner. You will find teams at a fraction of our cost and some of them are competent. Buy on rate and you should buy elsewhere. We are for teams choosing on delivery risk."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does nearshore development actually cost per month?","objection":"price","answerInline":[{"type":"text","value":"A "},{"type":"link","label":"dedicated engineer","href":"/staff-augmentation-company-uk"},{"type":"text","value":" at senior level is typically "},{"type":"bold","value":"€6,400–€8,000 per month"},{"type":"text","value":", working full time on your team only. An architect usually sits between "},{"type":"bold","value":"€9,600 and €12,800 per month"},{"type":"text","value":". A "},{"type":"link","label":"dedicated pod","href":"/staff-augmentation-company-uk"},{"type":"text","value":" of an architect plus two senior engineers is typically "},{"type":"bold","value":"€22,000–€29,000 per month"},{"type":"text","value":". What moves the number inside those bands is stack scarcity, the seniority level you need and whether the role requires specific domain experience. Rates are all-in: no recruitment fee, no setup fee, no separate management charge. The comparison worth running is not against a salary but against the loaded cost of a UK contractor doing the same work. More on that in "},{"type":"link","label":"nearshore versus offshore","href":"/nearshore-software-development-uk"},{"type":"text","value":"."}]},{"question":"How much timezone overlap do we really get?","objection":"other","answerInline":[{"type":"text","value":"Cluj-Napoca is UTC+2 in winter and UTC+3 in summer, so two hours ahead of the UK year-round. Your 9am is our 11am and our working day extends past yours. That is a full overlap in practice: same-day code review, live pairing, decisions made in the afternoon rather than tomorrow morning. It is the single biggest operational difference between this and a delivery centre eight hours away, and it is why we do not run follow-the-sun handovers."}]},{"question":"Why Romania rather than Poland, Ukraine or India?","objection":"other","answerInline":[{"type":"text","value":"Poland is a strong market and a fair comparison. It sits in the same timezone band, the same EU legal frame and generally a higher rate band, so if budget is not a factor the two are close. Ukraine has excellent engineers and a long track record, but it is outside the EU, which adds a data transfer mechanism, and the war introduces continuity questions your board will reasonably ask. India has enormous depth of talent and the lowest rates of the three, and it works well for well-specified, stable workstreams. It works less well when your work is discovery-heavy and needs answers the same afternoon. Romania sits where we think the trade-off is best for UK product teams: EU law, full day overlap, and senior engineering at a mid rate band."}]},{"question":"Will our data leave the EEA, and how does GDPR work here?","objection":"data-residency","answerInline":[{"type":"text","value":"No, not by default. Romania is an EU member state, so personal data stays inside the EEA with no transfer mechanism needed. GDPR applies to us directly and we sign a DPA as part of standard paperwork, before anyone gets access. Engineers normally work inside your own cloud accounts under your access controls, so in most engagements we are not holding your data at all. Where data cannot leave your environment even for model inference, we run open-weight models inside your infrastructure rather than calling a hosted API."}]},{"question":"Who owns the IP, and does that hold up across borders?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You do, transferring on full payment, assigned under the contract. Two things make it hold. First, every engineer signs a personal IP assignment and confidentiality agreement with us, so the chain runs from the individual to us to you with no gap. Second, both parties are inside the EU single market, which means a familiar enforcement route rather than a third-country one. We will sign your NDA and your MSA if you have your own; we have ours if you do not."}]},{"question":"How good is the English, honestly?","objection":"other","answerInline":[{"type":"text","value":"Good enough that it stops being a topic after week one. Romania consistently ranks among the strongest English-speaking countries in continental Europe, and the engineering industry here has worked in English for two decades. You do not have to take that on trust: every engineer interviews with your team in English before you commit, and you can weight communication as heavily as you like in that interview."}]},{"question":"What are the contracting mechanics post-Brexit?","objection":"other","answerInline":[{"type":"text","value":"Straightforward. You contract with SEVEN CODE DEVELOPMENT SRL, a Romanian company, as a service supplier. We invoice monthly, in euros or pounds, under a standard MSA plus DPA. Services do not attract customs or import duty, and the VAT treatment for a UK business buying services from an EU supplier is the reverse-charge mechanism your finance team already applies to other EU software suppliers. No entity, no employer of record and no local registration is needed on your side."}]},{"question":"How senior are the engineers, and can we interview them?","objection":"seniority","answerInline":[{"type":"text","value":"Senior means people who have owned services in production, not people who have contributed to one. You interview every candidate yourself, technically, run your way, and the engineer you interview is the engineer who starts. We do not swap profiles after signature. If we cannot staff your stack at a genuinely senior level, we say so on the first call instead of sending a near-enough CV. The model is the same as our "},{"type":"link","label":"staff augmentation","href":"/staff-augmentation-company-uk"},{"type":"text","value":" engagements."}]},{"question":"How fast can a nearshore team actually be running?","objection":"timeline","answerInline":[{"type":"text","value":"Two to four weeks from signed contract to engineers in your standup, covering interviews, notice periods and account provisioning. Common stacks sit at the shorter end. We aim for a first pull request inside two weeks of start, which means we plan the opening fortnight with your lead before day one. See "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" for the sequence."}]},{"question":"We tried outsourcing before and it did not work. What is different?","objection":"failed-before","answerInline":[{"type":"text","value":"The failures we get called into usually share a shape: nobody met the engineers, the contract was long enough that the supplier relaxed, and the team was managed by the supplier rather than by you. We remove all three on purpose. You interview. Terms are monthly rolling with one month's notice. The engineers report into your team lead and work your board. That does not guarantee success, but it means a bad fit shows up in week three and you can act on it."}]},{"question":"Can we visit, or can the team come to us?","objection":"other","answerInline":[{"type":"text","value":"Yes to both, and we encourage it early. Cluj has direct flights from London and it is a short trip. Most clients come once at the start and find it worth the day. Engineers travel to the UK for kickoffs, quarterly planning or a hard integration week where being in the room genuinely helps. Travel is arranged at cost and is not a revenue line for us."}]},{"question":"What if the real problem is not engineering capacity?","objection":"other","answerInline":[{"type":"text","value":"Then we will say so, even though it is not the sale in front of us. Sometimes a team asking for four engineers actually needs a defined scope, in which case a fixed-scope "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":" is the better shape. Sometimes the bottleneck is an operational process rather than the product backlog, which is "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" work. We would rather diagnose it correctly than staff the request as written."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Bring the objections, not just the brief","sub":"A 45-minute technical call. Bring your stack, your security questionnaire and whatever your board will ask about delivering from the EU. You will get direct answers and a rate and date, or an honest no."}},"sourceFile":"7code-build/content/pages/nearshore-software-development-uk.mdx"},"rag-development-company":{"spec":{"status":"approved","kind":"money","meta":{"slug":"rag-development-company","title":"RAG Development Company | Production RAG Systems | 7code","metaDescription":"RAG development company for teams past the naive pilot. Hybrid retrieval, reranking, citation enforcement, eval sets and EU-resident vector infrastructure.","canonical":"https://www.7code.tech/rag-development-company/","ogImage":"/og/rag-development-company.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"rag development company","secondaryKeywords":["rag development services","retrieval augmented generation company","enterprise rag implementation","rag pipeline development","build a rag system"],"icpSegment":"outstaffing","searchIntent":"commercial","flywheelStage":"find","difficultyNote":"Genuinely thin field. Nobody strong defends this term: the pages that rank are short service stubs and generic explainers of what retrieval-augmented generation means, with almost no depth on the part that decides whether a system works — retrieval quality, evaluation and grounding. The audience is small but exceptionally well qualified, usually a CTO or head of data who has already built a pilot and hit the wall. A page with real engineering substance should hold position here. Qualitative only — no verified volume data available.\n"},"cta":{"label":"Book a technical call","action":"booking","href":"/book/technical-call","reassurance":"45 minutes with a senior engineer, not a salesperson. Bring the questions your pilot gets wrong and we'll look at why."},"blocks":["hero","trustStrip","diagnosis","successHorizon","proof","cta","whatWeBuild","howWeDeliver","package","cta","pointOfView","faq","close"],"proof":[{"caseStudySlug":"hera","metric":"RAG-verified clinical AI intake — MVP shipped in 3 months","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"LLM & agent development","href":"/service/llm-agent-development"}]},{"caseStudySlug":"numerize","metric":"Platform running 6,000+ customer accounts","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI automation","href":"/service/ai-automation"}]}],"internalLinks":[{"anchor":"AI product engineering","href":"/service/ai-product-engineering","placement":"whatWeBuild"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatWeBuild"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatWeBuild"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"package"},{"anchor":"Production MVP","href":"/mvp-development-agency-uk","placement":"package"},{"anchor":"AI agent development","href":"/ai-agent-development-company","placement":"faq"},{"anchor":"AI development company UK","href":"/ai-development-company-uk","placement":"faq"},{"anchor":"AI automation","href":"/ai-automation-agency-uk","placement":"faq"},{"anchor":"staff augmentation","href":"/staff-augmentation-company-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"what AI work costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"RAG development company for teams past the naive pilot","sub":"Your model is fine. Retrieval is the problem, and it is an engineering problem — chunking, hybrid search, reranking, grounding checks, and an eval set that tells you when quality moves."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"diagnosis":{"rich":[{"type":"h2","text":"Five test questions answered perfectly. Then real documents arrived."},{"type":"p","inline":[{"type":"text","value":"The pilot took a weekend. Load the PDFs, split on a fixed character count, embed, top-k, feed the chunks to the model. On the five questions you tried, it was excellent. Then you pointed it at the actual document set and it started answering confidently from the wrong contract, missing the clause that was on the page nobody chunked cleanly, and quietly ignoring the table that held the number."}]},{"type":"p","inline":[{"type":"text","value":"Two things are now true and neither is comfortable. Nobody can say whether a given answer is grounded in a real passage or reconstructed from the model's own memory. And there is no retrieval eval set, so every improvement anyone proposes is an opinion. The team is tuning a prompt to fix a search problem."}]},{"type":"p","inline":[{"type":"text","value":"Retrieval quality is the whole game. Generation is the easy half, and it is the half that gets the attention. We start at the other end."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"successHorizon":{"heading":"What this looks like from where you're sitting","horizons":[{"type":"horizon","label":"In 3 weeks","inline":[{"type":"text","value":"you have a retrieval eval set built from your real documents and the questions your users actually ask, with a baseline for recall, precision and grounding rate. You know which failures are retrieval, which are chunking, and which are genuinely the model. That list is usually a surprise."}]},{"type":"horizon","label":"In 3 months","inline":[{"type":"text","value":"a production pipeline: ingestion that handles your real file formats, hybrid search with a reranking stage, citations enforced so every claim points at a passage, and document-level access control so a user only ever retrieves what they are permitted to see. Regressions are caught in CI, before release."}]},{"type":"horizon","label":"In 12 months","inline":[{"type":"text","value":"the corpus keeps changing and quality holds. Re-indexing is automatic, freshness is monitored, and your team adds new document types without calling us. When someone questions an answer, they open the citation and settle it in ten seconds."}]}]},"proof":{"rich":[{"type":"h2","text":"Two we can talk about"},{"type":"p","inline":[{"type":"bold","value":"Hera Health Tech"},{"type":"text","value":" — a clinical intake flow built as a retrieval-verified pipeline, with citation checks and a human approval step before anything reaches a clinician. Days of manual review became minutes, MVP shipped in three months. Tags: "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"LLM & agent development","href":"/service/llm-agent-development"},{"type":"text","value":" → "},{"type":"link","label":"Read the Hera case study","href":"/case-study/hera"}]},{"type":"p","inline":[{"type":"bold","value":"Numerize"},{"type":"text","value":" — an operational platform now running 6,000+ customer accounts, with data flowing between systems that previously required manual reconciliation. Tags: "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" · "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" → "},{"type":"link","label":"Read the Numerize case study","href":"/case-study/numerize"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book a technical call"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatWeBuild":{"rich":[{"type":"h2","text":"What we actually build"},{"type":"ul","items":[[{"type":"bold","value":"Chunking and ingestion pipelines"},{"type":"text","value":" — layout-aware parsing for PDFs, scans, spreadsheets and HTML, with tables and headers preserved rather than flattened. Chunk boundaries follow document structure, and every chunk keeps the metadata needed to filter and cite it."}],[{"type":"bold","value":"Hybrid retrieval"},{"type":"text","value":" — dense vectors plus keyword search, fused and tuned on your corpus. Pure vector search loses exact identifiers, part numbers and clause references, which is where most pilots fail."}],[{"type":"bold","value":"Reranking"},{"type":"text","value":" — a cross-encoder or model-based second pass over a wide candidate set, so the passages that reach the context window are the ones that answer the question, not merely the nearest ones."}],[{"type":"bold","value":"Grounding and citation enforcement"},{"type":"text","value":" — answers constrained to retrieved passages, span-level citations returned with the response, and a check that refuses rather than guesses when support is thin. An unsupported answer is a failure the system reports, not one your user discovers."}],[{"type":"bold","value":"Retrieval eval sets"},{"type":"text","value":" — a graded question and passage set from your own documents, scoring recall, precision, grounding rate and answer quality separately, running in CI so a change is measured."}],[{"type":"bold","value":"Freshness and re-indexing"},{"type":"text","value":" — incremental ingestion, change detection, version handling for superseded documents, and backfills that do not take the system offline."}],[{"type":"bold","value":"Access control at the document level"},{"type":"text","value":" — permissions enforced at retrieval time against your existing identity model, so a query never returns a passage the user cannot open directly."}],[{"type":"bold","value":"EU-resident vector infrastructure"},{"type":"text","value":" — the index, embeddings and document store hosted inside the EEA, in your own cloud account, with self-hosted embedding models where data cannot leave at all."}],[{"type":"bold","value":"[System integrations](/service/system-integrations)"},{"type":"text","value":" into the systems the documents already live in, plus "},{"type":"link","label":"LLM and agent development","href":"/service/llm-agent-development"},{"type":"text","value":" and "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" where retrieval is part of a wider product."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howWeDeliver":{"rich":[{"type":"h2","text":"How we work, and what that protects you from"},{"type":"ul","items":[[{"type":"bold","value":"We measure retrieval before we tune generation."},{"type":"text","value":" The eval set comes first. Otherwise every prompt change is a guess, and teams spend months improving the half that was already working."}],[{"type":"bold","value":"Citations are a requirement, not a feature."},{"type":"text","value":" If a claim cannot be traced to a passage, the system says so. That is what makes the output usable in a regulated or high-stakes setting."}],[{"type":"bold","value":"Permissions are enforced in the retriever."},{"type":"text","value":" Filtering after generation is not access control. We wire document-level rules to your identity provider before the first user sees a result."}],[{"type":"bold","value":"You meet the engineers who build it."},{"type":"text","value":" Named senior people from the first call to handover, with no account manager layer and no reassignment once the contract is signed."}],[{"type":"bold","value":"Model and vendor agnostic."},{"type":"text","value":" Embedding models, vector stores and generation models are chosen per corpus and per data-sensitivity rule, then kept behind an interface so any of them can be replaced."}],[{"type":"bold","value":"Your data stays in the EU."},{"type":"text","value":" We are an EU company delivering from Romania. Residency, retention and a DPA are settled before ingestion starts, and open-weight models run in your environment when needed."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"Start with a two-week paid retrieval review"},{"type":"p","inline":[{"type":"text","value":"Most RAG engagements here begin the same way. Two weeks, senior engineers, working on your real corpus and your real failing questions rather than a sample set."}]},{"type":"p","inline":[{"type":"text","value":"You get a written diagnosis and architecture: where your current pipeline loses information, a chunking and parsing strategy for your document types, a hybrid retrieval and reranking design, the grounding and citation approach, an access-control model, a first retrieval eval set with a measured baseline, and a phased build plan with estimates. Your engineers can act on it with or without us."}]},{"type":"p","inline":[{"type":"bold","value":"Typically €9,000–€14,000"},{"type":"text","value":", the same band as the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":". What moves it is corpus size, how messy the source formats are, and whether permissions have to be modelled from scratch."}]},{"type":"p","inline":[{"type":"text","value":"→ Where the review confirms a full build, teams usually continue into a "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":". Where the documents turn out to be a symptom of an operational problem, the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":" is the better route."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"pointOfView":{"rich":[{"type":"h2","text":"Our point of view"},{"type":"p","inline":[{"type":"text","value":"Almost every failing RAG pilot we are called into has the same shape. Serious effort went into prompts and model selection, and almost none into what gets retrieved. The pipeline splits documents on a fixed character count, runs a single vector query, takes the top five and hopes. When the answers are wrong, the team edits the prompt, because that is the part they can see."}]},{"type":"p","inline":[{"type":"text","value":"The fix is rarely exotic. Parse the document properly. Add keyword search alongside vectors. Rerank a wider candidate set. Force citations. Then build a graded eval set so the next change can be measured rather than argued about. None of that is a research problem. It is engineering discipline applied to the half of the system nobody enjoys."}]},{"type":"p","inline":[{"type":"text","value":"We also think a lot of retrieval projects should be smaller. If two hundred documents answer ninety percent of the questions, index those two hundred well instead of the whole drive badly."}]},{"type":"p","inline":[{"type":"bold","value":"Who we are not for:"},{"type":"text","value":" if you want a vector database installed and a chatbot pointed at everything you own, without an eval set and without a permission model, we will decline. That build fails slowly, and it fails in a way that damages trust in AI across your company."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does a RAG build cost?","objection":"price","answerInline":[{"type":"text","value":"It depends on corpus size, source-format mess and permission complexity, but here are the bands. A two-week paid retrieval review is typically "},{"type":"bold","value":"€9,000–€14,000"},{"type":"text","value":", the same band as the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":". A production build, a "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":", usually sits between "},{"type":"bold","value":"€40,000–€90,000"},{"type":"text","value":" over three to five months. Ongoing capacity is monthly: a dedicated senior engineer "},{"type":"bold","value":"€6,400–€8,000"},{"type":"text","value":", a dedicated architect "},{"type":"bold","value":"€9,600–€12,800"},{"type":"text","value":", a pod of an architect plus two senior engineers "},{"type":"bold","value":"€22,000–€29,000"},{"type":"text","value":". What moves those most is document variety and whether access rules must be built from nothing. More detail in "},{"type":"link","label":"what AI work costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"Our pilot works on test questions and fails on real ones. Why?","objection":"failed-before","answerInline":[{"type":"text","value":"Because the test questions were written by someone who already knew which document held the answer. Real questions use different vocabulary, span two documents, or depend on a table your parser turned into a wall of text. We rebuild the question set from actual user queries, measure retrieval separately from generation, and fix whichever is losing. It is retrieval far more often than teams expect."}]},{"question":"How do you know whether an answer is grounded?","objection":"other","answerInline":[{"type":"text","value":"We make it measurable. Answers are constrained to retrieved passages, citations are returned at span level, and an automated check verifies each claim is supported by the cited text. Grounding rate then becomes a metric in the eval suite alongside recall and answer quality. When support is thin, the correct behaviour is to say so and escalate, and we build that path deliberately."}]},{"question":"What actually goes in a retrieval eval set?","objection":"other","answerInline":[{"type":"text","value":"Real questions from your users or your support logs, each paired with the passages that genuinely answer them, graded by someone in your team who knows the domain. A hundred to three hundred items is usually enough to be decisive. We measure recall at k, precision, reranker lift, grounding rate and end-to-end answer quality separately, so a regression tells you which stage broke."}]},{"question":"Do we need to fine-tune a model?","objection":"other","answerInline":[{"type":"text","value":"Almost never for question answering over documents, and we will usually argue against it. Fine-tuning teaches tone and format, not facts, and facts are what you are missing. It also freezes knowledge that your corpus updates weekly. Fix chunking, hybrid retrieval and reranking first. If a genuine gap remains after that, we will say so with the evidence."}]},{"question":"Which vector database should we use?","objection":"other","answerInline":[{"type":"text","value":"Whichever fits your scale, filtering needs and where you are already hosted. For many corpora, Postgres with a vector extension is enough and removes a system to operate. What matters more is metadata filtering, permission-aware queries and re-index cost. We keep the store behind an interface so the decision is reversible, and we write the reasoning down during the review."}]},{"question":"Our documents are confidential. Where do they go?","objection":"data-residency","answerInline":[{"type":"text","value":"Inside the EEA by default, in your own cloud account, with a DPA as part of the standard paperwork. We are an EU company delivering from Romania, so this is our home regime. Where documents cannot leave your environment at all, we run self-hosted embedding and generation models inside your infrastructure. Residency and retention are settled before any ingestion runs."}]},{"question":"Can it respect who is allowed to see what?","objection":"other","answerInline":[{"type":"text","value":"Yes, and it must. Permissions are enforced at retrieval time against your existing identity provider, so a restricted passage is never a candidate for a user who cannot open it. Filtering after the model has already read a document is not access control. We model this in week one, because retrofitting it means re-indexing everything."}]},{"question":"Who actually builds it, and how fast can you start?","objection":"seniority","answerInline":[{"type":"text","value":"Senior engineers, named before you sign, and the same ones through delivery. Two to four weeks from signed contract to a working team, which is our standard allocation window. The retrieval review can usually start sooner. Ask for a working session with the engineer beforehand — we would rather you judged us on that than on a proposal."}]},{"question":"Who owns the IP?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You do, transferring on full payment. Pipelines, prompts, eval sets, index configuration and infrastructure code, including anything built on top of our own internal tooling. It sits in the standard contract rather than a premium tier."}]},{"question":"What happens when the documents change, and after launch generally?","objection":"after-launch","answerInline":[{"type":"text","value":"Ingestion runs incrementally with change detection, superseded versions are handled explicitly, and freshness is monitored so nobody answers from a document withdrawn last month. The build ships with the eval suite in CI, traces and a cost dashboard. A support retainer is optional, and the handover documentation assumes your team may run it alone."}]},{"question":"Is RAG even the right approach for us?","objection":"other","answerInline":[{"type":"text","value":"Sometimes not, and that is a cheap thing to find out early. Small stable document sets can go straight into context. Structured questions belong in SQL against your database, not in a retrieval pipeline. Multi-step tasks are "},{"type":"link","label":"AI agent development","href":"/ai-agent-development-company"},{"type":"text","value":", and process-shaped problems are "},{"type":"link","label":"AI automation","href":"/ai-automation-agency-uk"},{"type":"text","value":". A broader build is "},{"type":"link","label":"AI development company UK","href":"/ai-development-company-uk"},{"type":"text","value":", and if you would rather add senior capacity to your own team, that is "},{"type":"link","label":"staff augmentation","href":"/staff-augmentation-company-uk"},{"type":"text","value":". You can see "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" before you talk to us."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Start with a technical call","sub":"Bring the questions your pilot gets wrong. You will get a senior engineer's read on whether it is chunking, retrieval, ranking or grounding, and what it takes to fix."}},"sourceFile":"7code-build/content/pages/rag-development-company.mdx"},"staff-augmentation-company-uk":{"spec":{"status":"approved","kind":"money","meta":{"slug":"staff-augmentation-company-uk","title":"Staff Augmentation Company UK | Senior Engineers | 7code","metaDescription":"Staff augmentation company for UK engineering teams at capacity. Senior engineers you interview yourself, in your repo and standups, live in 2-4 weeks.","canonical":"https://www.7code.tech/staff-augmentation-company-uk/","ogImage":"/og/staff-augmentation-company-uk.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"staff augmentation company uk","secondaryKeywords":["it staff augmentation uk","software development staff augmentation","dedicated development team uk","hire senior engineers uk startup","team extension software development"],"icpSegment":"outstaffing","searchIntent":"commercial","flywheelStage":"find","difficultyNote":"Five of the seven top results on this SERP are \"top N staff augmentation companies\" listicles published by competing agencies, which means the page-one field is thin on genuine service pages. Andersen holds the only real service-page slot, running a .co.uk subsite against a global domain. The opening is specificity: named rates, named timelines, named commitments. Listicles cannot match a page that says what you get and when. Qualitative assessment only, from manual SERP inspection. No verified volume data available.\n"},"cta":{"label":"Book a technical call","action":"booking","href":"/book/technical-call","reassurance":"45 minutes with an engineer, not a salesperson. Bring your architecture and your backlog. You'll get a straight answer on whether we can staff it and when."},"blocks":["hero","trustStrip","diagnosis","successHorizon","proof","cta","whatWeBuild","howWeDeliver","package","cta","pointOfView","faq","close"],"proof":[{"caseStudySlug":"g42-fleet","metric":"Two-year engagement — fleet platform deployed at EXPO 2020 scale","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI product engineering","href":"/service/ai-product-engineering"}]},{"caseStudySlug":"numerize","metric":"6,000+ customer accounts running on the platform","tags":[{"label":"AI automation","href":"/service/ai-automation"},{"label":"System integrations","href":"/service/system-integrations"}]}],"internalLinks":[{"anchor":"AI product engineering","href":"/service/ai-product-engineering","placement":"whatWeBuild"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatWeBuild"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatWeBuild"},{"anchor":"dedicated engineer","href":"/staff-augmentation-company-uk","placement":"package"},{"anchor":"dedicated pod","href":"/staff-augmentation-company-uk","placement":"package"},{"anchor":"nearshore software development","href":"/nearshore-software-development-uk","placement":"faq"},{"anchor":"AI automation","href":"/service/ai-automation","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"what staff augmentation costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"},{"anchor":"Production MVP","href":"/mvp-development-agency-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"A staff augmentation company UK CTOs can actually plan around","sub":"For engineering leaders whose team is at capacity and whose hiring pipeline keeps stalling at offer stage. Senior engineers you interview yourself, working in your repo, on your board, inside two to four weeks."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"diagnosis":{"rich":[{"type":"h2","text":"Two roles open for five months, and the roadmap keeps moving right"},{"type":"p","inline":[{"type":"text","value":"You signed off two senior hires in the spring. One shortlist evaporated when the best candidate took a counter-offer. The second went quiet after the technical stage. Meanwhile the roadmap has slipped a quarter, then another quarter, and your board deck now has a slide explaining why."}]},{"type":"p","inline":[{"type":"text","value":"Or you already tried an agency. Three CVs arrived, two of those people never appeared on a call, and the one who did needed six weeks of hand-holding before writing anything you kept. You paid for all six weeks. Nobody wants to repeat that conversation internally."}]},{"type":"p","inline":[{"type":"text","value":"The pattern underneath both is the same. You do not have a talent problem. You have a throughput problem, and every route to fixing it either takes five months or hands you someone you never met."}]},{"type":"p","inline":[{"type":"text","value":"We solve the second one first. You interview the engineer. The engineer you interview is the engineer who starts. If that is not true, nothing else on this page matters."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"successHorizon":{"heading":"What this looks like from where you're sitting","horizons":[{"type":"horizon","label":"In 2 weeks","inline":[{"type":"text","value":"you have interviewed candidates yourself and picked. Contracts are signed, accounts are provisioned, and the engineer is in your Slack, your repo and your Monday standup. Onboarding is your normal onboarding, not a separate process we run."}]},{"type":"horizon","label":"In 3 months","inline":[{"type":"text","value":"the engineer is shipping at the pace of your own senior hires and reviewing other people's pull requests. Your team lead has stopped thinking of them as external. The two roles you could not fill are no longer the reason a quarter slips."}]},{"type":"horizon","label":"In 12 months","inline":[{"type":"text","value":"you have a stable pod that knows your domain, your legacy decisions and why that one service is the way it is. You can scale it up for a push, scale it down after, and end it on a month's notice without a redundancy conversation."}]}]},"proof":{"rich":[{"type":"h2","text":"Two we can talk about"},{"type":"p","inline":[{"type":"bold","value":"G42"},{"type":"text","value":" — a fleet management platform built and run over a two-year engagement, deployed at EXPO 2020 scale. The kind of timeline that only holds when the same engineers stay on the work. Tags: "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" · "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" → "},{"type":"link","label":"Read the G42 case study","href":"/case-study/g42-fleet"}]},{"type":"p","inline":[{"type":"bold","value":"Numerize"},{"type":"text","value":" — an operational platform now running 6,000+ customer accounts, with integrations replacing work that used to be reconciled by hand. Tags: "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" · "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" → "},{"type":"link","label":"Read the Numerize case study","href":"/case-study/numerize"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book a technical call"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatWeBuild":{"rich":[{"type":"h2","text":"The roles we staff"},{"type":"ul","items":[[{"type":"bold","value":"Senior backend engineers"},{"type":"text","value":" — Node, Python, Go, .NET, Java. People who have owned a service in production, not people who have contributed to one."}],[{"type":"bold","value":"Senior frontend and full-stack engineers"},{"type":"text","value":" — React, Next.js, TypeScript. Comfortable with design systems, accessibility and the parts of the job that are not the happy path."}],[{"type":"bold","value":"Software architects"},{"type":"text","value":" — for teams whose codebase has outgrown its original decisions. Someone to own the shape of the system while your leads keep shipping features."}],[{"type":"bold","value":"AI and ML engineers"},{"type":"text","value":" — "},{"type":"link","label":"LLM and agent development","href":"/service/llm-agent-development"},{"type":"text","value":", retrieval pipelines, evals, guardrails and observability. Engineers who have put this in production, not in a notebook."}],[{"type":"bold","value":"DevOps and platform engineers"},{"type":"text","value":" — CI/CD, infrastructure as code, cloud cost, release engineering. The work that quietly decides how fast everyone else can move."}],[{"type":"bold","value":"Data engineers"},{"type":"text","value":" — pipelines, warehousing, "},{"type":"link","label":"system integrations","href":"/service/system-integrations"},{"type":"text","value":" between tools that were never designed to talk to each other."}],[{"type":"bold","value":"QA automation engineers"},{"type":"text","value":" — test strategy and suites your team will still be running in a year."}],[{"type":"bold","value":"Full pods"},{"type":"text","value":" — an architect plus two or three senior engineers, delivering a whole area of your product. See "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" for the work we own end to end."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howWeDeliver":{"rich":[{"type":"h2","text":"The six commitments, and what each one protects you from"},{"type":"ul","items":[[{"type":"bold","value":"You interview them, and who you interview is who you get."},{"type":"text","value":" Every candidate does a technical interview with your team. No profile swaps after signature, no \"that engineer became unavailable\" the week before start. This kills the single biggest failure mode in this market."}],[{"type":"bold","value":"They join your team, not a parallel one."},{"type":"text","value":" Your repo, your board, your standups, your code review process, your definition of done. We do not run a separate project plan and report against it. You manage the work exactly as you manage your own engineers."}],[{"type":"bold","value":"First pull request inside two weeks of start."},{"type":"text","value":" Usually sooner. We plan the first fortnight with your lead before day one, so the engineer arrives with a ticket and an environment rather than a reading list. Ramp-up is our problem, not something you pay for."}],[{"type":"bold","value":"Two to four weeks from contract to a working team."},{"type":"text","value":" Not a pipeline to open, a bench to allocate from. If we cannot staff your stack in that window, we tell you on the first call instead of stringing you along while we recruit against your requirement."}],[{"type":"bold","value":"Monthly rolling, not a twelve-month lock-in."},{"type":"text","value":" One month's notice, either side, from either of us. We hold engagements by being worth keeping. If the commercial model is the only thing holding a supplier in place, the delivery was never the point."}],[{"type":"bold","value":"You can end it, and you keep everything."},{"type":"text","value":" Code, documentation, architecture decisions and context stay with you. We run a written handover as standard, not as a paid extra at the unhappy end of a relationship."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"What it costs, plainly"},{"type":"p","inline":[{"type":"text","value":"This page's offer is the rate. There is no discovery fee, no onboarding fee and no minimum term beyond the month you are in."}]},{"type":"p","inline":[{"type":"bold","value":"Dedicated senior engineer — typically €6,400–€8,000 per month."},{"type":"text","value":" Full-time, one client at a time. What moves the number is stack scarcity, seniority band and whether the role needs domain experience we have to go and find."}]},{"type":"p","inline":[{"type":"bold","value":"Dedicated architect — typically €9,600–€12,800 per month."},{"type":"text","value":" For teams that need system ownership rather than throughput: someone accountable for the shape of the platform, working alongside your existing leads."}]},{"type":"p","inline":[{"type":"bold","value":"Dedicated pod (architect + 2 senior engineers) — typically €22,000–€29,000 per month."},{"type":"text","value":" The unit that owns a whole area of your product. Fastest route to real velocity when the gap is a team, not a person."}]},{"type":"p","inline":[{"type":"text","value":"Rates are all-in. They include recruitment, employment, equipment, holiday cover arrangements and management overhead on our side. There is no separate agency margin bolted on at invoice time."}]},{"type":"p","inline":[{"type":"text","value":"→ "},{"type":"link","label":"dedicated engineer","href":"/staff-augmentation-company-uk"},{"type":"text","value":" · "},{"type":"link","label":"dedicated pod","href":"/staff-augmentation-company-uk"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"pointOfView":{"rich":[{"type":"h2","text":"Our point of view"},{"type":"p","inline":[{"type":"text","value":"Staff augmentation gets a bad name because most of the market sells access to people rather than accountability for outcomes. Three CVs, a rate card, an invoice. Whether the work landed is treated as your management problem."}]},{"type":"p","inline":[{"type":"text","value":"We think the opposite. An engineer we place is an engineer whose output we are answerable for. That is why we insist you interview them, why we plan the first two weeks before day one, and why the contract is monthly. Each of those makes it harder for us to hide behind a signed term. That is the point."}]},{"type":"p","inline":[{"type":"text","value":"It also means we say no more often than is commercially convenient. If your stack is one we cannot staff at a genuinely senior level, we will tell you on the first call rather than sending a near-enough profile and hoping."}]},{"type":"p","inline":[{"type":"bold","value":"Who we are not for:"},{"type":"text","value":" if you want the cheapest hourly rate on the market, we are the wrong partner. Our engineers cost less than a UK contractor and considerably more than the bottom of the global market. Teams who buy on rate alone should buy elsewhere, and usually do it twice."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does a dedicated engineer actually cost per month?","objection":"price","answerInline":[{"type":"text","value":"A dedicated senior engineer is typically "},{"type":"bold","value":"€6,400–€8,000 per month"},{"type":"text","value":", full time and on your team only. A "},{"type":"link","label":"dedicated engineer","href":"/staff-augmentation-company-uk"},{"type":"text","value":" at architect level is usually "},{"type":"bold","value":"€9,600–€12,800 per month"},{"type":"text","value":". A "},{"type":"link","label":"dedicated pod","href":"/staff-augmentation-company-uk"},{"type":"text","value":" of an architect plus two senior engineers typically sits between "},{"type":"bold","value":"€22,000 and €29,000 per month"},{"type":"text","value":". What moves the number inside those bands is stack scarcity, the seniority you need and whether the role requires specific domain experience. There is no setup fee and no recruitment fee on top. More detail in "},{"type":"link","label":"what staff augmentation costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"Can we interview the engineers before they join?","objection":"seniority","answerInline":[{"type":"text","value":"Yes, and we would rather you did. You get CVs, then a technical interview with your own team, run your way. You can set a take-home, pair on a real ticket, or grill someone on their last production incident. You decide. The commitment behind it matters more than the interview itself: the engineer you interview is the engineer who starts. We do not substitute profiles after signature."}]},{"question":"What happens if it is not working out?","objection":"lock-in","answerInline":[{"type":"text","value":"Tell us early and we replace the engineer at our cost, or you end the engagement. Contracts are monthly rolling with one month's notice on either side. There is no twelve-month minimum, no exit fee and no clause that makes leaving expensive. In practice the problem is usually visible inside three weeks, which is exactly why we do not ask you to commit for a year."}]},{"question":"What timezone do your engineers work in, and how much overlap do we get?","objection":"other","answerInline":[{"type":"text","value":"We deliver from Cluj-Napoca, Romania, which is UTC+2 in winter and UTC+3 in summer. That is a two-hour offset from the UK. Your 9am standup is their 11am, and their day runs past yours. In practice it is a full working-day overlap, so there is no follow-the-sun handover and no waiting overnight for an answer. Read more on "},{"type":"link","label":"nearshore software development","href":"/nearshore-software-development-uk"},{"type":"text","value":"."}]},{"question":"Do they work in our repo and follow our process?","objection":"other","answerInline":[{"type":"text","value":"Yes. Your repo, your CI, your ticketing, your code review rules, your definition of done. Engineers join your standups and your retros as team members. We do not run a shadow project plan or send you a weekly status report about work you can already see in your own board. If your process is the thing that needs fixing, we will say so, but we will still follow it first."}]},{"question":"Who owns the IP, and will you sign our NDA?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You own everything the engineer produces, assigned to you under the contract and transferring on full payment. That covers code, documentation, designs and models. We sign your NDA and your MSA if you have them, and we have our own if you do not. Every engineer is under a personal confidentiality and IP assignment agreement with us, so the chain of title holds end to end. As an EU company we are GDPR-bound and we will sign a DPA before anyone gets access."}]},{"question":"How is this different from using a recruiter?","objection":"other","answerInline":[{"type":"text","value":"A recruiter finds you a person, takes a percentage of first-year salary and leaves. From that moment the employment risk, the notice period, the sick cover and the replacement cost are yours. We employ the engineer. If they leave us, replacing them is our problem and our cost, not a second fee to you. You also get to stop on a month's notice, which is not something a permanent hire gives you. If a permanent hire is genuinely the right answer for the role, we will say that on the first call."}]},{"question":"What happens to the knowledge when an engineer rolls off?","objection":"after-launch","answerInline":[{"type":"text","value":"This is the right question to ask, and it is why we push pods rather than lone engineers on anything long-running. Practically: architecture decisions are written down as decision records in your repo, not held in someone's head. Pull requests are reviewed by at least one other person who understands the area. Where a single engineer holds a critical area, we overlap them with a second person before any planned exit. And on roll-off we run a written handover to whoever you nominate. None of that is an extra line on the invoice."}]},{"question":"How quickly can someone actually start?","objection":"timeline","answerInline":[{"type":"text","value":"Two to four weeks from signed contract to an engineer in your standup is the normal range, and it covers interviews, notice and account provisioning. Common stacks at the shorter end, scarce specialisms at the longer. We will give you a date on the first call and tell you if the honest answer is longer. You can see "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" for the full sequence."}]},{"question":"We used an outsourcing supplier before and it went badly. Why is this different?","objection":"failed-before","answerInline":[{"type":"text","value":"Most of the stories we hear share three causes: you never met the person, the contract was long enough that the supplier stopped trying, and the engineer was managed by the supplier rather than by you. We have removed all three deliberately. You interview. The term is monthly. The engineer reports into your team lead. That does not guarantee a good outcome, but it means a bad one surfaces in week three rather than month nine, and you can act on it."}]},{"question":"Where does our code and data actually sit?","objection":"data-residency","answerInline":[{"type":"text","value":"Inside your own environment. Engineers work in your cloud accounts and your repos, under your access controls, and we ask for the least access that lets them do the job. We are an EU company delivering from Romania, so any data we do handle stays inside the EEA under GDPR, covered by a DPA. If you need device policies, VPN-only access or a specific security posture, that gets agreed before start rather than discovered afterwards."}]},{"question":"What if what we actually need is a whole product, not extra hands?","objection":"other","answerInline":[{"type":"text","value":"Then we will tell you that. Sometimes the honest read is that the team is not short of capacity, it is short of a defined scope. In that case a fixed-scope build such as a "},{"type":"link","label":"Production MVP","href":"/mvp-development-agency-uk"},{"type":"text","value":" is the better shape, and we run those too. We also build "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" where the real bottleneck turns out to be an operational process rather than the product backlog."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Bring us the roles you cannot fill","sub":"A 45-minute technical call. We will tell you which of your open roles we can staff, at what rate, and by what date. If the answer is that you should hire permanently instead, you will hear that too."}},"sourceFile":"7code-build/content/pages/staff-augmentation-company-uk.mdx"}};
const PACKAGES = {"ai-ready-ops-blueprint":{"spec":{"status":"approved","kind":"package","meta":{"slug":"packages/ai-ready-ops-blueprint","title":"AI-Ready Ops Blueprint — AI Readiness Roadmap | 7code","metaDescription":"A four to six week blueprint: target architecture, data readiness assessment, a costed AI use-case roadmap, and a governance position your board can sign off.","canonical":"https://www.7code.tech/packages/ai-ready-ops-blueprint/","ogImage":"/og/ai-ready-ops-blueprint.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"ai readiness assessment","secondaryKeywords":["ai strategy roadmap consultancy","data readiness assessment ai","ai architecture review","ai governance framework for business"],"icpSegment":"smb-automation","searchIntent":"commercial","flywheelStage":"acquisition","difficultyNote":"Contested by the large consultancies at the top and by prompt-engineering boutiques at the bottom. The gap in the middle is a readiness assessment written by people who also build production systems, priced below a Big Four scoping phase. Buyer is often a COO with a CTO or IT lead beside them, so the page must survive technical reading. Qualitative only — no verified volume data available.\n"},"cta":{"label":"Book a discovery call","action":"booking","href":"/book/discovery","reassurance":"45 minutes with a senior engineer, not a salesperson. Bring your architecture questions — we answer them on the call."},"blocks":["hero","trustStrip","whoThisIsFor","whatYouGet","howItRuns","price","notForYouIf","faq","close"],"proof":[{"caseStudySlug":"hera","metric":"Clinical intake from days to minutes — RAG-verified, MVP in 3 months","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"LLM & agent development","href":"/service/llm-agent-development"}]},{"caseStudySlug":"g42-fleet","metric":"Fleet platform deployed at EXPO 2020 scale, across a 2-year engagement","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI product engineering","href":"/service/ai-product-engineering"}]}],"internalLinks":[{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatYouGet"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatYouGet"},{"anchor":"AI automation","href":"/service/ai-automation","placement":"whatYouGet"},{"anchor":"Automation Pilot","href":"/packages/automation-pilot","placement":"price"},{"anchor":"Operational Quick Scan","href":"/packages/operational-quick-scan","placement":"notForYouIf"},{"anchor":"Department Automation Sprint","href":"/packages/department-automation-sprint","placement":"faq"},{"anchor":"AI automation agency","href":"/ai-automation-agency-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"AI-Ready Ops Blueprint","sub":"In four to six weeks you get a target architecture, an honest data readiness verdict, and a costed AI roadmap your board can approve."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"whoThisIsFor":{"rich":[{"type":"h2","text":"This fits if you recognise your own company here"},{"type":"ul","items":[[{"type":"text","value":"Your board or your parent group has asked for an AI plan, and the honest answer today is that nobody has assessed whether the data underneath would support one."}],[{"type":"text","value":"You have run a proof of concept that worked in a demo and stalled on the way to production. You want to know whether that was the use case, the architecture, or the data."}],[{"type":"text","value":"Your systems grew by acquisition or by accident. Customer records exist in four places, none of them agree, and every automation proposal quietly assumes they do."}],[{"type":"text","value":"Procurement or legal needs a position on model vendors, data residency and lock-in before anything gets signed, and no one internally owns that answer."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatYouGet":{"rich":[{"type":"h2","text":"What lands on your desk"},{"type":"p","inline":[{"type":"text","value":"Five named artefacts, written to be read by a CTO and approved by a board. Both audiences get a version they can actually use."}]},{"type":"ul","items":[[{"type":"bold","value":"Target architecture"},{"type":"text","value":" — a documented end state for the systems that would carry AI workloads. Data flows, integration points, where inference runs, where records live, and what has to change from today's estate to get there."}],[{"type":"bold","value":"Data readiness assessment"},{"type":"text","value":" — a per-source verdict on the data you would need. Completeness, structure, freshness, ownership, and whether the source can be trusted for automated decisions. Written as a red-amber-green with the reasoning attached, not just the colour."}],[{"type":"bold","value":"Prioritised use-case roadmap"},{"type":"text","value":" — every candidate scored on business value, build cost, delivery risk and data dependency. Sequenced across four quarters, with the prerequisites each item inherits from the one before it."}],[{"type":"bold","value":"Model and vendor recommendation with a lock-in assessment"},{"type":"text","value":" — which models suit which workload, at what cost per unit of work, and what it would take to move off each one. Hosted APIs and open-weight options running in your own environment are both priced."}],[{"type":"bold","value":"Governance and data-residency position"},{"type":"text","value":" — a document your board can sign. Where data goes, who approves a model change, how outputs are reviewed, what gets logged, and how GDPR obligations are met."}]]},{"type":"p","inline":[{"type":"text","value":"Underneath these sits an inventory of the current estate, the "},{"type":"link","label":"system integrations","href":"/service/system-integrations"},{"type":"text","value":" that would need building, and a cost model for running "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" and "},{"type":"link","label":"LLM and agent development","href":"/service/llm-agent-development"},{"type":"text","value":" workloads at your volume."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howItRuns":{"rich":[{"type":"h2","text":"Four to six weeks, and what it costs your team"},{"type":"p","inline":[{"type":"bold","value":"Weeks 1–2 — estate and data."},{"type":"text","value":" We review the current architecture with your CTO or IT lead, then work through the data sources one at a time. Two workshops of two hours with the technical owner, plus short sessions with whoever holds each system. What we need most is read access to schemas and sample exports."}]},{"type":"p","inline":[{"type":"bold","value":"Weeks 3–4 — use cases and economics."},{"type":"text","value":" Three or four 90-minute sessions with operations and commercial leads to surface and challenge candidate use cases. In parallel we build the cost model and test model options against your real data shapes."}]},{"type":"p","inline":[{"type":"bold","value":"Weeks 5–6 — architecture, governance and readout."},{"type":"text","value":" We write the target architecture and the governance position, then present the blueprint. The readout runs two hours with the decision group. A board-ready summary follows, plus the full technical document."}]},{"type":"p","inline":[{"type":"text","value":"Time from your side is usually 20 to 25 hours across six weeks, concentrated in your CTO or IT lead. Operations leads spend around four hours each. We name the sessions that matter before we start."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"price":{"rich":[{"type":"h2","text":"What it costs and what happens next"},{"type":"p","inline":[{"type":"bold","value":"Typically €9,000–€14,000."}]},{"type":"p","inline":[{"type":"text","value":"What moves it inside that band: the number of data sources assessed, how many systems make up the current estate, and whether governance has to satisfy a regulator as well as a board. A single-entity company with five or six sources sits at the bottom. A group with several operating companies, mixed cloud accounts and a compliance obligation sits at the top. Price is fixed before we start."}]},{"type":"p","inline":[{"type":"bold","value":"If you want to proceed after the readout"},{"type":"text","value":", the roadmap names its own first item and prices it. Usually that is an "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":" on the highest-value use case, or a short integration project to fix a data source first. We credit the blueprint fee against the first build if you commit within 90 days."}]},{"type":"p","inline":[{"type":"bold","value":"CTA:"},{"type":"text","value":" Book a discovery call"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"notForYouIf":{"rich":[{"type":"h2","text":"Don't buy this if"},{"type":"ul","items":[[{"type":"bold","value":"Your question is operational, not architectural."},{"type":"text","value":" If you want to know which manual processes cost the most and what automating them returns, the "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":" answers that in less time for less money."}],[{"type":"bold","value":"You want a document to satisfy a stakeholder, not a plan you intend to run."},{"type":"text","value":" We write blueprints that commit to sequencing and cost. That makes them useful and it makes them uncomfortable. If the brief is a deck for a steering committee, a strategy firm will do it more gracefully."}],[{"type":"bold","value":"Your data situation is already understood and the decision is made."},{"type":"text","value":" If your CTO can already name the target architecture and the first three use cases, buy the build, not the plan."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does this cost, and what makes it move?","objection":"price","answerInline":[{"type":"bold","value":"€9,000–€14,000"},{"type":"text","value":" over four to six weeks. The band moves on the number of data sources, the number of systems in the current estate, and whether governance has to satisfy a regulator. We fix the fee once scope is agreed. Wider context in "},{"type":"link","label":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"How is this different from a consultancy's AI strategy engagement?","objection":"other","answerInline":[{"type":"text","value":"We build the systems we recommend, so every number in the roadmap is an estimate we would have to honour. That constrains what we can write. The architecture is drawn by people who have shipped production AI, including RAG pipelines with human review steps."}]},{"question":"Our proof of concept failed. Will this tell us why?","objection":"failed-before","answerInline":[{"type":"text","value":"That is one of the first things we look at. The cause is usually one of three: a use case chosen because it demoed well, a data source that could not be trusted for automated decisions, or an architecture with no eval or observability layer. The fix differs in each case."}]},{"question":"Who from our side needs to be involved?","objection":"timeline","answerInline":[{"type":"text","value":"Your CTO or IT lead carries most of it, at roughly 20 to 25 hours across six weeks. Operations and commercial leads spend about four hours each. Whoever owns each data source gives us one short session."}]},{"question":"Will you recommend a vendor you have a relationship with?","objection":"lock-in","answerInline":[{"type":"text","value":"No. We are model agnostic and we do not resell. The recommendation compares hosted APIs against open-weight models in your own environment, prices both at your volume, and states the exit cost of each. Lock-in is assessed explicitly, because it is usually the part nobody writes down."}]},{"question":"Can this satisfy our board and our data protection obligations?","objection":"data-residency","answerInline":[{"type":"text","value":"That is what the governance and data-residency position is for. We are an EU company delivering from Romania, so EEA residency is the default and a DPA is standard. Where data cannot leave your environment, the architecture uses open-weight models running inside your infrastructure."}]},{"question":"Who owns the blueprint afterwards?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You do, on full payment. It is written so another firm can execute against it. It names systems, volumes, integration points and decision criteria rather than 7code products."}]},{"question":"What if the roadmap turns out to be bigger than we can fund?","objection":"other","answerInline":[{"type":"text","value":"Then it gets sequenced honestly rather than compressed. The roadmap is built so the first quarter stands alone and returns something, whether or not the later quarters are funded. If the realistic shape is a full department rebuild, the "},{"type":"link","label":"Department Automation Sprint","href":"/packages/department-automation-sprint"},{"type":"text","value":" is where that lands. You can also see "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" and our wider "},{"type":"link","label":"AI automation agency","href":"/ai-automation-agency-uk"},{"type":"text","value":" practice."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Book a call and we'll scope the blueprint","sub":"Four to six weeks, a target architecture and a costed roadmap, plus a governance position your board can actually sign."}},"sourceFile":"7code-build/content/packages/ai-ready-ops-blueprint.mdx"},"automation-pilot":{"spec":{"status":"approved","kind":"package","meta":{"slug":"packages/automation-pilot","title":"Automation Pilot — One Workflow, In Production | 7code","metaDescription":"Six to ten weeks to put one or two workflows into production on your real data, with evals, guardrails, tracing and a cost dashboard. Code in your own repo.","canonical":"https://www.7code.tech/packages/automation-pilot/","ogImage":"/og/automation-pilot.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"ai automation pilot project","secondaryKeywords":["automate a business workflow end to end","ai proof of concept to production","workflow automation implementation","production ai automation project"],"icpSegment":"smb-automation","searchIntent":"commercial","flywheelStage":"closing","difficultyNote":"The buyer arriving here has usually already been burned by a pilot that never reached production. The competitive edge is not the automation itself but the production layer around it — evals, guardrails, tracing, cost dashboards, handover. Incumbent no-code shops cannot credibly claim that layer. Qualitative only — no verified volume data available.\n"},"cta":{"label":"Book an Operational Quick Scan","action":"booking","href":"/book/quick-scan","reassurance":"45 minutes. No prep needed. You'll leave with two or three processes worth automating, whether or not you work with us."},"blocks":["hero","trustStrip","whoThisIsFor","whatYouGet","howItRuns","price","notForYouIf","faq","close"],"proof":[{"caseStudySlug":"hera","metric":"Clinical intake from days to minutes — RAG-verified, MVP in 3 months","tags":[{"label":"LLM & agent development","href":"/service/llm-agent-development"},{"label":"AI product engineering","href":"/service/ai-product-engineering"}]},{"caseStudySlug":"numerize","metric":"6,000+ customer accounts running on the platform","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI automation","href":"/service/ai-automation"}]}],"internalLinks":[{"anchor":"AI automation","href":"/service/ai-automation","placement":"whatYouGet"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatYouGet"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatYouGet"},{"anchor":"Operational Quick Scan","href":"/packages/operational-quick-scan","placement":"price"},{"anchor":"Department Automation Sprint","href":"/packages/department-automation-sprint","placement":"price"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"notForYouIf"},{"anchor":"AI automation agency","href":"/ai-automation-agency-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"operations","href":"/expertise/operations","placement":"faq"},{"anchor":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"Automation Pilot","sub":"In six to ten weeks one or two of your workflows run end to end in production, on real data, with the controls that keep them working."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"whoThisIsFor":{"rich":[{"type":"h2","text":"This fits if you recognise your own company here"},{"type":"ul","items":[[{"type":"text","value":"You know which workflow you want automated. It is named, it has an owner, and the argument internally is about delivery, not about priorities."}],[{"type":"text","value":"A previous pilot worked on sample data and died on the way to production. Nobody could say what it cost to run, and nobody could tell when it was wrong."}],[{"type":"text","value":"One process is capping your growth. Volume goes up, the process needs more people, and the margin goes the wrong way each time you add one."}],[{"type":"text","value":"You want the automation running in your own cloud account, on code your team can read, before you commit to a larger programme."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatYouGet":{"rich":[{"type":"h2","text":"What lands on your desk"},{"type":"p","inline":[{"type":"text","value":"Seven named artefacts. The automation is one of them. The other six are why it is still running in a year."}]},{"type":"ul","items":[[{"type":"bold","value":"The working automation"},{"type":"text","value":" — one or two workflows, live in production, processing real volume. Built as "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" or "},{"type":"link","label":"LLM and agent development","href":"/service/llm-agent-development"},{"type":"text","value":" depending on what the work actually needs, with "},{"type":"link","label":"system integrations","href":"/service/system-integrations"},{"type":"text","value":" into the tools you already run."}],[{"type":"bold","value":"The eval suite"},{"type":"text","value":" — a test set built from your own historical cases, including the awkward ones. Every change is measured against it before release. This is how you know a model update did not quietly make things worse."}],[{"type":"bold","value":"Guardrails"},{"type":"text","value":" — input validation, output constraints, confidence thresholds, and an explicit escalation path. Edge cases go to a named human queue, not into a void."}],[{"type":"bold","value":"Tracing"},{"type":"text","value":" — every run recorded end to end. What came in, what the model decided, which tools it called, what went out. Searchable by your team, not only by ours."}],[{"type":"bold","value":"Cost dashboard"},{"type":"text","value":" — spend per run and per month, broken down by step, with alerts. You will know what the automation costs before finance asks."}],[{"type":"bold","value":"Handover documentation"},{"type":"text","value":" — runbook, architecture notes, prompt and configuration inventory, and the failure modes we found with what to do about each one. Written for an engineer who has never met us."}],[{"type":"bold","value":"The code, in your repo and your cloud account"},{"type":"text","value":" — from the first week, not at the end. You own the code, the prompts, the eval sets and the infrastructure configuration."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howItRuns":{"rich":[{"type":"h2","text":"Six to ten weeks, and what it costs your team"},{"type":"p","inline":[{"type":"bold","value":"Weeks 1–2 — grounding."},{"type":"text","value":" We confirm the process end to end with the people who run it, agree success criteria in numbers, and get access to systems and historical data. Your process owner spends around six hours here. Whoever controls system access spends two or three."}]},{"type":"p","inline":[{"type":"bold","value":"Weeks 3–6 — build on real data."},{"type":"text","value":" We build against your actual records, not samples, and demo weekly. Each demo is 45 minutes with the process owner. Between demos we need about two hours a week from them to judge outputs and settle edge cases. That judgement is the part we cannot do for you."}]},{"type":"p","inline":[{"type":"bold","value":"Weeks 6–8 — shadow running."},{"type":"text","value":" The automation runs alongside the people doing the work. Outputs are compared, disagreements logged, thresholds tuned. Your team works as normal and reviews a daily comparison, about 20 minutes a day for one person."}]},{"type":"p","inline":[{"type":"bold","value":"Weeks 8–10 — cutover and handover."},{"type":"text","value":" We move it into production with guardrails live, run handover with your team, and walk your engineers through the repo. Two sessions of 90 minutes."}]},{"type":"p","inline":[{"type":"text","value":"Total time from your side is usually 40 to 50 hours, most of it the process owner. Shorter pilots compress the shadow phase, never the eval work."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"price":{"rich":[{"type":"h2","text":"What it costs and what happens next"},{"type":"p","inline":[{"type":"bold","value":"Typically €15,000–€25,000."}]},{"type":"p","inline":[{"type":"text","value":"What moves it inside that band: how many systems the workflow touches, whether one workflow or two are in scope, how clean the historical data is, and whether decisions need a compliance review step. One workflow across two well-documented systems sits at the bottom. Two workflows across legacy systems with no API sit at the top. The fee is fixed once scope is agreed, and the scope document lists what is out as clearly as what is in."}]},{"type":"p","inline":[{"type":"bold","value":"If you are not certain which workflow to pick"},{"type":"text","value":", run an "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":" first. It costs less and prevents the expensive version of this mistake."}]},{"type":"p","inline":[{"type":"bold","value":"If it works"},{"type":"text","value":", the usual next step is widening to the rest of the department, which is the "},{"type":"link","label":"Department Automation Sprint","href":"/packages/department-automation-sprint"},{"type":"text","value":". Plenty of clients stop after the pilot and run it themselves. The handover pack assumes exactly that."}]},{"type":"p","inline":[{"type":"bold","value":"CTA:"},{"type":"text","value":" Book an Operational Quick Scan"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"notForYouIf":{"rich":[{"type":"h2","text":"Don't buy this if"},{"type":"ul","items":[[{"type":"bold","value":"You want a demo for a board meeting."},{"type":"text","value":" A production pilot spends most of its budget on the parts nobody sees in a demo: evals, guardrails, tracing, shadow running. If the goal is to show something impressive next month, this is an expensive way to get it."}],[{"type":"bold","value":"The process changes every quarter."},{"type":"text","value":" Automating a process that is still being redesigned means paying twice. Stabilise it first, or automate the part that is settled and leave the rest manual."}],[{"type":"bold","value":"Nobody will own it afterwards."},{"type":"text","value":" The pilot needs a named process owner who will judge outputs during the build and keep judging them after we leave. Without that person, it degrades quietly. If the underlying issue is architecture and data readiness, the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":" comes first."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does a pilot cost and what changes the number?","objection":"price","answerInline":[{"type":"bold","value":"€15,000–€25,000"},{"type":"text","value":" over six to ten weeks. It moves on the number of systems involved, whether it is one workflow or two, the state of the historical data, and whether a compliance review step is required. We fix the fee once scope is agreed. Full breakdown in "},{"type":"link","label":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"Our last pilot never made it to production. What is different?","objection":"failed-before","answerInline":[{"type":"text","value":"Most stalled pilots share a shape: clean sample data, no eval set, no way to tell when the output was wrong, no cost visibility. We build on your real records from week three and ship the eval suite, guardrails, tracing and cost dashboard as part of the work. Shadow running proves it against your own team before cutover."}]},{"question":"When do we see something working?","objection":"timeline","answerInline":[{"type":"text","value":"A working demo on your data by week three or four, then weekly. Shadow running starts around week six. Production cutover is week eight to ten depending on scope."}]},{"question":"Who builds it?","objection":"seniority","answerInline":[{"type":"text","value":"Senior engineers, the same ones from the first call through to handover. No account manager layer, no handover to juniors after signature. If you want to meet the engineer before committing, ask. See "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" and our "},{"type":"link","label":"operations","href":"/expertise/operations"},{"type":"text","value":" engagements."}]},{"question":"Where does the code live?","objection":"lock-in","answerInline":[{"type":"text","value":"Your repo and your cloud account, from the first week. You own the code, the prompts, the eval sets and the infrastructure configuration. We are model agnostic, so you are not tied to one AI vendor either."}]},{"question":"What happens when the model gets it wrong?","objection":"other","answerInline":[{"type":"text","value":"It gets caught or escalated. Guardrails validate inputs and constrain outputs, confidence thresholds route uncertain cases to a human queue, and every run is traced. The eval suite catches degradation before your customers do."}]},{"question":"Will this remove jobs on the team?","objection":"sideline-our-team","answerInline":[{"type":"text","value":"The pattern we see is a team spending most of the week on work needing no judgement, and the rest on work that does. The pilot takes the first part. In practice the person who ran the process becomes the person who owns the automation, because they are the only one who recognises a wrong output."}]},{"question":"Where does our data go?","objection":"data-residency","answerInline":[{"type":"text","value":"We are an EU company delivering from Romania, so data stays inside the EEA by default and a DPA is standard. Where records cannot leave your environment at all, we run open-weight models inside your own infrastructure rather than calling a hosted API. This is settled before the build, not after. More on our approach on the "},{"type":"link","label":"AI automation agency","href":"/ai-automation-agency-uk"},{"type":"text","value":" page."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Start with the scan, then the pilot","sub":"Six to ten weeks to one workflow running in production, with evals, guardrails, tracing and the code in your own account."}},"sourceFile":"7code-build/content/packages/automation-pilot.mdx"},"department-automation-sprint":{"spec":{"status":"approved","kind":"package","meta":{"slug":"packages/department-automation-sprint","title":"Department Automation Sprint — Digitalisation | 7code","metaDescription":"Ten to sixteen weeks to digitalise a whole department: connected workflows, integrations, internal tooling, team training and a documented operating model.","canonical":"https://www.7code.tech/packages/department-automation-sprint/","ogImage":"/og/department-automation-sprint.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"department digitalisation project","secondaryKeywords":["automate a whole department","operations digital transformation smb","back office automation programme","internal tooling and workflow automation"],"icpSegment":"smb-automation","searchIntent":"commercial","flywheelStage":"closing","difficultyNote":"Highest-value package in the set and the one where the buyer compares us against a mid-tier consultancy or a hire. The page has to answer time cost and operating model, not only price, because the risk the COO is carrying is disruption to a live department. Qualitative only — no verified volume data available.\n"},"cta":{"label":"Book a discovery call","action":"booking","href":"/book/discovery","reassurance":"45 minutes with a senior engineer, not a salesperson. Bring the department and the problem — we'll tell you honestly whether a sprint is the right shape."},"blocks":["hero","trustStrip","whoThisIsFor","whatYouGet","howItRuns","price","notForYouIf","faq","close"],"proof":[{"caseStudySlug":"g42-fleet","metric":"Fleet platform deployed at EXPO 2020 scale, across a 2-year engagement","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI product engineering","href":"/service/ai-product-engineering"}]},{"caseStudySlug":"numerize","metric":"6,000+ customer accounts running on the platform","tags":[{"label":"AI automation","href":"/service/ai-automation"},{"label":"System integrations","href":"/service/system-integrations"}]}],"internalLinks":[{"anchor":"AI automation","href":"/service/ai-automation","placement":"whatYouGet"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatYouGet"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"whatYouGet"},{"anchor":"Automation Pilot","href":"/packages/automation-pilot","placement":"notForYouIf"},{"anchor":"Operational Quick Scan","href":"/packages/operational-quick-scan","placement":"price"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"faq"},{"anchor":"AI automation agency","href":"/ai-automation-agency-uk","placement":"faq"},{"anchor":"staff augmentation","href":"/staff-augmentation-company-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"operations","href":"/expertise/operations","placement":"faq"},{"anchor":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"Department Automation Sprint","sub":"In ten to sixteen weeks one department runs on connected workflows, its own tooling and a documented operating model your team owns."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"whoThisIsFor":{"rich":[{"type":"h2","text":"This fits if you recognise your own company here"},{"type":"ul","items":[[{"type":"text","value":"One department is the constraint on the whole business. Sales can sell more than operations can deliver, or finance closes the month a week later than the board wants."}],[{"type":"text","value":"You have automated one workflow already and hit the ceiling. The gains stopped at the boundary, because the next step still arrives as an email from another team."}],[{"type":"text","value":"The department runs on four systems and a shared spreadsheet that quietly holds the real state. Everyone knows which one it is and nobody wants to be the person who breaks it."}],[{"type":"text","value":"The alternative on the table is hiring five people. You would rather spend a similar amount once and change the shape of the work."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatYouGet":{"rich":[{"type":"h2","text":"What lands on your desk"},{"type":"p","inline":[{"type":"text","value":"Five named artefacts. The last two are the ones that decide whether this survives after we leave."}]},{"type":"ul","items":[[{"type":"bold","value":"Connected workflows"},{"type":"text","value":" — the department's core processes automated end to end and joined up, so output from one becomes input to the next without a person retyping it. Built as "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" or "},{"type":"link","label":"LLM and agent development","href":"/service/llm-agent-development"},{"type":"text","value":" where judgement is genuinely needed, and as plain deterministic code where it is not."}],[{"type":"bold","value":"Integrations with the systems you already run"},{"type":"text","value":" — your CRM, ERP, finance system, ticketing, document store. These "},{"type":"link","label":"system integrations","href":"/service/system-integrations"},{"type":"text","value":" are usually the largest part of the work and the part other vendors underestimate."}],[{"type":"bold","value":"Internal tooling and dashboards for the process owners"},{"type":"text","value":" — the screens the department actually works in. Queues, exception handling, approvals, and a live view of what the automation did and why, without anyone asking engineering."}],[{"type":"bold","value":"Training for the team"},{"type":"text","value":" — sessions run with the people who do the work, not a video library. They learn the new operating model, the exception paths, and how to tell when something is wrong."}],[{"type":"bold","value":"A documented operating model"},{"type":"text","value":" — who owns which process, what the escalation path is, what the SLAs are now that volume is not people-bound, and what changes in each role. This is the artefact that turns a delivery into a way of working."}]]},{"type":"p","inline":[{"type":"text","value":"Every workflow ships with the production layer as standard: eval sets, guardrails, tracing, and a cost dashboard. Code and infrastructure live in your own repo and cloud account throughout."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howItRuns":{"rich":[{"type":"h2","text":"Ten to sixteen weeks, and what it costs your team"},{"type":"p","inline":[{"type":"bold","value":"Weeks 1–3 — map and sequence."},{"type":"text","value":" We document every process as it runs today, agree the target operating model, and sequence the build. One 45-minute interview per role, plus three two-hour workshops with the department head. Your department head spends around ten hours in this phase."}]},{"type":"p","inline":[{"type":"bold","value":"Weeks 4–10 — build in slices."},{"type":"text","value":" We deliver workflow by workflow, each one live before the next starts. Fortnightly hour-long demos with the department head and process owners. Between demos we need about three hours a week from two named process owners to judge outputs and resolve edge cases."}]},{"type":"p","inline":[{"type":"bold","value":"Weeks 10–14 — integrate and shadow."},{"type":"text","value":" Workflows are connected, internal tooling goes live, and the department runs the new path alongside the old one. Busiest phase for your team: two process owners at about a day a week each, reviewing the comparison."}]},{"type":"p","inline":[{"type":"bold","value":"Weeks 14–16 — training, cutover and operating model."},{"type":"text","value":" Training runs with the whole department, usually two half-days. We cut over, stay close for two weeks, and hand over the operating model with the runbooks."}]},{"type":"p","inline":[{"type":"text","value":"Total time from your side is usually 120 to 150 hours across four months, concentrated in the department head and two process owners. We name those people in week one. A sprint without them named is a sprint that slips."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"price":{"rich":[{"type":"h2","text":"What it costs and what happens next"},{"type":"p","inline":[{"type":"bold","value":"Typically €40,000–€65,000."}]},{"type":"p","inline":[{"type":"text","value":"What moves it inside that band: the number of workflows, how many systems need integrating and whether they have usable APIs, the volume of historical data to migrate, and whether the department operates in one country or several. Four workflows across modern SaaS tools sits at the bottom. Eight workflows spanning a legacy ERP, multiple entities and a compliance regime sit at the top."}]},{"type":"p","inline":[{"type":"text","value":"We price after a scoping phase, not before. If the department is not yet mapped, an "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":" is the cheapest way to a firm number, and we credit the fee against the sprint if you proceed within 60 days."}]},{"type":"p","inline":[{"type":"bold","value":"If you want to proceed"},{"type":"text","value":", we agree the workflow list and the sequence in writing first. The contract prices each slice, so you can stop after any slice with something working rather than something half built."}]},{"type":"p","inline":[{"type":"bold","value":"CTA:"},{"type":"text","value":" Book a discovery call"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"notForYouIf":{"rich":[{"type":"h2","text":"Don't buy this if"},{"type":"ul","items":[[{"type":"bold","value":"You have not automated anything yet."},{"type":"text","value":" Start with an "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":" on one workflow. It proves the approach on your data, it teaches both sides how the other works, and it costs a quarter as much to find out we are wrong about each other."}],[{"type":"bold","value":"The department is about to be reorganised."},{"type":"text","value":" A documented operating model built around roles that will not exist in six months is a wasted deliverable. Sequence the reorganisation first, then automate the shape you land on."}],[{"type":"bold","value":"You need it live in six weeks."},{"type":"text","value":" Ten to sixteen weeks is the honest range for a department, and compressing it means cutting the shadow-running and training phases. Those are the two phases that decide whether the department actually adopts it."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does a sprint cost and what changes the number?","objection":"price","answerInline":[{"type":"bold","value":"€40,000–€65,000"},{"type":"text","value":" over ten to sixteen weeks. It moves on the number of workflows, how many systems need integrating and whether they expose usable APIs, the data to migrate, and the number of entities involved. We price after scoping, and the contract prices each slice separately. Wider context in "},{"type":"link","label":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"How does this compare to hiring?","objection":"other","answerInline":[{"type":"text","value":"A sprint is a one-off cost against a permanent one. Five hires is a recurring annual commitment plus recruitment, onboarding and the management layer above them. It is not always the better answer. Where the work needs judgement, hire. Where the work is volume, automate."}]},{"question":"Can the department keep running while you build?","objection":"timeline","answerInline":[{"type":"text","value":"Yes, and that is why we build in slices and shadow-run before cutover. Each workflow goes live on its own and the old path stays available until the new one has proven itself."}]},{"question":"How much time does this take from our people?","objection":"timeline","answerInline":[{"type":"text","value":"Usually 120 to 150 hours across four months. The department head carries around ten hours in mapping, then an hour a fortnight. Two named process owners carry the rest, peaking at about a day a week each during shadow running."}]},{"question":"What if our systems have no API?","objection":"other","answerInline":[{"type":"text","value":"Common, and it is priced in. We have built against legacy systems before, including at scale. Options are database-level integration, file-based exchange, or a controlled interface layer. We assess which is safe during scoping and tell you if one system makes the whole sprint uneconomic."}]},{"question":"Who owns the result?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You do, on full payment. Code, prompts, eval sets, infrastructure configuration and documentation, in your own repo and cloud account throughout the build. That includes anything built on top of our internal tooling. It is standard contract, not an upgrade."}]},{"question":"What happens after cutover?","objection":"after-launch","answerInline":[{"type":"text","value":"The operating model document, runbooks and dashboards are written so your team runs it without us. We stay close for two weeks after cutover as standard. A support retainer is available and optional — it is not how we make the project viable. Some clients instead take one of our engineers on "},{"type":"link","label":"staff augmentation","href":"/staff-augmentation-company-uk"},{"type":"text","value":" to keep building internally."}]},{"question":"Should we do a readiness assessment first?","objection":"other","answerInline":[{"type":"text","value":"Sometimes. If the blocker is fragmented data or an unclear target architecture, the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":" answers that before you commit this much budget. If the processes are understood and the systems are known, go straight to scoping. See "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":", our "},{"type":"link","label":"operations","href":"/expertise/operations"},{"type":"text","value":" engagements, and the wider "},{"type":"link","label":"AI automation agency","href":"/ai-automation-agency-uk"},{"type":"text","value":" practice."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Book a call and we'll scope the sprint","sub":"Ten to sixteen weeks to a department running on connected workflows, its own tooling and an operating model your team owns."}},"sourceFile":"7code-build/content/packages/department-automation-sprint.mdx"},"operational-quick-scan":{"spec":{"status":"approved","kind":"package","meta":{"slug":"packages/operational-quick-scan","title":"Operational Quick Scan — Process Automation Audit | 7code","metaDescription":"A two to three week process audit that maps your operational workflows, ranks them by time and money cost, and prices what is worth automating.","canonical":"https://www.7code.tech/packages/operational-quick-scan/","ogImage":"/og/operational-quick-scan.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"process automation audit","secondaryKeywords":["automation opportunity assessment","business process audit for automation","ai automation roi assessment","workflow audit consultancy"],"icpSegment":"smb-automation","searchIntent":"commercial","flywheelStage":"acquisition","difficultyNote":"Low-competition long tail. Most incumbents in this space give the audit away free as a lead magnet and therefore keep it shallow. A paid, deliverable-backed scan reads as a different category of product and defends the price on depth, not on discount. Qualitative only — no verified volume data available.\n"},"cta":{"label":"Book an Operational Quick Scan","action":"booking","href":"/book/quick-scan","reassurance":"45 minutes. No prep needed. You'll leave with two or three processes worth automating, whether or not you work with us."},"blocks":["hero","trustStrip","whoThisIsFor","whatYouGet","howItRuns","price","notForYouIf","faq","close"],"proof":[{"caseStudySlug":"numerize","metric":"6,000+ customer accounts running on the platform","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI automation","href":"/service/ai-automation"}]},{"caseStudySlug":"hera","metric":"Clinical intake from days to minutes — RAG-verified, MVP in 3 months","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"LLM & agent development","href":"/service/llm-agent-development"}]}],"internalLinks":[{"anchor":"AI automation","href":"/service/ai-automation","placement":"whatYouGet"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"whatYouGet"},{"anchor":"Automation Pilot","href":"/packages/automation-pilot","placement":"price"},{"anchor":"Department Automation Sprint","href":"/packages/department-automation-sprint","placement":"faq"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"notForYouIf"},{"anchor":"AI automation agency","href":"/ai-automation-agency-uk","placement":"faq"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"operations","href":"/expertise/operations","placement":"faq"},{"anchor":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":true,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"Operational Quick Scan","sub":"In two to three weeks you get a ranked map of your operational processes, with a build cost and an expected return against each one."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"whoThisIsFor":{"rich":[{"type":"h2","text":"This fits if you recognise your own company here"},{"type":"ul","items":[[{"type":"text","value":"You know the business runs on manual work, but nobody can say which process costs the most. Every department nominates its own bottleneck and they cannot all be first."}],[{"type":"text","value":"A headcount request is sitting on your desk. You suspect the work behind it does not need a person, and you want that tested before you sign."}],[{"type":"text","value":"Three vendors have quoted you for automation. The quotes are not comparable because each one scoped a different problem, and none of them mapped your process first."}],[{"type":"text","value":"You have budget approval for one automation project this year, and picking the wrong one costs you the year, not just the money."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatYouGet":{"rich":[{"type":"h2","text":"What lands on your desk"},{"type":"p","inline":[{"type":"text","value":"Five named artefacts. All written, all yours, delivered whether the conclusion flatters us or not."}]},{"type":"ul","items":[[{"type":"bold","value":"Process map"},{"type":"text","value":" — every operational workflow in scope, documented as it actually runs. Not the version in the handbook. The version with the spreadsheet and the WhatsApp group in it."}],[{"type":"bold","value":"Cost-of-work register"},{"type":"text","value":" — each process scored on hours per month, salary cost attached, error rate where measurable, and the rework those errors generate."}],[{"type":"bold","value":"Automation opportunity map"},{"type":"text","value":" — every process ranked by what automating it is worth. Each entry carries a build estimate, an expected return, a confidence level, and the systems it would touch."}],[{"type":"bold","value":"Blockers list"},{"type":"text","value":" — the data quality, "},{"type":"link","label":"system integrations","href":"/service/system-integrations"},{"type":"text","value":" and access problems to solve before any "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" works. Named, sized, owned."}],[{"type":"bold","value":"Recommended order"},{"type":"text","value":" — what to automate first, second and third, and why. Sequencing matters more than selection, because the first build sets the pattern the rest inherit."}]]},{"type":"p","inline":[{"type":"text","value":"We present it live to you and your process owners, then hand over a document you can circulate internally without us in the room."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howItRuns":{"rich":[{"type":"h2","text":"Two to three weeks, and what it costs your team"},{"type":"p","inline":[{"type":"bold","value":"Week 1 — observation."},{"type":"text","value":" We interview the people who run the work, not only those who manage it. Six to eight sessions of 45 minutes, one per process owner. Your COO or operations lead spends roughly three hours with us across the week."}]},{"type":"p","inline":[{"type":"bold","value":"Week 2 — measurement."},{"type":"text","value":" We pull the numbers behind what we were told: ticket volumes, system logs, a few months of records. Mostly our work. You need one person to grant read access, about two hours."}]},{"type":"p","inline":[{"type":"bold","value":"Week 3 — ranking and readout."},{"type":"text","value":" We build the opportunity map, price each candidate, and present it. The readout runs 90 minutes with whoever decides. The written deliverable follows 48 hours later."}]},{"type":"p","inline":[{"type":"text","value":"Total time from your side is usually under 12 hours. That is the honest number, and it is why the scan works for companies that cannot spare a project team."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"price":{"rich":[{"type":"h2","text":"What it costs and what happens next"},{"type":"p","inline":[{"type":"bold","value":"Typically €4,500–€6,000."}]},{"type":"p","inline":[{"type":"text","value":"What moves it inside that band: the number of processes in scope, how many systems hold the data, and whether the work spans one department or several. A single-department scan with four or five processes sits at the bottom. A cross-functional scan touching finance, operations and customer service sits at the top. We fix the price before we start."}]},{"type":"p","inline":[{"type":"bold","value":"If you want to proceed after the readout"},{"type":"text","value":", the usual next step is an "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":" on the highest-value workflow from the map. We credit the scan fee against the pilot if you commit within 60 days. Taking the map to another firm or building it in house is a legitimate outcome, and the document is written to support it."}]},{"type":"p","inline":[{"type":"bold","value":"CTA:"},{"type":"text","value":" Book an Operational Quick Scan"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"notForYouIf":{"rich":[{"type":"h2","text":"Don't buy this if"},{"type":"ul","items":[[{"type":"bold","value":"You already know exactly which workflow you want built."},{"type":"text","value":" Skip the scan and go straight to the "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":". Paying us to confirm a decision you have already made is a waste of five thousand euros."}],[{"type":"bold","value":"The real question is architecture, not process."},{"type":"text","value":" If your problem is fragmented data, an unclear target stack or a board asking about AI governance, the "},{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":" answers that. The scan does not."}],[{"type":"bold","value":"Nobody senior can commit the interview time."},{"type":"text","value":" The scan is only as good as the access it gets. If process owners cannot give us 45 minutes each, we will produce a document based on what management believes happens, which is the exact failure mode we are trying to avoid."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"Why pay for an audit when other firms do it free?","objection":"price","answerInline":[{"type":"text","value":"Because a free audit is a sales document. It ends in a proposal, and it has to, or the firm giving it away loses money. Ours ends in a ranked list that sometimes says \"automate nothing this year\". We can write that sentence because you paid for the work. At "},{"type":"bold","value":"€4,500–€6,000"},{"type":"text","value":" it is the cheapest way to avoid a six-figure mistake. More detail in "},{"type":"link","label":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"What if the answer is that nothing is worth automating?","objection":"other","answerInline":[{"type":"text","value":"Then we say so, in writing, with the numbers that led us there. It happens. Usually it means the volume is not there yet, or the process is about to change anyway. You still get the process map and the cost-of-work register, which most operations teams have never had in one place."}]},{"question":"How much of my team's time does this take?","objection":"timeline","answerInline":[{"type":"text","value":"Usually under 12 hours in total across the whole engagement. One 45-minute interview per process owner, about three hours from your operations lead, two hours of system access, and a 90-minute readout."}]},{"question":"Who actually does the work?","objection":"seniority","answerInline":[{"type":"text","value":"Senior engineers, and the same people who would build the automation afterwards. That is deliberate. An estimate is only useful from the person who has to honour it. See "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" and the "},{"type":"link","label":"operations","href":"/expertise/operations"},{"type":"text","value":" engagements behind it."}]},{"question":"Do we have to use you for the build?","objection":"lock-in","answerInline":[{"type":"text","value":"No. The deliverable is written so another firm or your own team can act on it. It names systems, volumes and integration points rather than 7code products."}]},{"question":"Our data is a mess. Is it too early for this?","objection":"other","answerInline":[{"type":"text","value":"No — that is what the blockers list is for. Poor data quality is the most common reason to slow down, and the scan is where it surfaces cheaply. Often the honest first move is fixing one integration so two systems finally agree, before any AI is involved."}]},{"question":"Where does our data go during the scan?","objection":"data-residency","answerInline":[{"type":"text","value":"We are an EU company delivering from Romania, so anything we handle stays inside the EEA. A DPA and an NDA are signed before the first interview. Most scans need read access and exports, not production copies."}]},{"question":"What if the scope is bigger than one department?","objection":"other","answerInline":[{"type":"text","value":"We flag it in week one rather than at the end. If the honest answer is a full department rebuild, the "},{"type":"link","label":"Department Automation Sprint","href":"/packages/department-automation-sprint"},{"type":"text","value":" is the right shape and we say so. Wider picture on our "},{"type":"link","label":"AI automation agency","href":"/ai-automation-agency-uk"},{"type":"text","value":" page."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Book the scan","sub":"Two to three weeks, a ranked opportunity map you own, and a straight answer about what is worth building first."}},"sourceFile":"7code-build/content/packages/operational-quick-scan.mdx"}};
const HUB_ARTICLES = {"gdpr-ip-data-residency-outsourcing-ai-eu":{"spec":{"status":"approved","kind":"hub","meta":{"slug":"hub/gdpr-ip-data-residency-outsourcing-ai-eu","title":"GDPR & Outsourcing Software Development to the EU | 7code","metaDescription":"Practitioner guidance on GDPR, IP ownership and data residency when a UK company outsources AI and software development to an EU supplier. Not legal advice.","canonical":"https://www.7code.tech/hub/gdpr-ip-data-residency-outsourcing-ai-eu/","ogImage":"/og/gdpr-ip-data-residency-outsourcing-ai-eu.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"gdpr outsourcing software development eu","secondaryKeywords":["data residency ai development","gdpr nearshore development uk","ip ownership outsourcing software romania","dpa software development supplier","sending personal data to an eu supplier post brexit"],"icpSegment":"outstaffing","searchIntent":"informational","flywheelStage":"find","difficultyNote":"Near-zero direct competition. Existing content is either law-firm marketing written for lawyers, or supplier pages asserting \"we are GDPR compliant\" with no mechanics. The gap is practitioner guidance: what a buyer actually has to arrange, in what order, with the engineering consequences spelled out. High anxiety, low supply. Qualitative only; no verified volume data available.\n"},"cta":{"label":"Book a technical call","action":"booking","href":"/book/technical-call","reassurance":"45 minutes with an engineer. Bring your security questionnaire — we would rather answer it before there is a contract than after."},"blocks":["hero","notLegalAdvice","trustStrip","adequacy","dpa","subProcessors","residencyVsProcessing","hostedVsOpenWeight","ipOwnership","ndas","whatToAsk","faq","close"],"proof":[{"caseStudySlug":"hera","metric":"Clinical intake from days to minutes — RAG-verified, MVP in 3 months","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"RAG development","href":"/rag-development-company"}]},{"caseStudySlug":"lidl-road-safety","metric":"Road-safety programme platform delivered for Lidl Romania","tags":[{"label":"Nearshore development","href":"/nearshore-software-development-uk"},{"label":"System integrations","href":"/service/system-integrations"}]}],"internalLinks":[{"anchor":"nearshore software development","href":"/nearshore-software-development-uk","placement":"adequacy"},{"anchor":"AI consultancy","href":"/ai-consultancy-uk","placement":"whatToAsk"},{"anchor":"how we work","href":"/process","placement":"whatToAsk"}],"schema":{"service":false,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04","readTime":"10 min read"},"openItems":[]},"blocks":{"hero":{"h1":"GDPR, IP and data residency: outsourcing software development to the EU","sub":"What a UK company actually has to arrange before sending data to an EEA supplier, and what changes once an AI model is in the pipeline. Written from the supplier side of the table."},"notLegalAdvice":{"rich":[{"type":"p","inline":[{"type":"text","value":"> "},{"type":"bold","value":"We are engineers, not lawyers."},{"type":"text","value":" This article describes the practical mechanics we deal with on > every engagement — the documents that get signed, the questions that get asked, and the > architectural choices behind them. It is not legal advice and it is not a substitute for it. > Anything contractual should be reviewed by your own counsel before you sign it. Data protection > law, and the adequacy arrangements described below, change over time and vary by jurisdiction. > Verify the current position with a qualified adviser rather than relying on any article, including > this one."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"EU company","label":", delivering from Cluj-Napoca, Romania"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"adequacy":{"rich":[{"type":"h2","text":"The UK–EU position, in practical terms"},{"type":"p","inline":[{"type":"text","value":"Since Brexit the UK and the EU run two parallel data protection regimes that started from the same text. The practical question is narrow: what has to be in place before personal data moves from your systems to a supplier inside the European Economic Area?"}]},{"type":"p","inline":[{"type":"text","value":"For most of the period since Brexit that transfer has been treated as unrestricted in both directions, because each side recognised the other as offering an adequate level of protection. Adequacy decisions are time-limited, subject to review, and can be amended or withdrawn. Buyers routinely treat adequacy as a permanent fact rather than a status with an expiry date."}]},{"type":"p","inline":[{"type":"text","value":"So the answer is conditional. "},{"type":"bold","value":"If adequacy is in force when you transfer"},{"type":"text","value":", no additional mechanism is needed and the work is about the contract and the security posture. "},{"type":"bold","value":"If it is not"},{"type":"text","value":", you fall back to a mechanism such as standard contractual clauses plus a documented transfer risk assessment. Have your counsel confirm the current status before relying on either path."}]},{"type":"p","inline":[{"type":"text","value":"Two consequences either way. Sensible suppliers sign the contractual clauses regardless, so a change in status does not stop the project. And adequacy settles only the legality of the transfer, not whether the arrangement is well run."}]},{"type":"p","inline":[{"type":"text","value":"This is one of the quieter arguments for "},{"type":"link","label":"nearshore software development","href":"/nearshore-software-development-uk"},{"type":"text","value":" inside the EEA. The transfer conversation is shorter, and the supplier sits inside a regime your counsel already understands."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"dpa":{"rich":[{"type":"h2","text":"What a data processing agreement actually has to do"},{"type":"p","inline":[{"type":"text","value":"If a supplier handles personal data on your behalf, you are the controller and they are the processor. That relationship is documented in a data processing agreement, usually a schedule to the main contract. Most suppliers have one. Fewer have one that describes what they actually do."}]},{"type":"p","inline":[{"type":"text","value":"A DPA doing its job covers the following in specifics rather than boilerplate:"}]},{"type":"ul","items":[[{"type":"bold","value":"Subject matter, duration, nature and purpose."},{"type":"text","value":" What data, whose, for how long, to do what."}],[{"type":"bold","value":"Categories of data subject and personal data"},{"type":"text","value":", noting explicitly whether special-category data is involved, because that changes the risk profile and often the architecture."}],[{"type":"bold","value":"Instructions."},{"type":"text","value":" The processor acts only on your documented instructions. This clause is what stops a supplier using your data for something you did not ask for."}],[{"type":"bold","value":"Confidentiality of personnel"},{"type":"text","value":", covering everyone with access."}],[{"type":"bold","value":"Security measures."},{"type":"text","value":" The part most often left vague. Access control, encryption, environment separation, logging and retention, as actually implemented."}],[{"type":"bold","value":"Sub-processors"},{"type":"text","value":" — who else touches the data, and how you are told before a new one is added."}],[{"type":"bold","value":"Assistance obligations"},{"type":"text","value":" — data subject requests, breach notification within an agreed window, support for impact assessments."}],[{"type":"bold","value":"Deletion or return at the end"},{"type":"text","value":", including copies in backups and development environments."}],[{"type":"bold","value":"Audit and information rights"},{"type":"text","value":", and the practical form they take."}]]},{"type":"p","inline":[{"type":"text","value":"A useful test: read the security section and ask whether an engineer could implement your system from it. If it could describe any supplier in any industry, it is decoration."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"subProcessors":{"rich":[{"type":"h2","text":"Sub-processors, and why the model provider is one"},{"type":"p","inline":[{"type":"text","value":"This is where AI projects differ from ordinary software projects, and where older DPA templates fall over."}]},{"type":"p","inline":[{"type":"text","value":"When your supplier builds a feature that sends text to a hosted model API, that provider is processing your data. In practical terms it is a sub-processor of your processor, and it belongs on the sub-processor list alongside the cloud host, the error tracker and the logging platform."}]},{"type":"p","inline":[{"type":"bold","value":"The list must be current and specific."},{"type":"text","value":" Naming the provider is not enough. Which service, which region, under which commercial terms? Consumer and business tiers of the same product frequently differ on retention and training."}]},{"type":"p","inline":[{"type":"bold","value":"Training and retention have to be pinned down."},{"type":"text","value":" Business and enterprise tiers of the major providers generally do not train on customer content by default, and offer configurable retention. Defaults differ and change with contract terms, so confirm this against the agreement your supplier actually holds, not a marketing page."}]},{"type":"p","inline":[{"type":"bold","value":"Logging is the quiet leak."},{"type":"text","value":" Prompts and completions often land in an observability tool, an error tracker or a support ticket. That is a second copy, in a second system, frequently in another region with longer retention than the model provider itself. Trace masking should be a stated requirement."}]},{"type":"p","inline":[{"type":"text","value":"Ask for the data-flow diagram of one AI feature, showing every third party a payload reaches. If it cannot be produced in a day, nobody has done the exercise."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"residencyVsProcessing":{"rich":[{"type":"h2","text":"Data residency is not the same as data processing"},{"type":"p","inline":[{"type":"text","value":"The two terms get used interchangeably in sales conversations. They mean different things."}]},{"type":"p","inline":[{"type":"bold","value":"Residency"},{"type":"text","value":" is where data sits at rest: a database in an EU region, backups in an EU region. Easy to configure, easy to evidence."}]},{"type":"p","inline":[{"type":"bold","value":"Processing"},{"type":"text","value":" is everywhere data is handled in flight, including by people. The region inference runs in, the region logs land in, the laptop of the engineer debugging production, and any support tooling in between."}]},{"type":"p","inline":[{"type":"text","value":"A supplier can honestly say your data is stored in the EU while inference happens elsewhere. Both statements can be true at once. Ask about each separately, in writing."}]},{"type":"p","inline":[{"type":"text","value":"Two related distinctions matter. "},{"type":"bold","value":"Personal data is not the same as your data"},{"type":"text","value":" — commercially sensitive information may carry none, and it is your contract rather than data protection law that protects it. And "},{"type":"bold","value":"production is not the same as development"},{"type":"text","value":": many leaks are simply a copy of a production database sitting in a test environment so someone could reproduce a bug. How a supplier answers on test data tells you more than the residency section of their DPA."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"hostedVsOpenWeight":{"rich":[{"type":"h2","text":"Hosted model APIs versus open-weight models in your own environment"},{"type":"p","inline":[{"type":"text","value":"Every AI project makes this choice, deliberately or by default. The trade is capability against control."}]},{"type":"p","inline":[{"type":"bold","value":"Hosted APIs"},{"type":"text","value":" give you the strongest models, no infrastructure to run and fast iteration. Most offer regional processing and enterprise terms covering retention and training. For most business workloads this is the right answer, and the compliance work is contractual: confirm the region, the retention and the training position, then record it in the sub-processor list."}]},{"type":"p","inline":[{"type":"bold","value":"Open-weight models in your own environment"},{"type":"text","value":" mean data never leaves infrastructure you control. No third-party sub-processor, no cross-border question at inference, full control over logging. The costs are real: you run the hardware or managed instances, and on the hardest reasoning tasks the quality gap can matter."}]},{"type":"p","inline":[{"type":"text","value":"In practice the answer is usually a hybrid. Classification, extraction, routing and summarisation over sensitive documents run well on a smaller open-weight model in your own environment. The genuinely difficult tasks go to a hosted API, with sensitive fields stripped first."}]},{"type":"p","inline":[{"type":"text","value":"Three engineering points decide whether that works. Redaction happens before the call, because removing an identifier from a stored response does not unsend it. A provider abstraction layer is worth building early, so a change in the compliance answer does not mean rewriting the feature. And evals make the choice measurable: one labelled test set against both options compares accuracy against control with numbers rather than opinions."}]},{"type":"p","inline":[{"type":"text","value":"We are model agnostic for this reason. The model is chosen per use case and per data-sensitivity requirement, not by a vendor relationship."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"ipOwnership":{"rich":[{"type":"h2","text":"IP ownership when your supplier is an EU company"},{"type":"p","inline":[{"type":"text","value":"A common worry: if the work is done in Romania, does the client really own it?"}]},{"type":"p","inline":[{"type":"text","value":"The mechanics are less exotic than the anxiety suggests. Ownership of what is created for you is determined by the contract and by the law it says governs it. Jurisdictions differ on who owns work made by an employee or contractor absent an agreement. That is why the agreement exists."}]},{"type":"p","inline":[{"type":"text","value":"Six things to check in a supplier's paperwork, and to have counsel confirm."}]},{"type":"p","inline":[{"type":"bold","value":"Does assignment cover everything, present and future?"},{"type":"text","value":" Code, designs, documentation, prompts, eval datasets, infrastructure definitions. Prompts and eval sets are missing from older templates and are now core product assets."}]},{"type":"p","inline":[{"type":"bold","value":"When does transfer happen?"},{"type":"text","value":" Usually on full payment, which is normal. What matters is that the trigger is unambiguous and you know what you hold before it fires."}]},{"type":"p","inline":[{"type":"bold","value":"Does the supplier's team assign to the supplier?"},{"type":"text","value":" The chain matters. Employment contracts should assign work product upward, so the supplier has something to pass to you. If any part of the team is subcontracted, the same must hold one level down."}]},{"type":"p","inline":[{"type":"bold","value":"What is retained, and under what licence?"},{"type":"text","value":" Every experienced firm reuses internal scaffolding, and that makes your project cheaper. Discovering after handover that a component you depend on is not yours does not. Retained items should be named and licensed to you perpetually and irrevocably."}]},{"type":"p","inline":[{"type":"bold","value":"Open-source components."},{"type":"text","value":" Ask for a dependency inventory with licences. Awkward to reconstruct later."}]},{"type":"p","inline":[{"type":"bold","value":"Governing law and forum."},{"type":"text","value":" Often English law for a UK client, sometimes the supplier's. Both work. It should be a conscious choice rather than whatever the template said."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"ndas":{"rich":[{"type":"h2","text":"NDAs, and what they do not cover"},{"type":"p","inline":[{"type":"text","value":"Sign one before the first detailed technical conversation. Any serious supplier will."}]},{"type":"p","inline":[{"type":"bold","value":"Mutual beats one-way."},{"type":"text","value":" You will see their methods and internal tooling as well as the reverse, and a mutual agreement is quicker to negotiate because nobody is arguing about asymmetry."}]},{"type":"p","inline":[{"type":"bold","value":"An NDA is not a DPA and not an IP assignment."},{"type":"text","value":" It governs confidentiality between two businesses. It says nothing about who owns the code, and it does not make a transfer of personal data lawful. It is the first of three documents, not a substitute for the other two."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whatToAsk":{"rich":[{"type":"h2","text":"What to actually ask a supplier"},{"type":"p","inline":[{"type":"text","value":"Ten questions. Written answers, before contract, not reassurance on a call."}]},{"type":"p","inline":[{"type":"text","value":"1. Where is personal data stored at rest, and in which region is it processed in flight? 2. The full sub-processor list for my engagement, including the model provider's specific service and region. 3. Under which commercial terms is your model provider account held, and what are the retention and training positions under them? 4. A data-flow diagram for one AI feature, marking every third party a payload reaches. 5. What appears in traces and logs, how is it masked, where does it live, and for how long? 6. Do your engineers work with production data? Under what controls, or how is test data generated? 7. Which transfer mechanism does the contract rely on, and what happens if adequacy changes mid-engagement? 8. The IP clause, the transfer trigger, and the list of retained internal components. 9. What is your breach notification window to us, and who makes the call? 10. How is data deleted at the end, including backups and development environments, and how is that evidenced?"}]},{"type":"p","inline":[{"type":"text","value":"Quick, specific answers mean the supplier has done this before. A certification badge and a paragraph about taking security seriously means keep asking."}]},{"type":"p","inline":[{"type":"text","value":"We settle all ten during scoping rather than mid-build. The sequence is on "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":", and where it fits a broader engagement on our "},{"type":"link","label":"AI consultancy","href":"/ai-consultancy-uk"},{"type":"text","value":" page."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"Is it still straightforward for a UK company to use an EU supplier after Brexit?","objection":"data-residency","answerInline":[{"type":"text","value":"In day-to-day practice, yes, and it is common. The position depends on the adequacy status in force at the time, which is reviewed periodically and can change. Sensible suppliers keep standard contractual clauses in the pack as a fallback. Have your counsel confirm the current position rather than relying on an article."}]},{"question":"Where does our data sit if we work with you?","objection":"data-residency","answerInline":[{"type":"text","value":"Inside the EEA by default. We are a Romanian company delivering from Cluj-Napoca, and we deploy into your own cloud account in an EU region unless you say otherwise. Where data cannot leave your environment at all, we run open-weight models inside your infrastructure."}]},{"question":"Do you sign our DPA or do we sign yours?","objection":"other","answerInline":[{"type":"text","value":"Either. Most clients prefer their own, which is sensible when they are the controller. We review it, flag anything that does not match what we actually do, and sign."}]},{"question":"Does the model provider train on our data?","objection":"data-residency","answerInline":[{"type":"text","value":"Under business and enterprise terms the major providers generally do not train on customer content by default, and offer configurable retention. Terms differ and change, so we confirm it in writing against the agreement in place for your project and record it in the sub-processor list."}]},{"question":"Who owns the code and when?","objection":"ip-ownership","answerInline":[{"type":"text","value":"You do, transferring on full payment. That covers code, designs, documentation, prompts, eval datasets and infrastructure definitions. Anything built on our internal scaffolding is named explicitly and licensed to you for use in the delivered system."}]},{"question":"Can you complete our security questionnaire and sign an NDA first?","objection":"other","answerInline":[{"type":"text","value":"Yes to both, and we prefer a mutual NDA. Send the questionnaire before the technical call. Anything we cannot answer we mark as such rather than guess."}]},{"question":"What happens to our data when the engagement ends?","objection":"after-launch","answerInline":[{"type":"text","value":"Access is revoked and working copies are deleted on the schedule agreed in the DPA, including development environments and backups. Because we deploy into your cloud account, production data was in your control throughout."}]},{"question":"Should we run a data protection impact assessment?","objection":"other","answerInline":[{"type":"text","value":"That is a question for your own adviser. Where one is needed we supply the technical detail: data flows, sub-processors, retention, security measures. We do not decide whether it is required."}]},{"question":"Does any of this slow a project down?","objection":"timeline","answerInline":[{"type":"text","value":"Only if it starts late. Handled during scoping it costs no calendar time. Handled mid-build, a security review can hold a project for weeks."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Bring the security questionnaire to the first call","sub":"We would rather answer the compliance questions before there is a contract than after. Data flows, sub-processors, residency and IP, settled during scoping."}},"sourceFile":"7code-build/content/hub/gdpr-ip-data-residency-outsourcing-ai-eu.mdx"},"questions-to-ask-an-ai-development-partner":{"spec":{"status":"approved","kind":"hub","meta":{"slug":"hub/questions-to-ask-an-ai-development-partner","title":"Questions to Ask an AI Development Company | 15 to Use","metaDescription":"15 questions to ask an AI development company, with what a good answer sounds like and what a bad one sounds like. Written by engineers who answer them.","canonical":"https://www.7code.tech/hub/questions-to-ask-an-ai-development-partner/","ogImage":"/og/questions-to-ask-an-ai-development-partner.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"questions to ask an ai development company","secondaryKeywords":["how to choose an ai development partner","how to vet an ai agency","ai development company evaluation criteria","questions to ask an ai agency","choosing an llm development partner"],"icpSegment":"outstaffing","searchIntent":"commercial-investigation","flywheelStage":"find","difficultyNote":"A crowded genre where every existing version is generic — \"do they understand your business\", \"check their portfolio\". None of the incumbent lists contain a question a non-engineering agency would struggle to answer. The differentiator is specificity: eval coverage, retrieval metrics, prompt ownership, token attribution, model deprecation and rollback are questions that separate a delivery firm from a prototype shop. Qualitative only; no verified volume data available.\n"},"cta":{"label":"Book a technical call","action":"booking","href":"/book/technical-call","reassurance":"45 minutes with the engineer who would build it, not a salesperson. Bring the hardest question on this list."},"blocks":["hero","trustStrip","howToUse","questions","fairness","scorecard","faq","close"],"proof":[{"caseStudySlug":"hera","metric":"Clinical intake from days to minutes — RAG-verified, MVP in 3 months","tags":[{"label":"RAG development","href":"/rag-development-company"},{"label":"LLM & agent development","href":"/service/llm-agent-development"}]},{"caseStudySlug":"g42-fleet","metric":"Fleet platform deployed at EXPO 2020 scale, over a two-year engagement","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"System integrations","href":"/service/system-integrations"}]}],"internalLinks":[{"anchor":"AI development company","href":"/ai-development-company-uk","placement":"howToUse"},{"anchor":"AI agent development","href":"/ai-agent-development-company","placement":"questions"},{"anchor":"RAG development","href":"/rag-development-company","placement":"questions"},{"anchor":"how we work","href":"/process","placement":"scorecard"},{"anchor":"LLM and agent development","href":"/service/llm-agent-development","placement":"questions"}],"schema":{"service":false,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04","readTime":"12 min read"},"openItems":[]},"blocks":{"hero":{"h1":"Questions to ask an AI development company before you hire","sub":"Fifteen questions a prototype shop cannot answer well, with what a good answer sounds like and what a bad one sounds like. Written by the people who get asked them."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"howToUse":{"rich":[{"type":"h2","text":"Why the usual list is useless"},{"type":"p","inline":[{"type":"text","value":"Most buying guides tell you to check the portfolio, ask about the process and see whether they understand your industry. Every agency passes that. The demo will be good, because demos are easy, and the gap between a demo and a system that survives real users is where projects die."}]},{"type":"p","inline":[{"type":"text","value":"The questions below are about what happens after the model returns something wrong at 2am on a Tuesday. A firm that has run AI features in production answers them without preparation. A firm that has only built prototypes answers them with philosophy."}]},{"type":"p","inline":[{"type":"text","value":"Use them in a technical call, not a sales call. You are not testing whether they can say the words. You are testing for specifics: a number, a tool, a story about the time it went wrong."}]},{"type":"p","inline":[{"type":"text","value":"One fair warning. No supplier passes every question perfectly, and a firm that claims to should worry you more than one admitting a gap. You want a pattern of concrete answers and honesty about the edges. Our "},{"type":"link","label":"AI development company","href":"/ai-development-company-uk"},{"type":"text","value":" page sets out how we scope and deliver, if you want the shape of a full engagement first."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"questions":{"rich":[{"type":"h2","text":"The fifteen questions"},{"type":"p","inline":[{"type":"text","value":"### 1. Which engineer will write this code, and can I meet them this week?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" The single most common failure in agency work is the bait and switch: senior people sell it, juniors build it. This question surfaces that in one move, because a firm that intends to hand your project to whoever is free cannot produce a name."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" a name, a short summary of what that person last shipped, and an offer to put them on a call in the next few days. Better still, they were already on your first call."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" \"we allocate from our talent pool based on availability at kickoff\", or a promise that you will meet the team after signature."}]},{"type":"p","inline":[{"type":"text","value":"### 2. What does your eval suite look like for a feature like mine?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" Evals are the automated tests of AI engineering. Without them, nobody can tell whether a change improved the system or quietly broke it. A firm that does not run evals is shipping on vibes and will be unable to tell you why quality dropped."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" they describe a labelled dataset built from your real data, a scoring method per task type, a threshold that blocks a release, and how the set grows when a bug is found in production. They will tell you how many examples they typically start with and why."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" \"we test it thoroughly\", \"our prompts are well engineered\", or eval described as something they do at the end before handover."}]},{"type":"p","inline":[{"type":"text","value":"### 3. How do you measure retrieval quality, separately from answer quality?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" In a retrieval system, most wrong answers are retrieval failures wearing a generation costume. If you only measure the final answer, you cannot tell whether to fix the index, the chunking, the query rewriting or the prompt. Teams that conflate the two debug by guessing."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" they measure whether the right document made it into context at all, before judging the answer. They will name the metrics they use, explain how they built the set of question-to-correct-document pairs, and describe what they changed when recall was poor. Anyone doing serious "},{"type":"link","label":"RAG development","href":"/rag-development-company"},{"type":"text","value":" has these numbers."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" \"we use a vector database\", as if the choice of database were the answer. Naming a tool is not naming a measurement."}]},{"type":"p","inline":[{"type":"text","value":"### 4. What is your guardrail strategy, and what specifically does it block?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" Guardrails are where legal and brand risk live. Vague ones are worse than none, because they create the impression of safety without a specification anyone can check."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" a layered description. Input validation, output schema enforcement, refusal handling for out-of-scope questions, a check on anything leaving the system, and a defined behaviour when a guardrail fires — retry, escalate, or fail closed. They should also say what they deliberately do not block, and why over-blocking has a cost."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" \"the model provider handles safety\". That covers their risk, not yours."}]},{"type":"p","inline":[{"type":"text","value":"### 5. Who owns the prompts, and where do they live?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" Prompts are product logic. If they live in a proprietary platform you cannot export, you have bought a dependency, not a system. If they live inside code with no versioning, you cannot roll one back or run an A/B comparison."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" you own them, they are versioned in your repository, they are reviewable in a pull request, and changing one triggers the eval suite. Prompt changes are treated as code changes because they are."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" prompts held in the agency's tooling, or \"we keep them internally because they are our secret sauce\". Your business logic is not their intellectual property."}]},{"type":"p","inline":[{"type":"text","value":"### 6. How do you attribute token cost per feature?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" An unattributed AI bill is a bill you cannot manage. When spend triples you need to know which feature did it, and whether it came from more usage or a worse prompt. Without attribution, your only control is turning things off."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" every call tagged by feature, tenant and environment, cost visible per run in a dashboard, and an alert when spend per unit of work moves. They can quote the cost of a single transaction, not just the monthly total."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" \"we monitor the provider console\". That is one aggregate number and it tells you nothing about which part of your product is expensive."}]},{"type":"p","inline":[{"type":"text","value":"### 7. What happens when the model we build on is deprecated?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" Providers retire models on their own schedule. If your system is welded to one model's exact behaviour, that announcement is an emergency. This question tests whether the architecture anticipates something that is certain to happen."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" an abstraction layer over the provider, evals that can be re-run against a candidate replacement to quantify the difference, and a migration process they have actually performed. They should be candid that migration is real work, not free."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" \"we always use the latest model\", or a claim that swapping models is trivial. Anyone who has done it knows prompts do not transfer cleanly."}]},{"type":"p","inline":[{"type":"text","value":"### 8. What is your rollback plan when a change makes output worse?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" Quality regressions in AI systems are often silent. Nothing throws an error; the answers just get slightly worse. You need to know how they detect that and how fast they can undo it."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" prompts, model version and configuration are all versioned together and deployable as a unit, releases go out behind a flag or to a subset of traffic first, and there is a documented path back that has been rehearsed. They should quote a time: minutes, not days."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" rollback described only for application code, with prompts and model configuration edited live in a console."}]},{"type":"p","inline":[{"type":"text","value":"### 9. How do you handle data residency, and what exactly leaves our environment?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" Most teams cannot answer precisely which data reaches which third party. That is a problem in any regulated context, and an awkward one in a supplier due-diligence questionnaire."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" a specific data-flow answer. What is sent to the model provider, in what form, whether it is redacted first, which region processes it, what is retained and for how long, and what the alternative is when data cannot leave your environment at all. They should raise the option of running an open-weight model in your own infrastructure without being prompted."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" \"it is all encrypted and GDPR compliant\". Encryption in transit is not a residency answer, and compliance is not a description of where data goes."}]},{"type":"p","inline":[{"type":"text","value":"### 10. What will you refuse to build with an LLM?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" A firm that will put a model into anything is optimising for the invoice. Serious engineers have a list of things that should be plain deterministic code, and they will argue for it against their own commercial interest."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" arithmetic, anything requiring exact reproducibility, decisions with a hard legal or financial consequence and no human review, and any rule that can be written as a rule. They will suggest hybrid designs where the model handles the fuzzy part and code handles the rest."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" enthusiasm without limits. If everything is an agent, nothing has been thought about."}]},{"type":"p","inline":[{"type":"text","value":"### 11. How do you write acceptance criteria for a non-deterministic system?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" Traditional acceptance testing assumes the same input gives the same output. Models do not work that way. If nobody has solved this contractually, you will argue about whether the thing works at the exact moment you are due to pay for it."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" acceptance defined statistically against a labelled set that you have seen and agreed. A stated pass rate per task category, an agreed behaviour for the failing tail, and a named person on your side who signs off the test set before the build starts."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" \"you will know it when you see it\", or a demo used as acceptance."}]},{"type":"p","inline":[{"type":"text","value":"### 12. What does your production observability look like?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" When a user says the assistant gave a bad answer last Thursday, someone has to reconstruct exactly what happened. Without traces, that investigation is impossible and every bug report becomes an argument."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" every run is traced end to end — inputs, retrieved context, tool calls, model output, latency, cost — with the trace linkable from a support ticket. They will tell you the retention period and how personal data is masked in the traces."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" application logs only, or a dashboard that shows request counts and error rates but not what the model actually saw."}]},{"type":"p","inline":[{"type":"text","value":"### 13. Tell me about a project that went badly, and what you changed afterwards."}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" This is the fairness question, and it is the most revealing one on the list. Everybody has a project that went wrong. A firm that cannot describe one is either very new or not being straight with you. You are listening for ownership rather than blame, and for a specific change to how they work."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" a real situation, a clear description of what they misjudged, what it cost, and the concrete practice they adopted afterwards. Good firms are comfortable here. It tends to be the moment the conversation becomes honest."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" a story where the client was the problem, or a non-answer dressed as discretion. Confidentiality prevents naming a client. It does not prevent describing a mistake."}]},{"type":"p","inline":[{"type":"text","value":"### 14. Who owns the IP, and at what moment does it transfer?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" \"You own everything\" is easy to say and often untrue in the contract. The details matter: their internal frameworks, third-party components, the model weights if anything was fine-tuned, and the timing of transfer."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" a clear statement of what transfers and when, usually on full payment, with any retained internal tooling named and licensed to you. They will point to the clause rather than paraphrase it. Anything built on their own scaffolding is called out explicitly."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" a verbal assurance not reflected in the draft agreement, or silence about pre-existing components embedded in your system."}]},{"type":"p","inline":[{"type":"text","value":"### 15. What does handover look like if we take this in-house in six months?"}]},{"type":"p","inline":[{"type":"bold","value":"Why it matters."},{"type":"text","value":" The best test of whether a supplier is building for you or for their retainer. Ask it early, while it is hypothetical and nobody is defensive."}]},{"type":"p","inline":[{"type":"bold","value":"A good answer sounds like:"},{"type":"text","value":" an actual list. Repository access, infrastructure as code in your cloud account, runbooks, the eval suite and its dataset, prompt history, an architecture decision record, and a paid handover period with your engineers shadowing theirs. They will treat it as a normal outcome rather than a threat."}]},{"type":"p","inline":[{"type":"bold","value":"A bad answer sounds like:"},{"type":"text","value":" hesitation, or a handover fee that appears for the first time in this conversation. If a supplier cannot describe how you leave, you should assume leaving is difficult."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"fairness":{"rich":[{"type":"h2","text":"Being fair to the supplier"},{"type":"p","inline":[{"type":"text","value":"A checklist can be used badly. Three notes so this one is not."}]},{"type":"p","inline":[{"type":"bold","value":"Do not expect fifteen perfect answers."},{"type":"text","value":" A small firm may not run per-feature cost attribution on every project. What matters is whether the gaps are acknowledged and what they would do instead."}]},{"type":"p","inline":[{"type":"bold","value":"Weight the questions to your risk."},{"type":"text","value":" For an internal tool used by twelve people, guardrails and rollback matter less than speed. Where output touches customers or regulated decisions, questions four, nine and eleven are the whole conversation."}]},{"type":"p","inline":[{"type":"bold","value":"Give them the context to answer well."},{"type":"text","value":" Several of these have no good answer in the abstract. Retrieval quality depends on your corpus; cost attribution depends on your architecture. Send the problem in advance. A considered answer teaches you more than an ambush."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"scorecard":{"rich":[{"type":"h2","text":"How to score the conversation"},{"type":"p","inline":[{"type":"text","value":"Three signals separate the firms worth shortlisting, whatever the individual answers were."}]},{"type":"p","inline":[{"type":"bold","value":"Specificity."},{"type":"text","value":" Good answers contain nouns: a tool, a metric, a threshold, a number. Weak answers contain adjectives. Count them."}]},{"type":"p","inline":[{"type":"bold","value":"Volunteered limits."},{"type":"text","value":" A supplier who tells you what they would not build, or where their approach gets expensive, is describing real experience. Nobody who has shipped this work thinks it is easy."}]},{"type":"p","inline":[{"type":"bold","value":"Consistency between the call and the contract."},{"type":"text","value":" Everything said about IP, handover, data residency and ownership should appear in the draft agreement without you asking. If it does not, the call was marketing."}]},{"type":"p","inline":[{"type":"text","value":"We set out scoping, evals, delivery and handover on "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":", and what we build on "},{"type":"link","label":"AI agent development","href":"/ai-agent-development-company"},{"type":"text","value":" and "},{"type":"link","label":"LLM and agent development","href":"/service/llm-agent-development"},{"type":"text","value":"."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"How many suppliers should I run this with?","objection":"other","answerInline":[{"type":"text","value":"Three is usually enough, and more than four wastes everyone's time including yours. Run the same questions with each, in the same order, and write the answers down during the call. The differences are obvious on paper and much less obvious from memory a week later."}]},{"question":"Can I ask these if I am not technical?","objection":"seniority","answerInline":[{"type":"text","value":"Yes, and you should. You do not need to evaluate the technical content to evaluate the answer. Note whether they gave you something specific, whether they explained it in language you followed, and whether they were comfortable being pinned down. Bring a technical colleague or advisor for the follow-up if you have one."}]},{"question":"What if a supplier refuses to let me meet the engineer?","objection":"seniority","answerInline":[{"type":"text","value":"Treat it as an answer. There are legitimate scheduling reasons for a delay of a few days, but not for a refusal. The person who will build the system should be reachable before you sign, and at 7code they are usually already on the first call."}]},{"question":"Are these questions unfair to smaller firms?","objection":"other","answerInline":[{"type":"text","value":"No, and small firms often do better on them. A two-person team can name the engineer immediately and usually knows their own cost per transaction. Where small suppliers struggle is continuity, so add a question about what happens if their lead engineer is unavailable for a month."}]},{"question":"Should I send the list in advance?","objection":"other","answerInline":[{"type":"text","value":"Send it. You are hiring for engineering judgement, not improvisation. A prepared answer with real artefacts behind it beats a fluent one invented on the call."}]},{"question":"What if their answers are good but the price is high?","objection":"price","answerInline":[{"type":"text","value":"Compare what is included rather than the headline. Evals, guardrails, traces and cost dashboards are either in the quote or they are work your team does later. A cheaper quote that omits them is a deferred invoice, not a saving."}]},{"question":"How do I check what they tell me?","objection":"other","answerInline":[{"type":"text","value":"Ask for a reference from a client whose system is still in production a year later, and put the rollback and handover questions to them. Review platforms help with the relationship questions. Neither substitutes for a technical conversation with the engineer."}]},{"question":"Do you mind being asked these?","objection":"other","answerInline":[{"type":"text","value":"Not at all. We wrote them. Buyers who ask hard questions early make good clients later, because expectations are set before there is a contract to protect."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Bring the hardest question on the list","sub":"A technical call with the engineer who would do the work. No slides, no account manager, and a straight answer about anything on this page."}},"sourceFile":"7code-build/content/hub/questions-to-ask-an-ai-development-partner.mdx"},"what-ai-automation-costs-uk":{"spec":{"status":"approved","kind":"hub","meta":{"slug":"hub/what-ai-automation-costs-uk","title":"How Much Does AI Automation Cost? UK & EU Price Bands","metaDescription":"How much does AI automation cost? Real bands for UK and EU buyers: €4,500 for a process scan, €15,000–€25,000 for one workflow, plus what moves the number.","canonical":"https://www.7code.tech/hub/what-ai-automation-costs-uk/","ogImage":"/og/what-ai-automation-costs-uk.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"how much does ai automation cost","secondaryKeywords":["ai automation cost uk","ai automation pricing","cost of automating a business process","ai workflow automation cost","how much does business process automation cost"],"icpSegment":"smb-automation","searchIntent":"commercial-investigation","flywheelStage":"find","difficultyNote":"Pricing intent is the highest-frequency question buyers put to AI assistants, and almost no agency in this field publishes a number. Incumbents answer with \"it depends\" and a contact form. Publishing real bands with the variables that move them is the entire competitive advantage here — an assistant cites whoever supplies an actual figure. Qualitative only; no verified volume data available.\n"},"cta":{"label":"Book an Operational Quick Scan","action":"booking","href":"/book/quick-scan","reassurance":"45 minutes. No prep needed. You'll leave with two or three processes worth automating, whether or not you work with us."},"blocks":["hero","trustStrip","shortAnswer","costDrivers","workedExample","overruns","howToReduce","runningCosts","package","faq","close"],"proof":[{"caseStudySlug":"numerize","metric":"6,000+ customer accounts running on the platform","tags":[{"label":"AI automation","href":"/service/ai-automation"},{"label":"System integrations","href":"/service/system-integrations"}]},{"caseStudySlug":"hera","metric":"Clinical intake from days to minutes — RAG-verified, MVP in 3 months","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"LLM & agent development","href":"/service/llm-agent-development"}]}],"internalLinks":[{"anchor":"AI automation agency","href":"/ai-automation-agency-uk","placement":"shortAnswer"},{"anchor":"Operational Quick Scan","href":"/packages/operational-quick-scan","placement":"shortAnswer"},{"anchor":"Automation Pilot","href":"/packages/automation-pilot","placement":"workedExample"},{"anchor":"Department Automation Sprint","href":"/packages/department-automation-sprint","placement":"shortAnswer"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"shortAnswer"},{"anchor":"AI automation","href":"/service/ai-automation","placement":"costDrivers"},{"anchor":"system integrations","href":"/service/system-integrations","placement":"costDrivers"},{"anchor":"how we work","href":"/process","placement":"faq"}],"schema":{"service":false,"faqPage":true,"breadcrumbList":true,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04","readTime":"9 min read"},"openItems":[]},"blocks":{"hero":{"h1":"How much does AI automation cost for a UK company?","sub":"Real bands, what moves them, and one workflow costed line by line. Written by the engineers who quote this work, not by a marketing team."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"shortAnswer":{"rich":[{"type":"h2","text":"The short answer, before the caveats"},{"type":"p","inline":[{"type":"text","value":"Most buyers get told \"it depends\" and a discovery call. Here is the actual shape of the market as we quote it. These are the bands we work in, in euros, for UK and EU clients."}]},{"type":"table","rows":[[[{"type":"text","value":"What you are buying"}],[{"type":"text","value":"Duration"}],[{"type":"text","value":"Typical cost"}]],[[{"type":"bold","value":"Operational Quick Scan"},{"type":"text","value":" — map the processes, rank them, cost them"}],[{"type":"text","value":"2–3 weeks"}],[{"type":"bold","value":"€4,500 – €6,000"}]],[[{"type":"bold","value":"AI-Ready Ops Blueprint"},{"type":"text","value":" — target architecture, data readiness, sequencing"}],[{"type":"text","value":"4–6 weeks"}],[{"type":"bold","value":"€9,000 – €14,000"}]],[[{"type":"bold","value":"Automation Pilot"},{"type":"text","value":" — one workflow automated end to end, in production"}],[{"type":"text","value":"6–10 weeks"}],[{"type":"bold","value":"€15,000 – €25,000"}]],[[{"type":"bold","value":"Department Automation Sprint"},{"type":"text","value":" — a whole function digitised"}],[{"type":"text","value":"10–16 weeks"}],[{"type":"bold","value":"€40,000 – €65,000"}]],[[{"type":"bold","value":"Production MVP"},{"type":"text","value":" — a new AI product, not an internal automation"}],[{"type":"text","value":"3–5 months"}],[{"type":"bold","value":"€40,000 – €90,000"}]],[[{"type":"bold","value":"Dedicated senior engineer"},{"type":"text","value":" — embedded in your team"}],[{"type":"text","value":"monthly"}],[{"type":"bold","value":"€6,400 – €8,000"}]],[[{"type":"bold","value":"Dedicated architect"}],[{"type":"text","value":"monthly"}],[{"type":"bold","value":"€9,600 – €12,800"}]],[[{"type":"bold","value":"Dedicated pod"},{"type":"text","value":" — architect plus two senior engineers"}],[{"type":"text","value":"monthly"}],[{"type":"bold","value":"€22,000 – €29,000"}]]]},{"type":"p","inline":[{"type":"text","value":"Two caveats, and they matter more than the table."}]},{"type":"p","inline":[{"type":"text","value":"First, these are build costs. They do not include what the automation costs to run each month, which is a separate and much smaller number. We cover that further down."}]},{"type":"p","inline":[{"type":"text","value":"Second, the range inside each band is not padding. A €15,000 pilot and a €25,000 pilot are different projects. The next section is about what decides which one you have."}]},{"type":"p","inline":[{"type":"text","value":"If you want the wider picture of how this work gets scoped and delivered, start with our "},{"type":"link","label":"AI automation agency","href":"/ai-automation-agency-uk"},{"type":"text","value":" page. If you want the cheapest honest way to find out what your own number is, that is the "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":"."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"costDrivers":{"rich":[{"type":"h2","text":"What actually moves the number"},{"type":"p","inline":[{"type":"text","value":"Six things decide where you land in a band. In our experience they account for nearly all the variance between two projects that sound identical in a first call."}]},{"type":"p","inline":[{"type":"bold","value":"1. How many systems the workflow touches."},{"type":"text","value":" One system with a documented API is straightforward. Four systems, one of which is a 2011 ERP with a CSV export and no test environment, is a different project. Integration work is the single largest cost driver in "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":", and it is almost always underestimated because it is invisible in the process diagram."}]},{"type":"p","inline":[{"type":"bold","value":"2. Whether the process is actually defined."},{"type":"text","value":" Many processes exist as habits, not rules. Ask five people how an invoice exception is handled and you get five answers. Automating that means deciding the rule first, which is a business decision, not an engineering one. It takes meeting time, and meeting time with the right people is the scarcest thing in these projects."}]},{"type":"p","inline":[{"type":"bold","value":"3. The cost of being wrong."},{"type":"text","value":" An automation that drafts an internal summary needs light checking. One that issues a credit note, files a regulatory return, or emails a customer needs review steps, audit trails, and a tested rollback. The accuracy bar you set drives the amount of engineering around the model, and that scaffolding usually costs more than the model call itself."}]},{"type":"p","inline":[{"type":"bold","value":"4. Data quality and access."},{"type":"text","value":" Clean, structured, accessible data makes a project cheap. Scanned PDFs, inconsistent reference codes, duplicated customer records and a data owner on annual leave make it expensive. This is worth diagnosing before you commit to a build, not during one."}]},{"type":"p","inline":[{"type":"bold","value":"5. How many exceptions you want handled."},{"type":"text","value":" Automating the eighty per cent of cases that follow the rule is fast. The remaining twenty per cent is where most of the budget goes. Often the right answer is to route exceptions to a person and stop there, but that has to be an explicit decision."}]},{"type":"p","inline":[{"type":"bold","value":"6. Whether it has to be real time."},{"type":"text","value":" A nightly batch job is simpler, cheaper and easier to fix than a live event-driven pipeline. Ask honestly whether anyone would notice a four-hour delay. Frequently nobody would, and the answer saves a meaningful share of the build."}]},{"type":"p","inline":[{"type":"text","value":"None of these are AI-specific. That is the point. The model is rarely the hard part, and "},{"type":"link","label":"system integrations","href":"/service/system-integrations"},{"type":"text","value":" usually are."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"workedExample":{"rich":[{"type":"h2","text":"One workflow, costed line by line"},{"type":"p","inline":[{"type":"text","value":"Here is a realistic shape for a mid-range "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":". The workflow: inbound supplier invoices arrive by email, someone opens each one, keys the values into a finance system, checks them against a purchase order, and escalates mismatches."}]},{"type":"p","inline":[{"type":"text","value":"The split below is illustrative of how we build a quote. The total is the published band, and the proportions shift by project."}]},{"type":"table","rows":[[[{"type":"text","value":"Line item"}],[{"type":"text","value":"What it covers"}],[{"type":"text","value":"Share of the build"}]],[[{"type":"text","value":"Process definition and rules"}],[{"type":"text","value":"Sitting with the finance team, writing down what actually happens, agreeing the exception rules"}],[{"type":"text","value":"~10%"}]],[[{"type":"text","value":"Data and document handling"}],[{"type":"text","value":"Ingesting the email, extracting fields from mixed-quality PDFs, normalising supplier references"}],[{"type":"text","value":"~20%"}]],[[{"type":"text","value":"Integration"}],[{"type":"text","value":"Reading purchase orders and writing entries into the finance system, including a test environment that may not exist yet"}],[{"type":"text","value":"~25%"}]],[[{"type":"text","value":"Decision logic and model work"}],[{"type":"text","value":"Prompting, structured output, confidence scoring, choosing what the model decides and what plain code decides"}],[{"type":"text","value":"~15%"}]],[[{"type":"text","value":"Evals and test data"}],[{"type":"text","value":"A labelled set of real invoices, an automated scoring run, a threshold below which the release does not ship"}],[{"type":"text","value":"~10%"}]],[[{"type":"text","value":"Human-in-the-loop interface"}],[{"type":"text","value":"The review queue where a person confirms or corrects a low-confidence extraction"}],[{"type":"text","value":"~10%"}]],[[{"type":"text","value":"Observability, guardrails, rollback"}],[{"type":"text","value":"Traces, a cost dashboard, alerting on drift, and the switch that puts the process back to manual"}],[{"type":"text","value":"~10%"}]]]},{"type":"p","inline":[{"type":"text","value":"Total: "},{"type":"bold","value":"€15,000 – €25,000"},{"type":"text","value":", six to ten weeks, one workflow live in production."}]},{"type":"p","inline":[{"type":"text","value":"Two things are worth noticing. The model work is roughly one-seventh of the project. And the last three lines, the ones that make it survivable, are about a third. A quote that omits them is not cheaper. It has moved the cost to the month after go-live, when your team is the one absorbing it."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"overruns":{"rich":[{"type":"h2","text":"What makes these projects go over"},{"type":"p","inline":[{"type":"text","value":"Overruns in this work are boringly predictable. We have seen the same five causes repeatedly, and four of them are avoidable before a contract is signed."}]},{"type":"p","inline":[{"type":"bold","value":"Access arrives late."},{"type":"text","value":" The build is quoted assuming credentials, a sandbox and sample data in week one. They arrive in week four because a security review was never scheduled. Nothing was mis-estimated; the calendar moved. Book the access conversation before kickoff."}]},{"type":"p","inline":[{"type":"bold","value":"The process changes underneath the build."},{"type":"text","value":" Operations restructures the approval chain in week five. That is a legitimate business decision, and it invalidates work already done. Freeze the process for the pilot, or accept a change order."}]},{"type":"p","inline":[{"type":"bold","value":"Edge cases surface as requirements."},{"type":"text","value":" \"It also needs to handle credit notes\" is a new project, not a detail. Write the exclusion list into the scope explicitly, and review it in week two rather than week eight."}]},{"type":"p","inline":[{"type":"bold","value":"Nobody owns the outcome on your side."},{"type":"text","value":" A project with no single named owner drifts into consensus-seeking. Decisions that take an hour with an owner take three weeks in a committee. This is the most expensive failure mode we see, and it has nothing to do with technology."}]},{"type":"p","inline":[{"type":"bold","value":"The accuracy bar moves once people see the output."},{"type":"text","value":" A team asks for eighty per cent, sees the remaining twenty, and wants ninety-five. That is a reasonable reaction and a genuine change of scope. Agree the bar against a labelled test set at the start, not against a demo."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"howToReduce":{"rich":[{"type":"h2","text":"How to spend less without getting less"},{"type":"p","inline":[{"type":"text","value":"Seven levers, roughly in order of how much they save."}]},{"type":"p","inline":[{"type":"bold","value":"Scan before you build."},{"type":"text","value":" The cheapest project is the one you correctly decided not to do. Two to three weeks of process mapping regularly removes a six-figure build from the plan, or replaces it with a much smaller one."}]},{"type":"p","inline":[{"type":"bold","value":"Automate one workflow, not a department."},{"type":"text","value":" A single pilot proves the pattern, exposes the data problems and gives your team something to react to. Buying the department sprint first means making every scoping decision before you have learned anything."}]},{"type":"p","inline":[{"type":"bold","value":"Use code where code works."},{"type":"text","value":" A lot of what gets sold as AI automation is a rules engine with better marketing. If a decision can be expressed as a rule, write the rule. It is cheaper to build, cheaper to run, and it does not need an eval suite. Reserve the model for genuinely fuzzy judgement."}]},{"type":"p","inline":[{"type":"bold","value":"Pick a process with one system of record."},{"type":"text","value":" Cost tracks integration count almost linearly. A workflow living inside one platform can be a third of the price of the same logic spanning four."}]},{"type":"p","inline":[{"type":"bold","value":"Accept batch over real time."},{"type":"text","value":" Ask what breaks if this runs every hour instead of every second. Usually nothing does, and the architecture gets simpler."}]},{"type":"p","inline":[{"type":"bold","value":"Let a person handle the tail."},{"type":"text","value":" Routing the hardest five per cent to a human is not a failure. It is frequently the highest-return design decision in the whole project."}]},{"type":"p","inline":[{"type":"bold","value":"Own the infrastructure."},{"type":"text","value":" Running the automation in your own cloud account, with your own model provider contract, means no per-seat platform fee on top and no renegotiation when volume grows. It also means you can change supplier without changing systems."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"runningCosts":{"rich":[{"type":"h2","text":"What it costs to run, once it is live"},{"type":"p","inline":[{"type":"text","value":"Build cost is the number everyone asks about. Running cost is the number that surprises people, in both directions. It has three parts."}]},{"type":"p","inline":[{"type":"bold","value":"Model API spend."},{"type":"text","value":" Charged per token by whichever provider you use. Published prices change often and have fallen repeatedly, so we will not quote a figure that will be wrong within months. Estimate it directly: average tokens in and out per run, multiplied by your provider's current published rate, multiplied by expected monthly volume. Do this during the pilot on real traffic. For most internal back-office workflows it lands far below the cost of the hours it replaces."}]},{"type":"p","inline":[{"type":"bold","value":"Infrastructure."},{"type":"text","value":" Compute, storage, queues, logging. Ordinary cloud cost in your own account, usually modest for a single workflow. Running an open-weight model on your own hardware moves cost from per-token to per-hour, worth modelling if volume is high or data cannot leave your environment."}]},{"type":"p","inline":[{"type":"bold","value":"Maintenance."},{"type":"text","value":" APIs change, document formats change, and model behaviour changes when a provider ships a new version. Budget engineering time, either as a retainer or in-house. An eval suite makes maintenance cheap, because you learn something drifted from a failing test rather than a complaint."}]},{"type":"p","inline":[{"type":"text","value":"We ship a cost dashboard with every automation for this reason. You should see spend per workflow, per run, without asking an engineer."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"package":{"rich":[{"type":"h2","text":"The cheapest way to get your own number"},{"type":"p","inline":[{"type":"text","value":"Every band on this page is a market range. Your number is a specific figure that depends on your systems, your data and your exceptions."}]},{"type":"p","inline":[{"type":"text","value":"The "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":" exists to produce it. Two to three weeks, "},{"type":"bold","value":"typically €4,500–€6,000"},{"type":"text","value":". We sit with the people who run the process, map what actually happens, and return a ranked opportunity map: which workflows are worth automating, what each would cost, what each would return, and in what order."}]},{"type":"p","inline":[{"type":"text","value":"You own the deliverable. If the honest answer is that nothing here is worth automating yet, that is what it will say. You will have spent a few thousand euros to find that out instead of six figures."}]},{"type":"p","inline":[{"type":"bold","value":"CTA:"},{"type":"text","value":" Book an Operational Quick Scan "},{"type":"bold","value":"Reassurance:"},{"type":"text","value":" 45 minutes. No prep needed. You'll leave with two or three processes worth automating, whether or not you work with us."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What is the smallest useful project?","objection":"price","answerInline":[{"type":"text","value":"A process scan, "},{"type":"bold","value":"typically €4,500–€6,000"},{"type":"text","value":" over two to three weeks. Below that you are buying an opinion, not an assessment. If you already know exactly which workflow to automate and have clean system access, the "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":" at "},{"type":"bold","value":"€15,000–€25,000"},{"type":"text","value":" is the smallest thing that reaches production."}]},{"question":"Why quote in euros when we are a UK company?","objection":"other","answerInline":[{"type":"text","value":"We are an EU company and we contract in euros. Clients budget in sterling and pay in euros, or we agree a fixed sterling equivalent at signature so the number does not move mid-project. Either works, and neither changes the scope."}]},{"question":"Is a fixed price or time and materials better?","objection":"price","answerInline":[{"type":"text","value":"For a scoped pilot, fixed. You know the number, we carry the estimation risk, and the scope is small enough to define properly. For ongoing product work, a monthly team is honest and a fixed price is theatre. A "},{"type":"link","label":"dedicated senior engineer","href":"/ai-automation-agency-uk"},{"type":"text","value":" runs "},{"type":"bold","value":"€6,400–€8,000"},{"type":"text","value":" monthly and a pod of an architect plus two senior engineers "},{"type":"bold","value":"€22,000–€29,000"},{"type":"text","value":"."}]},{"question":"How does this compare to hiring someone?","objection":"price","answerInline":[{"type":"text","value":"An automation pilot is a one-off cost that keeps working. A hire is a recurring cost with recruitment time attached, and one person rarely covers engineering, integration and operations. That said, if you need continuous automation work for years, an internal team is the right answer and we will say so."}]},{"question":"What is the ongoing cost after the build?","objection":"after-launch","answerInline":[{"type":"text","value":"Model spend, infrastructure and maintenance. Model spend is metered per token by your provider and is usually the smallest of the three for internal workflows. Infrastructure runs in your own cloud account. Maintenance is either a retainer with us or time from your own engineers. We ship a cost dashboard so you can see the running number rather than estimate it."}]},{"question":"Do you charge for the scoping call?","objection":"price","answerInline":[{"type":"text","value":"No. The first call is free and produces a shortlist of processes worth looking at. The paid work starts at the scan, where we go into your systems and produce something written that you own."}]},{"question":"What if the scan says do not build anything?","objection":"other","answerInline":[{"type":"text","value":"Then it says that, and it is a good outcome. It has happened. The alternative is discovering the same thing four months into a build. An agency paid only to build is structurally unlikely to give you that answer, which is exactly why the scan is a separate, small, paid engagement."}]},{"question":"Can we start bigger than a pilot?","objection":"timeline","answerInline":[{"type":"text","value":"Yes, and some clients do. The "},{"type":"link","label":"Department Automation Sprint","href":"/packages/department-automation-sprint"},{"type":"text","value":" covers a whole function over ten to sixteen weeks, "},{"type":"bold","value":"typically €40,000–€65,000"},{"type":"text","value":". We only recommend starting there when a previous pilot has already proved the data and the integrations. Otherwise you are making every scoping decision blind."}]},{"question":"Do you need a long-term contract?","objection":"lock-in","answerInline":[{"type":"text","value":"No. Each engagement stands alone. You own the code, the prompts, the eval suites and the infrastructure config, and it runs in your cloud account. Some clients keep us on for the next workflow; plenty take it in house after the first pilot, and that is a fine outcome."}]},{"question":"What is not included in these numbers?","objection":"price","answerInline":[{"type":"text","value":"Third-party software licences, your own model provider spend, and your team's time. We are explicit about all three in a quote. We also exclude anything on the written exclusion list, which we agree in week two rather than discovering in week eight. You can see the full sequence in "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":"."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"close":{"heading":"Get your own number instead of a band","sub":"Two to three weeks, a written opportunity map you own, and an honest answer about whether anything here is worth building."}},"sourceFile":"7code-build/content/hub/what-ai-automation-costs-uk.mdx"}};
const HOME_CONTENT = {"spec":{"status":"approved","kind":"index","meta":{"slug":"","title":"AI-Native Software Engineering Partner | 7code","metaDescription":"We design, build and operate AI-native products end-to-end — LLM features, agent workflows and the cloud infrastructure behind them. Senior engineers, EU-based.","canonical":"https://www.7code.tech/","ogImage":"/og/home.jpg","ogImageDimensions":{"width":1200,"height":630},"locale":"en_GB"},"targeting":{"primaryKeyword":"ai native software engineering partner","secondaryKeywords":["ai engineering company","ai product development partner","llm development partner europe"],"icpSegment":"outstaffing","searchIntent":"navigational","flywheelStage":"reach","difficultyNote":"The homepage is not a money page. It is not optimised to rank for a commercial head term — the root-level money pages do that. Its job is to route four different buyers to four different pages in under one scroll, and to carry the entity-level trust signals that AI assistants read when asked who 7code is. Optimise it for brand queries and for Organization schema completeness.\n"},"cta":{"label":"Book a discovery call","action":"booking","href":"/book/discovery","reassurance":"30 minutes with an engineer, not a salesperson. If we're not the right fit we'll say so on the call."},"blocks":["hero","trustStrip","router","diagnosis","proof","cta","whyUs","packages","faq","testimonials","close"],"proof":[{"caseStudySlug":"hera","metric":"RAG-verified clinical AI intake — MVP shipped in 3 months","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"LLM & agent development","href":"/service/llm-agent-development"}]},{"caseStudySlug":"g42-fleet","metric":"Fleet platform deployed at EXPO 2020 scale — 2-year engagement","tags":[{"label":"AI product engineering","href":"/service/ai-product-engineering"},{"label":"Cloud & agentic infrastructure","href":"/service/cloud-agentic-infra"}]},{"caseStudySlug":"numerize","metric":"Platform running 6,000+ customer accounts","tags":[{"label":"System integrations","href":"/service/system-integrations"},{"label":"AI automation","href":"/service/ai-automation"}]}],"internalLinks":[{"anchor":"AI automation for operations","href":"/ai-automation-agency-uk","placement":"router"},{"anchor":"Build an AI product","href":"/ai-development-company-uk","placement":"router"},{"anchor":"Ship your first product","href":"/mvp-development-agency-uk","placement":"router"},{"anchor":"Add senior engineers","href":"/staff-augmentation-company-uk","placement":"router"},{"anchor":"AI agent development","href":"/ai-agent-development-company","placement":"whyUs"},{"anchor":"RAG development","href":"/rag-development-company","placement":"whyUs"},{"anchor":"AI consultancy","href":"/ai-consultancy-uk","placement":"whyUs"},{"anchor":"nearshore delivery from Romania","href":"/nearshore-software-development-uk","placement":"whyUs"},{"anchor":"Operational Quick Scan","href":"/packages/operational-quick-scan","placement":"packages"},{"anchor":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint","placement":"packages"},{"anchor":"Automation Pilot","href":"/packages/automation-pilot","placement":"packages"},{"anchor":"Department Automation Sprint","href":"/packages/department-automation-sprint","placement":"packages"},{"anchor":"how we work","href":"/process","placement":"faq"},{"anchor":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk","placement":"faq"}],"schema":{"service":false,"faqPage":true,"breadcrumbList":false,"organization":true,"aggregateRating":{"ratingValue":4.8,"reviewCount":11,"source":"https://clutch.co/profile/7code"}},"authorship":{"author":"Nicu Mardari","reviewer":"Nicu Mardari","published":"2026-08-04","updated":"2026-08-04"},"openItems":[]},"blocks":{"hero":{"h1":"AI-native software, engineered for production","sub":"We design, build and operate AI-native products end-to-end — LLM features, agent workflows, and the cloud infrastructure behind them. Senior engineers, based in the EU, shipping into the UK and Europe."},"trustStrip":{"stats":[{"value":"20+","label":"products delivered"},{"value":"8+ years","label":"engineering practice"},{"value":"4.8/5","label":"on Clutch, from 11 reviews"},{"value":"2–4 weeks","label":"from contract to a working team"}],"logos":["Lidl Romania","G42","Founders Factory","Life is Hard"]},"router":{"heading":"Start where you are","cards":[{"quote":"Our operations run on manual work.","body":"People rebuild the same reports, chase the same approvals, and re-key the same data between systems that will not talk to each other. You know it does not scale. Nobody has mapped it.","linkLabel":"AI automation for operations","href":"/ai-automation-agency-uk"},{"quote":"We have an idea and no engineering team.","body":"You have been quoted three wildly different numbers for the same product and cannot tell which quote is honest. You need someone to scope it properly before anyone builds anything.","linkLabel":"Ship your first product","href":"/mvp-development-agency-uk"},{"quote":"Our AI prototype works in the demo and breaks in production.","body":"It hallucinates on real data, nobody owns the eval suite, and the token bill is a surprise every month. You need engineers who have shipped this before, not another proof of concept.","linkLabel":"Build an AI product","href":"/ai-development-company-uk"},{"quote":"Our team is at capacity and hiring is too slow.","body":"Two roles have been open for five months and the roadmap slips a quarter at a time. You need senior people in your repo in weeks, without the headcount risk.","linkLabel":"Add senior engineers","href":"/staff-augmentation-company-uk"}]},"diagnosis":{"rich":[{"type":"h2","text":"Most AI projects do not fail on the technology"},{"type":"p","inline":[{"type":"text","value":"They fail earlier than that. Somebody picked a use case because it demoed well, not because the process behind it was understood. The pilot ran on clean sample data. Real data arrived and the whole thing fell over."}]},{"type":"p","inline":[{"type":"text","value":"The second most common failure is quieter. The feature works, ships, and then slowly degrades — because no one built an eval set, no one is watching the traces, and no one can tell you what a single run costs. By the time a customer complains, it has been wrong for weeks."}]},{"type":"p","inline":[{"type":"text","value":"We treat both as engineering problems, because they are. Map the process first. Test on real data before anyone commits budget. Ship the evals, guardrails, tracing and cost dashboards with the feature, not in a phase two that never happens."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"proof":{"rich":[{"type":"h2","text":"Work we can talk about"},{"type":"p","inline":[{"type":"bold","value":"Hera Health Tech"},{"type":"text","value":" — clinical onboarding that took days now takes minutes, built as a RAG-verified intake flow with a human review step. MVP shipped in three months. "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"LLM & agent development","href":"/service/llm-agent-development"},{"type":"text","value":" → "},{"type":"link","label":"Read the case study","href":"/case-study/hera"}]},{"type":"p","inline":[{"type":"bold","value":"G42"},{"type":"text","value":" — a fleet platform deployed at EXPO 2020 scale, over a two-year engagement. "},{"type":"link","label":"AI product engineering","href":"/service/ai-product-engineering"},{"type":"text","value":" · "},{"type":"link","label":"Cloud & agentic infrastructure","href":"/service/cloud-agentic-infra"},{"type":"text","value":" → "},{"type":"link","label":"Read the case study","href":"/case-study/g42-fleet"}]},{"type":"p","inline":[{"type":"bold","value":"Numerize"},{"type":"text","value":" — an operational platform now running 6,000+ customer accounts, integrating systems that previously needed manual reconciliation. "},{"type":"link","label":"System integrations","href":"/service/system-integrations"},{"type":"text","value":" · "},{"type":"link","label":"AI automation","href":"/service/ai-automation"},{"type":"text","value":" → "},{"type":"link","label":"Read the case study","href":"/case-study/numerize"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"cta":{"rich":[{"type":"p","inline":[{"type":"text","value":"Book a discovery call"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"whyUs":{"rich":[{"type":"h2","text":"Why teams pick us over the alternatives"},{"type":"p","inline":[{"type":"text","value":"Most clients arrive stuck between two bad options. Freelancers are fast and cheap until the work needs more than one person or has to survive contact with production. Large outsourcing firms are reliable and slow, and the engineers who show up are not the ones who were in the pitch."}]},{"type":"p","inline":[{"type":"text","value":"We sit in between, deliberately."}]},{"type":"ul","items":[[{"type":"bold","value":"Senior engineers only."},{"type":"text","value":" The person in your first call is the person who builds it. No account manager layer, no handover to juniors after signature."}],[{"type":"bold","value":"AI-native depth, not an AI page."},{"type":"text","value":" "},{"type":"link","label":"Agent development","href":"/ai-agent-development-company"},{"type":"text","value":", "},{"type":"link","label":"RAG systems","href":"/rag-development-company"},{"type":"text","value":", evals, prompt management, observability — shipped, not prototyped."}],[{"type":"bold","value":"You own everything."},{"type":"text","value":" Code, prompts, eval suites, infrastructure config, documentation. In your repo, in your cloud account. Model agnostic, so you are not tied to one AI vendor either."}],[{"type":"bold","value":"EU delivery, UK hours."},{"type":"text","value":" "},{"type":"link","label":"Nearshore delivery from Romania","href":"/nearshore-software-development-uk"},{"type":"text","value":" overlaps the UK working day almost entirely. Data stays in the EEA by default."}],[{"type":"bold","value":"2–4 weeks from contract to a working team"},{"type":"text","value":", because we do not start recruiting after you sign."}],[{"type":"bold","value":"We will tell you not to build it."},{"type":"text","value":" If the honest answer is that a project is not worth doing yet, you get that answer — from us, in writing, early. Ask us about "},{"type":"link","label":"AI consultancy","href":"/ai-consultancy-uk"},{"type":"text","value":" if the decision is what you actually need help with."}]]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"packages":{"rich":[{"type":"h2","text":"Fixed-scope ways to start"},{"type":"p","inline":[{"type":"text","value":"You do not have to commit to a build to work with us. Most engagements begin with one of these."}]},{"type":"table","rows":[[[{"type":"text","value":"Package"}],[{"type":"text","value":"Duration"}],[{"type":"text","value":"Typically"}]],[[{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":" — process audit + automation opportunity map + ROI estimate"}],[{"type":"text","value":"2–3 weeks"}],[{"type":"text","value":"€4,500 – €6,000"}]],[[{"type":"link","label":"AI-Ready Ops Blueprint","href":"/packages/ai-ready-ops-blueprint"},{"type":"text","value":" — architecture, data readiness, prioritised use-case roadmap"}],[{"type":"text","value":"4–6 weeks"}],[{"type":"text","value":"€9,000 – €14,000"}]],[[{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":" — one or two workflows automated end-to-end, in production"}],[{"type":"text","value":"6–10 weeks"}],[{"type":"text","value":"€15,000 – €25,000"}]],[[{"type":"link","label":"Department Automation Sprint","href":"/packages/department-automation-sprint"},{"type":"text","value":" — a full department digitalised"}],[{"type":"text","value":"10–16 weeks"}],[{"type":"text","value":"€40,000 – €65,000"}]]]},{"type":"p","inline":[{"type":"text","value":"What moves the number is the count of systems involved and the state of your data. We break it down per workflow before you commit, so anything that does not pay for itself can be dropped."}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"faq":[{"question":"What does an engagement typically cost?","objection":"price","answerInline":[{"type":"text","value":"It depends on scope, but the bands are published rather than hidden. A process audit and opportunity map, the "},{"type":"link","label":"Operational Quick Scan","href":"/packages/operational-quick-scan"},{"type":"text","value":", is typically €4,500–€6,000. A single workflow automated end to end, an "},{"type":"link","label":"Automation Pilot","href":"/packages/automation-pilot"},{"type":"text","value":", typically runs €15,000–€25,000. A production MVP is usually €40,000–€90,000, and a clickable prototype with a validated scope starts from €8,000. A dedicated senior engineer is €6,400–€8,000 a month, an architect €9,600–€12,800. More detail in "},{"type":"link","label":"what AI automation costs","href":"/hub/what-ai-automation-costs-uk"},{"type":"text","value":"."}]},{"question":"How quickly can you start?","objection":"timeline","answerInline":[{"type":"text","value":"Two to four weeks from signed contract to a working team. We do not start recruiting after you sign, which is why the number is that low and why it is the same number we quoted last year."}]},{"question":"Who will actually be doing the work?","objection":"seniority","answerInline":[{"type":"text","value":"Senior engineers, and the same ones throughout. You can meet them before you commit — ask, and we would rather you did. There is no account manager between you and the people building."}]},{"question":"Where are you based, and does that matter?","objection":"other","answerInline":[{"type":"text","value":"Cluj-Napoca, Romania. We are an EU company delivering into the UK, Ireland, the Nordics, Benelux and DACH. The practical effects: your working day and ours overlap almost entirely, your data stays inside the EEA by default, and a DPA is standard paperwork rather than a negotiation."}]},{"question":"Do we own the code?","objection":"ip-ownership","answerInline":[{"type":"text","value":"Yes, transferring on full payment, including anything built on top of our own internal tooling. It runs in your repo and your cloud account, documented so another team can pick it up."}]},{"question":"Will we be locked into you, or into an AI vendor?","objection":"lock-in","answerInline":[{"type":"text","value":"Neither. Everything is handed over documented and runnable. We are model agnostic — GPT, Claude, Gemini, or an open-weight model in your own environment — and we choose per use case and per data-sensitivity requirement, not per vendor relationship."}]},{"question":"We tried AI before and it did not work. Why would this be different?","objection":"failed-before","answerInline":[{"type":"text","value":"Most failures we are called in to fix have the same cause: a use case chosen because it demoed well, before anyone understood the process behind it. We map first and test on your real data before you commit to a build. If it will not work, you find out in week two rather than month six."}]},{"question":"Do you only do AI work?","objection":"other","answerInline":[{"type":"text","value":"No. A good share of what we do is ordinary, careful product engineering and integration work with AI in one part of it. Sometimes the honest answer is that the AI is not the interesting bit — fixing one integration so two systems finally agree is where the return is. We will say so."}]},{"question":"What happens after launch?","objection":"after-launch","answerInline":[{"type":"text","value":"Every AI feature ships with a test set, guardrails, traces and a cost dashboard, so your team can see it working and see it drift. Support retainers are available and optional. If you want to run it yourself from day one, the handover assumes exactly that."}]},{"question":"How do we know you are any good?","objection":"other","answerInline":[{"type":"text","value":"Ask us what went wrong on a past project — a firm that gets uncomfortable with that question is telling you something. Then ask to speak to a client. Our Clutch reviews are public and named, and you can see "},{"type":"link","label":"how we work","href":"/process"},{"type":"text","value":" before you talk to us."},{"type":"text","value":" "},{"type":"text","value":"---"}]}],"testimonials":{"rich":[{"type":"p","inline":[{"type":"text","value":"*Named, with company. All four are public on Clutch.*"}]},{"type":"ul","items":[[{"type":"bold","value":"Emily Kucharski"},{"type":"text","value":" — CEO & Co-founder, WholeSum"}],[{"type":"bold","value":"Evyn White"},{"type":"text","value":" — Co-founder, Hera Health Tech"}],[{"type":"bold","value":"Paul Egan"},{"type":"text","value":" — CTO, Founders Factory"}],[{"type":"bold","value":"Marcel Ionescu"},{"type":"text","value":" — CTO"}]]},{"type":"p","inline":[{"type":"text","value":"*Implementation note: pull the quote text from the live Clutch profile at build time or paste it in verbatim. Do not paraphrase a review.*"}]},{"type":"p","inline":[{"type":"text","value":"---"}]}]},"close":{"heading":"Tell us what you are trying to build","sub":"Thirty minutes with an engineer. Bring the problem, not a spec — we will tell you what we would do and roughly what it costs."}},"sourceFile":"7code-build/content/pages/home.mdx"};

